// Connection lifecycle stages reported by the controller for each device.
enum ConnectivityState {
    CONNECTIVITY_UNKNOWN     = 0;  // registered but no connection attempt yet
    CONNECTIVITY_DISCOVERING = 1;  // operational mDNS/DNS-SD lookup + CASE in progress
    CONNECTIVITY_SUBSCRIBED  = 2;  // active Matter subscription
    CONNECTIVITY_RETRYING    = 3;  // connection failed, retry timer active
}

