/*
 * Flux Controller — commission-then-handoff device commissioning (see flux_commission.h)
 *
 * Discovers a device over Thread by discriminator (commissionable DNS-SD),
 * PASEs with the request passcode, and commissions it onto the controller's
 * own fabric. Device NOC signing is handled transparently by the custom
 * credentials issuer (flux_creds_issuer) installed in flux_bootstrap_fabric();
 * this file only drives discovery + PairDevice + the pairing/commissioning
 * delegate callbacks.
 *
 * Modeled on the on-network commissioning that existed before the app-owned-
 * fabric pivot (see git history of flux_controller.cpp pre-8ab43f7), updated
 * for discriminator-filtered discovery instead of full setup-code parsing
 * (the phone already has the passcode + discriminator from the ECM window).
 */

#include "flux_commission.h"
#include "flux_state.h"
#include "flux_controller.h"   /* FLUX_BACKBONE_IFKEY */
#include "flux_async.h"

#include <esp_log.h>
#include <esp_timer.h>
#include <esp_netif.h>
#include <esp_netif_net_stack.h>   /* esp_netif_get_netif_impl */
#include <lwip/netif.h>
#include <esp_matter_controller_client.h>

#include <controller/CHIPDeviceController.h>
#include <credentials/attestation_verifier/DeviceAttestationDelegate.h>
#include <lib/dnssd/Types.h>
#include <transport/raw/PeerAddress.h>

#include <freertos/FreeRTOS.h>
#include <freertos/semphr.h>

#include <inttypes.h>
#include <new>
#include <stdio.h>
#include <string.h>

using namespace chip;
using namespace esp_matter::controller;

namespace {

constexpr char TAG[] = "flux_commission";

/* The controller has no local PAA trust store. The phone already performed
 * full DAC/PAA attestation during its Pass-1 BLE commissioning, so the
 * controller's own commissioning pass does not need to repeat that check. */
class PermissiveAttestationDelegate : public chip::Credentials::DeviceAttestationDelegate {
public:
    chip::Optional<uint16_t> FailSafeExpiryTimeoutSecs() const override { return chip::NullOptional; }
    void OnDeviceAttestationCompleted(
        chip::Controller::DeviceCommissioner *commissioner,
        chip::DeviceProxy                   *device,
        const chip::Credentials::DeviceAttestationVerifier::AttestationDeviceInfo &,
        chip::Credentials::AttestationVerificationResult result) override
    {
        ESP_LOGW(TAG, "attestation result=%u — bypassing (phone already verified in Pass 1)",
                 (unsigned)result);
        commissioner->ContinueCommissioningAfterDeviceAttestation(
            device, chip::Credentials::AttestationVerificationResult::kSuccess);
    }
};
PermissiveAttestationDelegate s_attest_delegate;

/* Context shared between flux_commission_device() (CoAP task, blocks) and the
 * CHIP-task callbacks below. Only one commission runs at a time. */
struct CommissionCtx {
    uint32_t passcode;
    uint16_t discriminator;   /* filtered client-side in OnDiscoveredDevice */
    chip::NodeId node_id;
    char     error[256];
    bool     ok;
    flux_async_t async;       /* bounded wait + abandonment + single-owner free */
};
CommissionCtx *s_ctx = nullptr;

/* Idempotency cache. A /commission request is not idempotent but can legitimately
 * be repeated (CoAP retransmit while the long commission is in flight, app resend,
 * user re-scan). Re-running PASE against a device whose ECM window has since closed
 * fails and masks the original success. Remember the last successful commission for
 * a short window and replay its result for a repeated request to the same address. */
constexpr int64_t kCommissionCacheTtlUs = 30 * 1000 * 1000; /* 30 s */
struct LastCommission {
    char     address[46];
    uint64_t node_id;
    uint64_t fabric_id;
    int64_t  when_us;  /* esp_timer_get_time() at success; 0 = none cached */
};
LastCommission s_last = {};

void finish(bool ok, const char *error)
{
    CommissionCtx *ctx = s_ctx;
    if (!ctx) return;                /* already finished (idempotent) */
    ctx->ok = ok;

