extern "C" esp_err_t flux_commission_device(
    uint32_t passcode, uint32_t discriminator, uint64_t requested_node_id,
    const char *device_address, uint16_t device_port,
    uint64_t *out_node_id, uint64_t *out_fabric_id,
    char *error_buf, size_t error_buf_len)
{
    if (passcode == 0) {
        snprintf(error_buf, error_buf_len, "passcode is required");
        return ESP_ERR_INVALID_ARG;
    }

    /* Idempotency: replay the last successful commission for a repeated request
     * to the same device within a short window, instead of re-running PASE
     * against a now-closed window (which fails and masks the original success). */
    if (device_address && device_address[0] != '\0' && s_last.when_us != 0 &&
        strncmp(device_address, s_last.address, sizeof(s_last.address)) == 0 &&
        (esp_timer_get_time() - s_last.when_us) < kCommissionCacheTtlUs) {
        ESP_LOGW(TAG, "duplicate /commission for %s — replaying cached result (node=%016" PRIX64 ")",
                 device_address, s_last.node_id);
        *out_node_id   = s_last.node_id;
        *out_fabric_id = s_last.fabric_id;
        return ESP_OK;
    }

    /* Only one commission at a time: s_ctx is still set while a prior attempt is
     * in flight (or abandoned-but-not-yet-cleaned after a timeout). Reject rather
     * than clobber s_ctx, which would orphan the in-flight context. */
    if (s_ctx != nullptr) {
        snprintf(error_buf, error_buf_len, "commission already in progress");
        return ESP_ERR_INVALID_STATE;
    }

    chip::NodeId node_id = requested_node_id ? requested_node_id : flux_state_alloc_node_id();

    auto *ctx = new (std::nothrow) CommissionCtx{};
    if (!ctx) { snprintf(error_buf, error_buf_len, "oom"); return ESP_ERR_NO_MEM; }
    if (!flux_async_init(&ctx->async)) {
        delete ctx; snprintf(error_buf, error_buf_len, "oom"); return ESP_ERR_NO_MEM;
    }
    s_ctx = ctx;

    auto *w = new (std::nothrow) CommissionWorkCtx{};
    if (w) {
        w->passcode      = passcode;
        w->discriminator = discriminator;
        w->node_id       = node_id;
        snprintf(w->address, sizeof(w->address), "%s", device_address ? device_address : "");
        w->port          = device_port;
    }
    if (!w) {
        s_ctx = nullptr;
        flux_async_deinit(&ctx->async); delete ctx;
        snprintf(error_buf, error_buf_len, "oom");
        return ESP_ERR_NO_MEM;
    }

    CHIP_ERROR cerr = chip::DeviceLayer::PlatformMgr().ScheduleWork(
        commission_work, reinterpret_cast<intptr_t>(w));
    if (cerr != CHIP_NO_ERROR) {
        delete w;
        s_ctx = nullptr;
        flux_async_deinit(&ctx->async); delete ctx;
        snprintf(error_buf, error_buf_len, "ScheduleWork: %s", cerr.AsString());
        return ESP_FAIL;
    }

    /* Discovery + PASE + full commissioning (incl. AddNOC + the final operational
     * CASE for CommissioningComplete) can take well over a minute on a Thread mesh:
     * the device often promotes to a Thread router right after AddNOC, and the
     * operational DNS-SD resolve can time out (~45s) and retry while it settles.
     * CHIP re-arms the device fail-safe to 120s for that, so we wait to match
     * rather than abandoning a commission that is still progressing. */
    if (!flux_async_wait(&ctx->async, 120000)) {
        /* Timed out — ownership was handed to finish(), which frees ctx when the
         * still-pending commission eventually completes. */
        snprintf(error_buf, error_buf_len, "commission timed out");

        chip::DeviceLayer::PlatformMgr().ScheduleWork(
            [](intptr_t arg) {
                auto nid = static_cast<chip::NodeId>(arg);
                auto &ci = matter_controller_client::get_instance();
                CHIP_ERROR e = ci.get_commissioner()->StopPairing(nid);
                ci.get_commissioner()->RegisterPairingDelegate(nullptr);
                ci.get_commissioner()->RegisterDeviceDiscoveryDelegate(nullptr);
                ESP_LOGW(TAG, "post-timeout cleanup for %016" PRIX64 ": StopPairing=%s",
                         nid, e.AsString());
            },
            static_cast<intptr_t>(node_id));
        return ESP_ERR_TIMEOUT;
    }

    bool ok = ctx->ok;
    if (!ok) snprintf(error_buf, error_buf_len, "%s", ctx->error);
    flux_async_deinit(&ctx->async);
    delete ctx;

    if (!ok) return ESP_FAIL;

    *out_node_id = (uint64_t)node_id;
    /* The committed FabricTable fabric is the single source of truth (see
     * flux_controller_sync_raw_fabric_id) — read it back rather than trusting
     * any cached value, so this always matches what /info reports. */
    *out_fabric_id = flux_state_get_raw_fabric_id();

    /* Cache this success so a retried request for the same device replays the
     * result instead of re-commissioning a closed window (see guard above). */
    if (device_address && device_address[0] != '\0') {
        snprintf(s_last.address, sizeof(s_last.address), "%s", device_address);
        s_last.node_id   = *out_node_id;
        s_last.fabric_id = *out_fabric_id;
        s_last.when_us   = esp_timer_get_time();
    }
    return ESP_OK;
}

