/* ── Handler: POST /commission ───────────────────────────────────────────── */
/* Commission-then-handoff (see flux_commission.h / docs/multiadmin-rework.md).
 * The phone has already BLE-commissioned the device onto a throwaway fabric and
 * opened an ECM commissioning window; it hands us the window's passcode +
 * discriminator and we commission the device onto our own fabric directly. */

/* Commissioning can take up to ~2 min (PASE + AddNOC + the device's Thread
 * router promotion + the operational CASE for CommissioningComplete). Blocking
 * the single CoAP task that long would stall every other request and force the
 * client to retransmit (each retransmit spawning a duplicate commission). So we
 * use a CoAP **separate response**: the handler returns an empty ACK immediately
 * (libcoap does this when the response code is left at 0), a worker task runs the
 * blocking commission off the CoAP task, and the real reply is sent later from
 * the notify-queue drain (flux_coap_drain_notify_queue), on the CoAP task. */
typedef struct {
    coap_session_t *session;   /* referenced; released when the reply is sent  */
    uint8_t  token[8];
    size_t   token_len;
    uint32_t passcode;
    uint32_t discriminator;
    uint64_t req_node_id;
    char     device_address[46];
    uint32_t device_port;
    uint32_t vendor_id;
    uint32_t product_id;
    uint32_t device_type;
    char     name[40];
} commission_job_t;

static void commission_worker(void *arg)
{
    commission_job_t *job = (commission_job_t *)arg;

    uint64_t node_id = 0, fabric_id = 0;
    char     error_buf[160] = "";
    esp_err_t err = flux_commission_device(
        job->passcode, job->discriminator, job->req_node_id,
        job->device_address, (uint16_t)job->device_port,
        &node_id, &fabric_id, error_buf, sizeof(error_buf));

    notify_t *n = (notify_t *)calloc(1, sizeof(notify_t));
    if (n) {
        n->type          = NOTIFY_TYPE_COMMISSION_RESULT;
        n->cm_session    = job->session;
        n->cm_token_len  = job->token_len;
        if (job->token_len) memcpy(n->cm_token, job->token, job->token_len);
        n->cm_success    = (err == ESP_OK);
        n->node_id       = node_id;
        n->cm_fabric_id  = fabric_id;
        n->cm_vendor_id  = job->vendor_id;
        n->cm_product_id = job->product_id;
        n->cm_device_type= job->device_type;
        if (job->name[0] != '\0')
            snprintf(n->cm_name, sizeof(n->cm_name), "%s", job->name);
        else
            snprintf(n->cm_name, sizeof(n->cm_name), "Device %04llX",
                     (unsigned long long)(node_id & 0xFFFF));
        if (err != ESP_OK)
            snprintf(n->cm_error, sizeof(n->cm_error), "%s", error_buf);

        if (xQueueSend(flux_coap_notify_queue, &n, 0) != pdTRUE) {
            /* Queue full (≈never): the deferred reply is lost and the session
             * ref leaks (coap_session_release must run on the CoAP task). The
             * app times out and retries; the controller cache then replays. */
            ESP_LOGW(TAG, "notify queue full — dropping commission reply for %016llx",
                     (unsigned long long)node_id);
            free(n);
        }
    } else {
        ESP_LOGE(TAG, "oom building commission reply");
    }

    free(job);
    vTaskDelete(NULL);
}

void hnd_commission_post(coap_resource_t *resource,
                         coap_session_t  *session,
                         const coap_pdu_t *request,
                         const coap_string_t *query,
                         coap_pdu_t       *response)
{
    uint8_t *body; size_t body_len;
    if (!read_body(request, &body, &body_len)) {
        send_status(resource, session, request, response, 1, "no body");
        return;
    }

    flux_CommissionRequest msg = flux_CommissionRequest_init_zero;
    pb_istream_t is = pb_istream_from_buffer(body, body_len);
    bool decoded = pb_decode(&is, flux_CommissionRequest_fields, &msg);
    free(body);

    if (!decoded || msg.passcode == 0) {
        send_status(resource, session, request, response, 1,
                    "decode failed or missing passcode");
        return;
    }

    commission_job_t *job = (commission_job_t *)calloc(1, sizeof(*job));
    if (!job) {
        send_status_ex(resource, session, request, response,
                       COAP_RESPONSE_CODE_INTERNAL_ERROR, 1, "oom");
        return;
    }

    coap_bin_const_t tok = coap_pdu_get_token(request);
    job->token_len = tok.length > sizeof(job->token) ? sizeof(job->token) : tok.length;
    if (job->token_len) memcpy(job->token, tok.s, job->token_len);
    job->passcode      = msg.passcode;
    job->discriminator = msg.discriminator;
    job->req_node_id   = msg.node_id;
    snprintf(job->device_address, sizeof(job->device_address), "%s", msg.device_address);
    job->device_port   = msg.device_port;
    job->vendor_id     = msg.vendor_id;
    job->product_id    = msg.product_id;
    job->device_type   = msg.device_type;
    snprintf(job->name, sizeof(job->name), "%s", msg.name);

    /* Keep the session alive across the (long) commission; released after the
     * deferred reply is sent in flux_coap_drain_notify_queue(). */
    job->session = coap_session_reference(session);

    if (xTaskCreate(commission_worker, "cm_worker", 4096, job, 5, NULL) != pdPASS) {
        ESP_LOGE(TAG, "failed to spawn commission worker");
        coap_session_release(job->session);
        free(job);
        send_status_ex(resource, session, request, response,
                       COAP_RESPONSE_CODE_SERVICE_UNAVAILABLE, 1, "busy");
        return;
    }

    /* Leave `response` untouched (code 0): libcoap sends an empty ACK now and
     * the worker delivers the real reply later (CoAP separate response). */
}

