void commission_work(intptr_t arg)
{
    auto *w = reinterpret_cast<CommissionWorkCtx *>(arg);
    auto &ci = matter_controller_client::get_instance();
    auto *commissioner = ci.get_commissioner();

    /* Clear a stale delegate left by a previous timed-out attempt — PairDevice
     * (via DiscoverCommissionableNodes) refuses to start a second pairing
     * process while one is still registered. */
    if (commissioner->GetPairingDelegate() != nullptr) {
        ESP_LOGW(TAG, "clearing stale pairing delegate before new commission");
        commissioner->RegisterPairingDelegate(nullptr);
        commissioner->RegisterDeviceDiscoveryDelegate(nullptr);
    }

    s_ctx->passcode      = w->passcode;
    s_ctx->node_id       = w->node_id;
    s_ctx->discriminator = (uint16_t)w->discriminator;
    char     addr_str[46];
    snprintf(addr_str, sizeof(addr_str), "%s", w->address);
    uint16_t addr_port = w->port;
