     * directly. The controller's own DNS-SD discovery cannot identify the device
     * — the OTBR's SRP->mDNS proxy strips the discriminator/CM TXT on the local
     * query, so records resolve as disc=0 cm=0. */
    if (addr_str[0] != '\0') {
        chip::Inet::IPAddress addr;
        if (!chip::Inet::IPAddress::FromString(addr_str, addr)) {
            finish(false, "invalid device_address");
            return;
        }
        uint16_t p = addr_port ? addr_port : 5540;
        /* A link-local device_address (fe80::..) is only routable when scoped to
         * a local interface. The phone hands us the address with ITS own zone
         * (e.g. %wlan0), which is meaningless here and is dropped during parsing,
         * leaving a zoneless link-local that SendMessage() rejects with ERR_RTE.
         * Re-scope it to the controller's backbone (Ethernet) netif, which shares
         * the LAN link with the device. Routable (global/ULA) addresses need no
         * interface. Mirrors the self-discovery path in OnDiscoveredDevice(). */
        chip::Inet::InterfaceId ifc = chip::Inet::InterfaceId::Null();
        if (addr.IsIPv6LinkLocal()) {
            esp_netif_t *bb = esp_netif_get_handle_from_ifkey(FLUX_BACKBONE_IFKEY);
            struct netif *bb_netif =
                bb ? static_cast<struct netif *>(esp_netif_get_netif_impl(bb)) : nullptr;
            if (bb_netif != nullptr) {
                ifc = chip::Inet::InterfaceId(bb_netif);
            } else {
                ESP_LOGW(TAG, "link-local device_address but backbone netif %s "
                              "unavailable — PASE send will likely fail",
                         FLUX_BACKBONE_IFKEY);
            }
        }
        chip::Transport::PeerAddress peer =
            chip::Transport::PeerAddress::UDP(addr, p, ifc);
        chip::RendezvousParameters params =
            chip::RendezvousParameters().SetSetupPINCode(s_ctx->passcode).SetPeerAddress(peer);
        chip::Controller::CommissioningParameters cparams;
        cparams.SetDeviceAttestationDelegate(&s_attest_delegate);
        ESP_LOGI(TAG, "PASE direct to [%s]:%u iface=%s (skipping DNS-SD)", addr_str,
                 (unsigned)p, addr.IsIPv6LinkLocal() ? FLUX_BACKBONE_IFKEY : "none");
        CHIP_ERROR err = commissioner->PairDevice(s_ctx->node_id, params, cparams);
        if (err != CHIP_NO_ERROR) {
            char buf[128];
            snprintf(buf, sizeof(buf), "PairDevice: %s", err.AsString());
            ESP_LOGE(TAG, "%s", buf);
            finish(false, buf);
        }
        return;
    }

    /* Fallback (no address supplied): browse all commissionable nodes (kNone) and
     * match the discriminator in OnDiscoveredDevice. Discriminator-subtype
     * discovery (kLongDiscriminator) fails over the OTBR because the SRP->mDNS
     * proxy omits the L<disc> subtype PTR. */
    commissioner->RegisterDeviceDiscoveryDelegate(&s_delegate);
    chip::Dnssd::DiscoveryFilter filter(chip::Dnssd::DiscoveryFilterType::kNone);
    CHIP_ERROR disc_err = commissioner->DiscoverCommissionableNodes(filter);
    if (disc_err != CHIP_NO_ERROR) {
        commissioner->RegisterDeviceDiscoveryDelegate(nullptr);
        commissioner->RegisterPairingDelegate(nullptr);
        char buf[128];
        snprintf(buf, sizeof(buf), "DiscoverCommissionableNodes: %s", disc_err.AsString());
        ESP_LOGE(TAG, "%s", buf);
        finish(false, buf);
    }
}

toolUseResult.newString:
    commissioner->RegisterPairingDelegate(&s_delegate);

    /* Own-mesh first: the SRP server table is the authoritative source for
     * devices on our Thread network (full TXT — the mDNS echo of our own
     * registrations is stripped by the OTBR's advertising proxy). */
    if (try_srp_commission()) return;

    /* LAN path: browse all commissionable nodes (kNone) and match the
     * discriminator in OnDiscoveredDevice. Catches Wi-Fi/Ethernet devices and
     * Thread devices proxied by another ecosystem's border router (direct
     * handover of a shared code). Discriminator-subtype discovery
     * (kLongDiscriminator) is avoided because our own OTBR proxy omits the
     * L<disc> subtype PTR. */
    commissioner->RegisterDeviceDiscoveryDelegate(&s_delegate);
    chip::Dnssd::DiscoveryFilter filter(chip::Dnssd::DiscoveryFilterType::kNone);
    CHIP_ERROR disc_err = commissioner->DiscoverCommissionableNodes(filter);
    if (disc_err != CHIP_NO_ERROR) {
        commissioner->RegisterDeviceDiscoveryDelegate(nullptr);
        commissioner->RegisterPairingDelegate(nullptr);
        char buf[128];
        snprintf(buf, sizeof(buf), "DiscoverCommissionableNodes: %s", disc_err.AsString());
        ESP_LOGE(TAG, "%s", buf);
        finish(false, buf);
        return;
    }

    /* Keep re-checking the SRP table while the browse runs — an own-mesh
     * device's window registration may land moments after this request. */
    chip::DeviceLayer::SystemLayer().StartTimer(
        chip::System::Clock::Milliseconds32(2000), srp_poll_cb, nullptr);
}

