1	import 'dart:async';
2	
3	import 'package:fixnum/fixnum.dart';
4	import 'package:matter_home/models/commission_models.dart';
5	import 'package:matter_home/models/device_type.dart';
6	import 'package:matter_home/models/fabric_descriptor.dart';
7	import 'package:matter_home/models/matter_device.dart';
8	import 'package:matter_home/models/share_result.dart';
9	import 'package:matter_home/models/wifi_network.dart';
10	import 'package:matter_home/providers/device_provider.dart';
11	import 'package:matter_home/services/device_store.dart';
12	import 'package:matter_home/services/flux_coap_service.dart';
13	import 'package:matter_home/services/matter_port.dart';
14	import 'package:matter_home/services/proto/flux.pb.dart' as $proto;
15	import 'matter_fakes.dart' show FakeMatterPort;
16	
17	/// ── FakeMatterCommissionPort ────────────────────────────────────────────────
18	///
19	/// Drop-in [MatterCommissionPort] for CommissioningController tests.
20	///
21	/// Exposes a controllable [commissionEvents] stream, records every call with
22	/// its arguments, and returns canned results.  The optional [onCommission]
23	/// hook runs *inside* the commission* methods, so a test can emit events (e.g.
24	/// CREDENTIALS_NEEDED) and wait for the controller to react before the
25	/// commission future completes.
26	class FakeMatterCommissionPort implements MatterCommissionPort {
27	  final _events = StreamController<String>.broadcast();
28	
29	  /// Pushes a progress line onto [commissionEvents] (as the native layer would).
30	  void emit(String event) => _events.add(event);
31	
32	  // ── Configurable results ──────────────────────────────────────────────────
33	  ParsedPayload? parsedResult;
34	  CommissionResult commissionResult = CommissionResult.ok(nodeId: 0x1234, deviceTypeId: 0x0101);
35	
36	  /// ECM window result returned by [openCommissioningWindow] (null = failure).
37	  ShareDeviceResult? windowResult = const ShareDeviceResult(
38	      qrCodePayload: 'MT:FAKE', manualPairingCode: '00000000000',
39	      passcode: 0x4D2, discriminator: 0x2A);
40	
41	  /// Fabrics returned by [readFabrics] (the post-handoff safety gate).
42	  List<FabricDescriptor>? fabricsResult;
43	
44	  /// Result of [removeFabric].
45	  bool removeFabricResult = true;
46	
47	  /// Invoked inside commissionDevice / commissionViaIp / commissionViaCode.
48	  Future<void> Function()? onCommission;
49	
50	  // ── Recorded calls ────────────────────────────────────────────────────────
51	  int parseCallCount = 0;
52	  int commissionDeviceCalls = 0;
53	  int commissionViaIpCalls = 0;
54	  int commissionViaCodeCalls = 0;
55	  int openWindowCalls = 0;
56	  int readFabricsCalls = 0;
57	  final List<({int nodeId, int fabricIndex})> removeFabricCalls = [];
58	
59	  String? lastWifiSsid;
60	  String? lastWifiPassword;
61	  String? lastThreadDatasetHex;
62	  String? lastIpAddress;
63	  int? lastDiscriminator;
64	  int? lastSetupPinCode;
65	
66	  // provideCredentials capture + a future tests can await.
67	  int provideCredentialsCalls = 0;
68	  String? providedSsid;
69	  String? providedPassword;
70	  String? providedThreadDatasetHex;
71	  final Completer<void> provideCredentialsCalled = Completer<void>();
72	
73	  @override
74	  Stream<String> get commissionEvents => _events.stream;
75	
76	  @override
77	  Future<ParsedPayload?> parsePayload(String payload) async {
78	    parseCallCount++;
79	    return parsedResult;
80	  }
81	
82	  @override
83	  Future<CommissionResult> commissionDevice(
84	    String payload, {
85	    String? wifiSsid,
86	    String? wifiPassword,
87	    String? threadDatasetHex,
88	  }) async {
89	    commissionDeviceCalls++;
90	    lastWifiSsid = wifiSsid;
91	    lastWifiPassword = wifiPassword;
92	    lastThreadDatasetHex = threadDatasetHex;
93	    if (onCommission != null) await onCommission!();
94	    return commissionResult;
95	  }
96	
97	  @override
98	  Future<CommissionResult> commissionViaIp({
99	    required String ipAddress,
100	    required int discriminator,
101	    required int setupPinCode,
102	    int port = 5540,
103	  }) async {
104	    commissionViaIpCalls++;
105	    lastIpAddress = ipAddress;
106	    lastDiscriminator = discriminator;
107	    lastSetupPinCode = setupPinCode;
108	    if (onCommission != null) await onCommission!();
109	    return commissionResult;
110	  }
111	
112	  @override
113	  Future<CommissionResult> commissionViaCode({required String setupCode}) async {
114	    commissionViaCodeCalls++;
115	    if (onCommission != null) await onCommission!();
116	    return commissionResult;
117	  }
118	
119	  @override
120	  Future<List<WifiNetwork>> scanWifiNetworks() async => const [];
121	
122	  @override
123	  Future<void> provideCredentials({
124	    String? ssid,
125	    String? password,
126	    String? threadDatasetHex,
127	  }) async {
128	    provideCredentialsCalls++;
129	    providedSsid = ssid;
130	    providedPassword = password;
131	    providedThreadDatasetHex = threadDatasetHex;
132	    if (!provideCredentialsCalled.isCompleted) provideCredentialsCalled.complete();
133	  }
134	
135	  @override
136	  Future<ShareDeviceResult?> openCommissioningWindow(int nodeId) async {
137	    openWindowCalls++;
138	    return windowResult;
139	  }
140	
141	  @override
142	  Future<List<FabricDescriptor>?> readFabrics(int nodeId) async {
143	    readFabricsCalls++;
144	    return fabricsResult;
145	  }
146	
147	  @override
