def start(port):
    pid = _read_pid()
    if pid and _pid_alive(pid):
        print(f"already running (pid {pid}), logging to {LOG_FILE}")
        return
    os.makedirs(LOG_DIR, exist_ok=True)
    # Detached background process, independent of this shell/session.
    subprocess.Popen(
        [sys.executable, os.path.abspath(__file__), "run", port],
        stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL,
        stderr=subprocess.DEVNULL, start_new_session=True)
    time.sleep(1.0)
    pid = _read_pid()
    if pid and _pid_alive(pid):
        print(f"started (pid {pid}) — logging {port} to {LOG_FILE}")
    else:
        print("failed to start (is pyserial installed? is the port present?)")
        sys.exit(1)


def stop():
    pid = _read_pid()
    if not pid or not _pid_alive(pid):
        print("not running")
        try:
            os.remove(PID_FILE)
        except OSError:
            pass
        return
    os.kill(pid, signal.SIGTERM)
    for _ in range(30):
        if not _pid_alive(pid):
            break
        time.sleep(0.1)
    print(f"stopped (pid {pid})")


def status():
    pid = _read_pid()
    running = bool(pid and _pid_alive(pid))
    print(f"status : {'RUNNING pid ' + str(pid) if running else 'stopped'}")
    print(f"log    : {LOG_FILE}")
    if os.path.exists(LOG_FILE):
        sz = os.path.getsize(LOG_FILE)
        print(f"size   : {sz} bytes")
        try:
            with open(LOG_FILE, "rb") as f:
                if sz > 4096:
                    f.seek(-4096, os.SEEK_END)
                last = f.read().decode("utf-8", errors="replace").splitlines()
            if last:
                print(f"last   : {last[-1]}")
        except OSError:
            pass


def main():
    cmd = sys.argv[1] if len(sys.argv) > 1 else "status"
    port = sys.argv[2] if len(sys.argv) > 2 else DEFAULT_PORT
    if cmd == "run":
        run(port)
    elif cmd == "start":
        start(port)
    elif cmd == "stop":
        stop()
    elif cmd == "restart":
        stop()
        time.sleep(0.5)
        start(port)
    elif cmd == "status":
        status()
    else:
        print(__doc__)
        sys.exit(2)

