203	/* ── Drain notify queue ──────────────────────────────────────────────────── */
204	
205	void flux_coap_drain_notify_queue(coap_context_t *ctx)
206	{
207	    notify_t *n;
208	    bool events_dirty = false;
209	
210	    while (xQueueReceive(flux_coap_notify_queue, &n, 0) == pdTRUE) {
211	        switch (n->type) {
212	
213	        case NOTIFY_TYPE_ATTR: {
214	            node_pending_t *p = flux_coap_pending_get(n->node_id);
215	            if (p) { flux_coap_pending_merge_attr(p, n); events_dirty = true; }
216	            flux_coap_cache_upsert_attr(n->node_id, n);
217	            break;
218	        }
219	
220	        case NOTIFY_TYPE_DEVICE_EVENT: {
221	            node_pending_t *p = flux_coap_pending_get(n->node_id);
222	            if (p) {
223	                p->has_event  = true;
224	                p->event_type = n->event_type;
225	                snprintf(p->event_error, sizeof(p->event_error), "%s", n->event_error);
226	                events_dirty = true;
227	            }
228	            /* Drive connectivity state machine */
229	            switch (n->event_type) {
230	            case flux_DeviceEventType_DEVICE_EVENT_DISCOVERING:
231	                /* subscribe_command queued — mDNS/CASE in flight */
232	            case flux_DeviceEventType_DEVICE_EVENT_RESUBSCRIBING: {
233	                /* connection lost — retry timer active; still show as retrying
234	                 * until the retry fires and we go back to DISCOVERING */
235	                node_cache_t *c = flux_coap_cache_find_or_create(n->node_id);
236	                if (c) c->connectivity =
237	                    (n->event_type == flux_DeviceEventType_DEVICE_EVENT_DISCOVERING)
238	                    ? REDACTED
239	                    : flux_ConnectivityState_CONNECTIVITY_RETRYING;
240	                break;
241	            }
242	            case flux_DeviceEventType_DEVICE_EVENT_ESTABLISHED: {
243	                node_cache_t *c = flux_coap_cache_find_or_create(n->node_id);
244	                if (c) c->connectivity = REDACTED;
245	                break;
246	            }
247	            case flux_DeviceEventType_DEVICE_EVENT_ERROR:
248	                /* Fatal: device removed or giving up — clear back to UNKNOWN */
249	                flux_coap_cache_clear_node(n->node_id);
250	                break;
251	            default:
252	                break;
253	            }
254	            break;
255	        }
256	
257	        case NOTIFY_TYPE_COMMISSION_RESULT: {
258	            /* Deferred reply to a POST /commission (CoAP separate response).
259	             * Runs on the CoAP task, so coap_*() and device-table calls are safe. */
260	            flux_CommissionResult result = flux_CommissionResult_init_zero;
261	            result.success = n->cm_success;
262	            if (n->cm_success) {
263	                result.node_id   = n->node_id;
264	                result.fabric_id = n->cm_fabric_id;
265	
266	                flux_DeviceRecord rec; memset(&rec, 0, sizeof(rec));
267	                rec.node_id     = n->node_id;
268	                rec.vendor_id   = n->cm_vendor_id;
269	                rec.product_id  = n->cm_product_id;
270	                rec.device_type = n->cm_device_type;
271	                snprintf(rec.name, sizeof(rec.name), "%s", n->cm_name);
272	                flux_device_upsert(&rec);
273	                flux_device_fetch_metadata(n->node_id);
274	                flux_device_subscribe(n->node_id);
275	
276	                ESP_LOGI(TAG, "POST /commission ok: node=%016llx fabric=%016llx",
277	                         (unsigned long long)n->node_id,
278	                         (unsigned long long)n->cm_fabric_id);
279	            } else {
280	                snprintf(result.error, sizeof(result.error), "%s", n->cm_error);
281	                ESP_LOGE(TAG, "POST /commission failed: %s", n->cm_error);
282	            }
283	
284	            uint8_t buf[flux_CommissionResult_size];
285	            pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
286	            if (n->cm_session && pb_encode(&os, flux_CommissionResult_fields, &result)) {
287	                coap_pdu_t *pdu = coap_pdu_init(
288	                    COAP_MESSAGE_CON, COAP_RESPONSE_CODE_CONTENT,
289	                    coap_new_message_id(n->cm_session),
290	                    coap_session_max_pdu_size(n->cm_session));
291	                if (pdu) {
292	                    coap_add_token(pdu, n->cm_token_len, n->cm_token);
293	                    uint8_t fmt = COAP_MEDIATYPE_APPLICATION_OCTET_STREAM;
294	                    coap_add_option(pdu, COAP_OPTION_CONTENT_FORMAT, 1, &fmt);
295	                    coap_add_data(pdu, os.bytes_written, buf);
296	                    if (coap_send(n->cm_session, pdu) == COAP_INVALID_MID)
297	                        ESP_LOGW(TAG, "deferred commission reply send failed");
298	                } else {
299	                    ESP_LOGE(TAG, "oom building deferred commission reply pdu");
300	                }
301	            }
302	            if (n->cm_session) coap_session_release(n->cm_session);
303	            break;
304	        }
305	
306	        case NOTIFY_TYPE_CLUSTER_DUMP: {
307	            /* The full cluster read (a worker task) finished. Hand the JSON to the
308	             * registered async and trigger it — libcoap re-runs hnd_clusters_get
309	             * with the original request, which sends the block-wise reply. */
310	            coap_bin_const_t tok = { .length = n->cd_token_len, .s = n->cd_token };
311	            coap_async_t *async = n->cd_session ? coap_find_async(n->cd_session, tok) : NULL;
312	            if (async) {
313	                cluster_dump_result_t *res =
314	                    (cluster_dump_result_t *)malloc(sizeof(*res));
315	                if (res) {
316	                    res->session  = n->cd_session;  /* ref ownership moves to the reply */
317	                    res->json     = n->cd_json;
318	                    res->json_len = n->cd_json_len;
319	                    coap_async_set_app_data(async, res);
320	                    coap_async_trigger(async);
321	                } else {
322	                    free(n->cd_json);
323	                    coap_session_release(n->cd_session);
324	                }
325	            } else {
326	                /* Client gone before the read finished — discard. */
327	                free(n->cd_json);
328	                if (n->cd_session) coap_session_release(n->cd_session);
329	            }
330	            break;
331	        }
332	
333	        case NOTIFY_TYPE_ENERGY_HISTORY:      /* shares the md_* fields + mechanism */
334	        case NOTIFY_TYPE_MODBUS_DISCOVERED: {
335	            /* A worker task (subnet scan, or SD energy aggregation) finished. Hand
336	             * the encoded proto to the registered async and trigger it — libcoap
337	             * re-runs the handler with the original request, which sends the
338	             * reply. Mirrors CLUSTER_DUMP. */
339	            coap_bin_const_t tok = { .length = n->md_token_len, .s = n->md_token };
340	            coap_async_t *async = n->md_session ? coap_find_async(n->md_session, tok) : NULL;
341	            if (async) {
342	                cluster_dump_result_t *res =
343	                    (cluster_dump_result_t *)malloc(sizeof(*res));
344	                if (res) {
345	                    res->session  = n->md_session;  /* ref ownership moves to reply */
346	                    res->json     = (char *)n->md_payload;
347	                    res->json_len = n->md_payload_len;
348	                    coap_async_set_app_data(async, res);
349	                    coap_async_trigger(async);
350	                } else {
351	                    free(n->md_payload);
352	                    coap_session_release(n->md_session);
353	                }
354	            } else {
355	                free(n->md_payload);
356	                if (n->md_session) coap_session_release(n->md_session);
357	            }
358	            break;
359	        }
360	
361	        default:
362	            break;
363	        }
364	        free(n);
365	    }
366	
367	    if (events_dirty && s_events_resource)
368	        coap_resource_notify_observers(s_events_resource, NULL);
369	}
