373	void flux_coap_notify_attr(uint64_t node_id, const char *key,
374	                            uint8_t which, bool bv, int32_t iv, int64_t lv)
375	{
376	    if (!flux_coap_notify_queue || !key) return;
377	    notify_t *n = (notify_t *)malloc(sizeof(notify_t));
378	    if (!n) return;
379	    memset(n, 0, sizeof(*n));
380	    n->type       = NOTIFY_TYPE_ATTR;
381	    n->node_id    = node_id;
382	    snprintf(n->attr_key, sizeof(n->attr_key), "%s", key);
383	    n->attr_which = which;
384	    n->attr_bool  = bv;
385	    n->attr_int   = iv;
386	    n->attr_long  = lv;
387	    if (xQueueSend(flux_coap_notify_queue, &n, 0) != pdTRUE) {
388	        ESP_LOGW(TAG, "notify queue full — dropping attr '%s' for node %016llx",
389	                 n->attr_key, (unsigned long long)node_id);
390	        free(n);
391	    }
392	}
