394	void flux_coap_notify_device_event(uint64_t node_id,
395	                                    uint8_t event_type, const char *error)
396	{
397	    if (!flux_coap_notify_queue) return;
398	    notify_t *n = (notify_t *)malloc(sizeof(notify_t));
399	    if (!n) return;
400	    memset(n, 0, sizeof(*n));
401	    n->type       = NOTIFY_TYPE_DEVICE_EVENT;
402	    n->node_id    = node_id;
403	    n->event_type = event_type;
404	    if (error) snprintf(n->event_error, sizeof(n->event_error), "%s", error);
405	    if (xQueueSend(flux_coap_notify_queue, &n, 0) != pdTRUE) {
406	        ESP_LOGW(TAG, "notify queue full — dropping device event for node %016llx",
407	                 (unsigned long long)node_id);
408	        free(n);
409	    }
