/* ── Observe resource handle ──────────────────────────────────────────────── */

static coap_resource_t *s_events_resource = NULL;

void flux_coap_set_observe_resources(coap_resource_t *events)
{
    s_events_resource = events;
}

/* ── Drain notify queue ──────────────────────────────────────────────────── */

void flux_coap_drain_notify_queue(coap_context_t *ctx)
{
    notify_t *n;
    bool events_dirty = false;

    while (xQueueReceive(flux_coap_notify_queue, &n, 0) == pdTRUE) {
        switch (n->type) {

        case NOTIFY_TYPE_ATTR: {
            node_pending_t *p = flux_coap_pending_get(n->node_id);
            if (p) { flux_coap_pending_merge_attr(p, n); events_dirty = true; }
            flux_coap_cache_upsert_attr(n->node_id, n);
            break;
        }

        case NOTIFY_TYPE_DEVICE_EVENT: {
            node_pending_t *p = flux_coap_pending_get(n->node_id);
            if (p) {
                p->has_event  = true;
                p->event_type = n->event_type;
                snprintf(p->event_error, sizeof(p->event_error), "%s", n->event_error);
                events_dirty = true;
            }
            /* Drive connectivity state machine */
            switch (n->event_type) {
            case flux_DeviceEventType_DEVICE_EVENT_DISCOVERING:
                /* subscribe_command queued — mDNS/CASE in flight */
            case flux_DeviceEventType_DEVICE_EVENT_RESUBSCRIBING: {
                /* connection lost — retry timer active; still show as retrying
                 * until the retry fires and we go back to DISCOVERING */
                node_cache_t *c = flux_coap_cache_find_or_create(n->node_id);
                if (c) c->connectivity =
                    (n->event_type == flux_DeviceEventType_DEVICE_EVENT_DISCOVERING)
                    ? REDACTED
                    : flux_ConnectivityState_CONNECTIVITY_RETRYING;
                break;
            }
            case flux_DeviceEventType_DEVICE_EVENT_ESTABLISHED: {
                node_cache_t *c = flux_coap_cache_find_or_create(n->node_id);
                if (c) c->connectivity = REDACTED;
                break;
            }
            case flux_DeviceEventType_DEVICE_EVENT_ERROR:
                /* Fatal: device removed or giving up — clear back to UNKNOWN */
                flux_coap_cache_clear_node(n->node_id);
                break;
            default:
                break;
            }
            break;
        }

        case NOTIFY_TYPE_COMMISSION_RESULT: {
            /* Deferred reply to a POST /commission (CoAP separate response).
             * Runs on the CoAP task, so coap_*() and device-table calls are safe. */
            flux_CommissionResult result = flux_CommissionResult_init_zero;
            result.success = n->cm_success;
            if (n->cm_success) {
                result.node_id   = n->node_id;
                result.fabric_id = n->cm_fabric_id;

                flux_DeviceRecord rec; memset(&rec, 0, sizeof(rec));
                rec.node_id     = n->node_id;
                rec.vendor_id   = n->cm_vendor_id;
                rec.product_id  = n->cm_product_id;
                rec.device_type = n->cm_device_type;
                snprintf(rec.name, sizeof(rec.name), "%s", n->cm_name);
                flux_device_upsert(&rec);
                flux_device_fetch_metadata(n->node_id);
                flux_device_subscribe(n->node_id);

                ESP_LOGI(TAG, "POST /commission ok: node=%016llx fabric=%016llx",
                         (unsigned long long)n->node_id,
                         (unsigned long long)n->cm_fabric_id);
            } else {
                snprintf(result.error, sizeof(result.error), "%s", n->cm_error);
                ESP_LOGE(TAG, "POST /commission failed: %s", n->cm_error);
            }

            uint8_t buf[flux_CommissionResult_size];
            pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
            if (n->cm_session && pb_encode(&os, flux_CommissionResult_fields, &result)) {
                coap_pdu_t *pdu = coap_pdu_init(
                    COAP_MESSAGE_CON, COAP_RESPONSE_CODE_CONTENT,
                    coap_new_message_id(n->cm_session),
                    coap_session_max_pdu_size(n->cm_session));
                if (pdu) {
                    coap_add_token(pdu, n->cm_token_len, n->cm_token);
                    uint8_t fmt = COAP_MEDIATYPE_APPLICATION_OCTET_STREAM;
                    coap_add_option(pdu, COAP_OPTION_CONTENT_FORMAT, 1, &fmt);
                    coap_add_data(pdu, os.bytes_written, buf);
                    if (coap_send(n->cm_session, pdu) == COAP_INVALID_MID)
                        ESP_LOGW(TAG, "deferred commission reply send failed");
                } else {
                    ESP_LOGE(TAG, "oom building deferred commission reply pdu");
                }
            }
            if (n->cm_session) coap_session_release(n->cm_session);
            break;
        }

        case NOTIFY_TYPE_CLUSTER_DUMP: {
            /* The full cluster read (a worker task) finished. Hand the JSON to the
             * registered async and trigger it — libcoap re-runs hnd_clusters_get
             * with the original request, which sends the block-wise reply. */
            coap_bin_const_t tok = { .length = n->cd_token_len, .s = n->cd_token };
            coap_async_t *async = n->cd_session ? coap_find_async(n->cd_session, tok) : NULL;
            if (async) {
                cluster_dump_result_t *res =
                    (cluster_dump_result_t *)malloc(sizeof(*res));
                if (res) {
                    res->session  = n->cd_session;  /* ref ownership moves to the reply */
                    res->json     = n->cd_json;
                    res->json_len = n->cd_json_len;
                    coap_async_set_app_data(async, res);
                    coap_async_trigger(async);
                } else {
                    free(n->cd_json);
                    coap_session_release(n->cd_session);
                }
            } else {
                /* Client gone before the read finished — discard. */
                free(n->cd_json);
                if (n->cd_session) coap_session_release(n->cd_session);
            }
            break;
        }

        case NOTIFY_TYPE_ENERGY_HISTORY:      /* shares the md_* fields + mechanism */
        case NOTIFY_TYPE_MODBUS_DISCOVERED: {
            /* A worker task (subnet scan, or SD energy aggregation) finished. Hand
             * the encoded proto to the registered async and trigger it — libcoap
             * re-runs the handler with the original request, which sends the
             * reply. Mirrors CLUSTER_DUMP. */
            coap_bin_const_t tok = { .length = n->md_token_len, .s = n->md_token };
            coap_async_t *async = n->md_session ? coap_find_async(n->md_session, tok) : NULL;
            if (async) {
                cluster_dump_result_t *res =
                    (cluster_dump_result_t *)malloc(sizeof(*res));
                if (res) {
                    res->session  = n->md_session;  /* ref ownership moves to reply */
                    res->json     = (char *)n->md_payload;
                    res->json_len = n->md_payload_len;
                    coap_async_set_app_data(async, res);
                    coap_async_trigger(async);
                } else {
                    free(n->md_payload);
                    coap_session_release(n->md_session);
                }
            } else {
                free(n->md_payload);
                if (n->md_session) coap_session_release(n->md_session);
            }
            break;
        }

        default:
            break;
        }
        free(n);
    }

    if (events_dirty && s_events_resource)
        coap_resource_notify_observers(s_events_resource, NULL);
}

/* ── Public push API (called from other tasks) ──────────────────────── */

void flux_coap_notify_attr(uint64_t node_id, const char *key,
                            uint8_t which, bool bv, int32_t iv, int64_t lv)
{
    if (!flux_coap_notify_queue || !key) return;
    notify_t *n = (notify_t *)malloc(sizeof(notify_t));
    if (!n) return;
    memset(n, 0, sizeof(*n));
    n->type       = NOTIFY_TYPE_ATTR;
    n->node_id    = node_id;
    snprintf(n->attr_key, sizeof(n->attr_key), "%s", key);
    n->attr_which = which;
    n->attr_bool  = bv;
    n->attr_int   = iv;
    n->attr_long  = lv;
    if (xQueueSend(flux_coap_notify_queue, &n, 0) != pdTRUE) {
        ESP_LOGW(TAG, "notify queue full — dropping attr '%s' for node %016llx",
                 n->attr_key, (unsigned long long)node_id);
        free(n);
    }
}

void flux_coap_notify_device_event(uint64_t node_id,
                                    uint8_t event_type, const char *error)
{
    if (!flux_coap_notify_queue) return;
    notify_t *n = (notify_t *)malloc(sizeof(notify_t));
    if (!n) return;
    memset(n, 0, sizeof(*n));
    n->type       = NOTIFY_TYPE_DEVICE_EVENT;
    n->node_id    = node_id;
    n->event_type = event_type;
    if (error) snprintf(n->event_error, sizeof(n->event_error), "%s", error);
    if (xQueueSend(flux_coap_notify_queue, &n, 0) != pdTRUE) {
        ESP_LOGW(TAG, "notify queue full — dropping device event for node %016llx",
                 (unsigned long long)node_id);
        free(n);
    }
}

/* The CoAP layer is the transport sink for flux_events: producers (Matter
 * controller, Modbus poller) call flux_events_emit_*() and land here without
 * depending on flux_coap.h. Registered once at boot from flux_coap_start(). */
static const flux_event_sink_t s_coap_event_sink = {
    .emit_attr   = flux_coap_notify_attr,
    .emit_device = flux_coap_notify_device_event,
};

/*
 * flux_events — device/attribute event bus (producer ↔ transport decoupling).
 *
 * Event *producers* — the Matter controller (subscription reports, lifecycle
 * events) and the Modbus poller (readings) — call flux_events_emit_*(). They do
 * NOT include flux_coap.h. The CoAP transport registers a sink at boot whose
 * callbacks push the event onto the CoAP /events notify queue.
 *
 * This inverts what used to be a matter→coap dependency (the core reaching up
 * into its transport to publish): now both the producers and the transport
 * depend only downward on this neutral module, so the dependency graph is
 * acyclic. See ADR / the architectural review.
 */
#pragma once

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Publish one changed attribute. which: 1 = bool_val, 2 = int_val (int32),
 * 3 = long_val (int64). Safe to call from any task; a no-op until a sink is
 * registered (and the sink itself drops events until its queue exists). */
void flux_events_emit_attr(uint64_t node_id, const char *key,
                           uint8_t which, bool bv, int32_t iv, int64_t lv);

/* Publish a device lifecycle event. event_type is a flux_DeviceEventType cast
 * to uint8_t; error may be NULL for non-error events. */
void flux_events_emit_device(uint64_t node_id, uint8_t event_type, const char *error);

/* Transport sink — implemented and registered once at boot by the CoAP layer
 * (flux_coap_notify_register_sink). Signatures match the emit_* functions. */
typedef struct {
    void (*emit_attr)(uint64_t node_id, const char *key,
                      uint8_t which, bool bv, int32_t iv, int64_t lv);
    void (*emit_device)(uint64_t node_id, uint8_t event_type, const char *error);
} flux_event_sink_t;

void flux_events_set_sink(const flux_event_sink_t *sink);

#ifdef __cplusplus
}
#endif

