#include "flux_events.h"

/* Set once at boot (flux_coap_notify_register_sink) before any producer task
 * emits, so a plain pointer read here needs no lock — the boot-time store
 * happens-before every producer via task creation. */
static const flux_event_sink_t *s_sink;

void flux_events_set_sink(const flux_event_sink_t *sink)
{
    s_sink = sink;
}

void flux_events_emit_attr(uint64_t node_id, const char *key,
                           uint8_t which, bool bv, int32_t iv, int64_t lv)
{
    const flux_event_sink_t *s = s_sink;
    if (s && s->emit_attr) s->emit_attr(node_id, key, which, bv, iv, lv);
}

void flux_events_emit_device(uint64_t node_id, uint8_t event_type, const char *error)
{
    const flux_event_sink_t *s = s_sink;
    if (s && s->emit_device) s->emit_device(node_id, event_type, error);
}

