/* ── Handler: GET /commission/events (Observe) ───────────────────────────── */
/* Fine-grained progress of the in-flight /commission. Returns the LATEST
 * CommissionEvent (seq 0 = nothing yet); Observe notifications re-run this
 * handler on every stage change (flux_coap_drain_notify_queue). Advisory —
 * the deferred POST /commission reply is the source of truth. */
void hnd_commission_events_get(coap_resource_t *resource,
                               coap_session_t  *session,
                               const coap_pdu_t *request,
                               const coap_string_t *query,
                               coap_pdu_t       *response)
{
    (void)resource; (void)session; (void)request; (void)query;

    const commission_progress_t *p = flux_coap_commission_progress();

    flux_CommissionEvent evt = flux_CommissionEvent_init_zero;
    evt.seq    = p->seq;
    evt.failed = p->failed;
    snprintf(evt.stage,  sizeof(evt.stage),  "%s", p->stage);
    snprintf(evt.detail, sizeof(evt.detail), "%s", p->detail);

    uint8_t buf[flux_CommissionEvent_size];
    pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
    if (!pb_encode(&os, flux_CommissionEvent_fields, &evt)) {
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR);
        return;
    }
    coap_pdu_set_code(response, COAP_RESPONSE_CODE_CONTENT);
    coap_add_data_blocked_response(request, response,
                                   COAP_MEDIATYPE_APPLICATION_OCTET_STREAM, 0,
                                   os.bytes_written, buf);
}

