116	 * a short window and replay its result for a repeated request with the same
117	 * passcode + discriminator (the only stable identity the request carries). */
118	constexpr int64_t kCommissionCacheTtlUs = 30 * 1000 * 1000; /* 30 s */
119	struct LastCommission {
120	    uint32_t passcode;
121	    uint32_t discriminator;
122	    uint64_t node_id;
123	    uint64_t fabric_id;
124	    int64_t  when_us;  /* esp_timer_get_time() at success; 0 = none cached */
