45	/* Guards s_attr_cache against a cross-task reader (flux_energy_log's snapshot).
46	 * All mutators run on the CoAP task and so never race each other; only the
47	 * writes below and the snapshot take this. Static-buffer mutex: creation cannot
48	 * fail (a heap-pressure NULL here would silently drop mutual exclusion — the
49	 * old `if (s_cache_mux)` guards no-opped instead of excluding), and it must be
50	 * created by flux_coap_cache_init() before the energy task starts. */
51	static SemaphoreHandle_t s_cache_mux;
52	static StaticSemaphore_t s_cache_mux_buf;
53	
54	void flux_coap_cache_init(void)
55	{
56	    if (s_cache_mux == NULL) {
57	        s_cache_mux = xSemaphoreCreateMutexStatic(&s_cache_mux_buf);
58	    }
59	}
