64	/* ── Cache accessors ──────────────────────────────────────────────────────── */
65	
66	/* Assumes the cache mutex is held (or caller is single-threaded CoAP task). */
67	static node_cache_t *cache_find_or_create_locked(uint64_t node_id)
68	{
69	    for (size_t i = 0; i < s_attr_cache_n; i++)
70	        if (s_attr_cache[i].node_id == node_id) return &s_attr_cache[i];
71	    if (s_attr_cache_n >= ATTR_CACHE_MAX_NODES) return NULL;
72	    node_cache_t *c = &s_attr_cache[s_attr_cache_n++];
73	    memset(c, 0, sizeof(*c));
74	    c->node_id = node_id;
75	    return c;
76	}
