78	node_cache_t *flux_coap_cache_find_or_create(uint64_t node_id)
79	{
80	    /* The returned slot lives in a static array (never moved), so the pointer
81	     * stays valid after unlock. Callers are all on the CoAP task and only read
82	     * the slot afterwards, so no writer can race that read. */
83	    cache_lock();
84	    node_cache_t *c = cache_find_or_create_locked(node_id);
85	    cache_unlock();
86	    return c;
87	}
