90	{
91	    for (size_t i = 0; i < s_attr_cache_n; i++) {
92	        if (s_attr_cache[i].node_id == node_id)
93	            return s_attr_cache[i].connectivity;
94	    }
95	    return flux_ConnectivityState_CONNECTIVITY_UNKNOWN;
96	}
