98	void flux_coap_cache_clear_node(uint64_t node_id)
99	{
100	    cache_lock();
101	    for (size_t i = 0; i < s_attr_cache_n; i++) {
102	        if (s_attr_cache[i].node_id == node_id) {
103	            s_attr_cache[i].connectivity = flux_ConnectivityState_CONNECTIVITY_UNKNOWN;
104	            s_attr_cache[i].n_attrs      = 0;
105	            break;
106	        }
107	    }
108	    cache_unlock();
109	}
