111	void flux_coap_cache_upsert_attr(uint64_t node_id, const notify_t *n)
112	{
113	    cache_lock();
114	    node_cache_t *c = cache_find_or_create_locked(node_id);
115	    if (!c) { cache_unlock(); return; }
116	    for (size_t i = 0; i < c->n_attrs; i++) {
117	        if (strcmp(c->attrs[i].key, n->attr_key) == 0) {
118	            c->attrs[i].which = n->attr_which;
119	            c->attrs[i].bv    = n->attr_bool;
120	            c->attrs[i].iv    = n->attr_int;
121	            c->attrs[i].lv    = n->attr_long;
122	            cache_unlock();
123	            return;
124	        }
125	    }
126	    if (c->n_attrs >= ATTR_CACHE_MAX_ATTRS) { cache_unlock(); return; }
127	    cached_attr_t *a = &c->attrs[c->n_attrs++];
128	    snprintf(a->key, sizeof(a->key), "%s", n->attr_key);
129	    a->which = n->attr_which;
130	    a->bv    = n->attr_bool;
131	    a->iv    = n->attr_int;
132	    a->lv    = n->attr_long;
133	    cache_unlock();
134	}
