136	size_t flux_coap_energy_snapshot(flux_energy_sample_t *out, size_t max)
137	{
138	    if (!out || max == 0) return 0;
139	    size_t n = 0;
140	    cache_lock();
141	    for (size_t i = 0; i < s_attr_cache_n && n < max; i++) {
142	        const node_cache_t *c = &s_attr_cache[i];
143	        flux_energy_sample_t s;
144	        memset(&s, 0, sizeof(s));
145	        s.node_id = c->node_id;
146	        bool any = false;
147	        for (size_t j = 0; j < c->n_attrs; j++) {
148	            const cached_attr_t *a = &c->attrs[j];
149	            if      (strcmp(a->key, "activePower") == 0)                 { s.active_power_mw   = a->lv; s.has_power   = true; any = true; }
150	            else if (strcmp(a->key, "voltage") == 0)                     { s.voltage_mv        = a->lv; s.has_voltage = true; any = true; }
151	            else if (strcmp(a->key, "activeCurrent") == 0)               { s.current_ma        = a->lv; s.has_current = true; any = true; }
152	            else if (strcmp(a->key, "cumulativeEnergyMwh") == 0)         { s.energy_import_mwh = a->lv; s.has_import  = true; any = true; }
153	            else if (strcmp(a->key, "cumulativeEnergyExportedMwh") == 0) { s.energy_export_mwh = a->lv; s.has_export  = true; any = true; }
154	        }
155	        if (any) out[n++] = s;
156	    }
157	    cache_unlock();
158	    return n;
159	}
