80	  /// (`--dart-define=FLUX_TURN_HOST=… FLUX_TURN_USER=… FLUX_TURN_PASS=…`) so it
81	  /// works out of the box; public builds ship no credentials and users
82	  /// configure their own relay in Remote-access settings (which always wins).
83	  /// Public so the settings screen can display the effective defaults.
84	  static const defaultTurnHost = String.fromEnvironment('FLUX_TURN_HOST');
85	  static const defaultTurnUser = String.fromEnvironment('FLUX_TURN_USER');
86	  static const defaultTurnPass = String.fromEnvironment('FLUX_TURN_PASS');
87	
88	  FluxCoapService? _service;
89	  bool _hasStoredPsk = false;
90	  bool _reachable    = false;
91	  bool _probing      = false;
92	  Timer? _heartbeatTimer;
93	  StreamSubscription<List<ConnectivityResult>>? _connSub;
94	  Timer? _connDebounce;
95	  bool?  _lastMobileOnly;
96	
97	  FluxCoapService? get service => _service;
98	  bool get isConnected => _service != null;
99	
100	  /// True when a hub has been configured (a PSK is stored), even if the
101	  /// controller is currently unreachable. Lets the UI distinguish "no hub set
102	  /// up yet" from "hub set up but offline" — the latter should not be told to
103	  /// pair a new hub.
104	  bool get hasConfiguredHub => isConnected || _hasStoredPsk;
105	
106	  /// App-wide controller reachability. Watch this to reflect/gate anything that
107	  /// depends on the hub.
108	  ControllerStatus get status {
109	    if (!hasConfiguredHub) return ControllerStatus.noHub;
110	    if (_reachable)        return ControllerStatus.online;
111	    if (_probing)          return ControllerStatus.connecting;
112	    return ControllerStatus.offline;
113	  }
114	
115	  bool get isOnline => status == ControllerStatus.online;
116	
117	  /// Which transport the active connection uses. The remote ICE tunnel always
118	  /// presents a 127.0.0.1 loopback endpoint (app ADR-0001), so a loopback host
119	  /// means remote; any other reachable host is a direct LAN connection. Only
120	  /// meaningful while [isOnline].
121	  ConnectionKind get connectionKind {
122	    if (!_reachable) return ConnectionKind.none;
123	    return _service?.endpoint.host == '127.0.0.1'
124	        ? ConnectionKind.remote
125	        : ConnectionKind.local;
126	  }
127	
128	  /// Re-reads whether any controller PSK is stored and notifies listeners if it
129	  /// changed. Call after the add-controller flow saves a PSK.
130	  Future<void> refreshConfiguredState() async {
131	    final has = await ControllerSettings.hasAnyPsk();
132	    if (has != _hasStoredPsk) {
133	      _hasStoredPsk = has;
134	      notifyListeners();
135	    }
136	  }
137	
138	  /// Directly installs a freshly-created service (e.g. after background
139	  /// discovery that completed post-boot) and notifies listeners.
140	  void setService(FluxCoapService svc) {
141	    _service?.dispose();
142	    _service = svc;
143	    _wire(svc);
144	    notifyListeners();
145	    unawaited(_probe());
146	  }
147	
148	  /// Connectivity-aware entry to the connect FSM (app ADR-0003). On a
149	  /// cellular-only network the home LAN is unreachable, so skip mDNS discovery
150	  /// (which otherwise blocks up to ~20s) and go straight to the remote tunnel.
151	  /// Wi-Fi/ethernet/VPN are ambiguous (could be a foreign network), so there we
152	  /// still try LAN-first via [reconnect].
153	  Future<bool> connect() async {
154	    if (await _isMobileOnly()) {
155	      _log('cellular-only network → skipping LAN discovery, going remote');
156	      return tryRemote();
157	    }
158	    return reconnect();
159	  }
160	
161	  /// True when the only active transport is cellular. Wi-Fi/ethernet/VPN count
162	  /// as "LAN-capable" even if foreign — the LAN probe is what disambiguates
