2	 * Flux Controller — CoAP/DTLS API server
3	 *
4	 * Server lifecycle, PSK setup, and I/O task.
5	 * Handlers and notify logic are in flux_coap_handlers.c and flux_coap_notify.c.
6	 *
7	 * Architecture
8	 * ────────────
9	 *   libcoap is NOT multi-thread safe. All coap_*() calls live in the coap_task.
10	 *   Other tasks communicate via s_notify_queue (see flux_coap_notify.c).
11	 */
12	
13	#include "flux_coap.h"
14	#include "flux_coap_internal.h"
15	#include "flux_state.h"
16	
17	#include <coap3/coap.h>
18	
19	#include <esp_log.h>
20	#include <esp_mac.h>
21	#include <esp_random.h>
22	#include <nvs_flash.h>
23	#include <nvs.h>
24	#include <freertos/FreeRTOS.h>
25	#include <freertos/task.h>
26	#include <string.h>
27	#include <stdio.h>
28	
29	static const char *TAG = "flux_coap";
30	
31	/* ── PSK ──────────────────────────────────────────────────────────────────── */
32	
33	static uint8_t s_psk[16];
34	static char    s_psk_id[48];  /* "flux-controller-xxxxxx\0" */
35	static bool    s_psk_ready = false;
36	
37	/* Well-known default DTLS PSK. Every controller comes up with this until a
38	 * manufacturing PSK is programmed via POST /mfg/provision, so a freshly
39	 * flashed / NVS-erased device is always reachable on a known key (no random
40	 * PSK to read off the serial console). It is intentionally NOT persisted —
41	 * absence of a stored PSK *is* the "still on default" state — and is
42	 * overridden the moment manufacturing data provides one. Not a secret: it is
43	 * a documented bootstrap credential meant to be replaced at manufacturing. */
44	static const uint8_t k_default_psk[16] = {
45	    0x2c, 0x15, 0x25, 0xa8, 0xcd, 0xf4, 0x09, 0x08,
46	    0xdb, 0x38, 0x0e, 0x07, 0x0a, 0xd9, 0x23, 0x5e,
47	};
48	
49	static void init_psk(void)
50	{
51	    /* Manufacturing data (flux_state, flux_factory partition) overrides the
52	     * default when present — settable via POST /mfg/provision so a per-device
53	     * PSK (e.g. printed on a label / QR code) can be programmed. */
54	    if (flux_state_get_psk(s_psk) == ESP_OK) {
55	        ESP_LOGI(TAG, "PSK loaded from manufacturing data");
56	    } else {
57	        memcpy(s_psk, k_default_psk, sizeof(s_psk));
58	        ESP_LOGW(TAG, "PSK not provisioned — using well-known default "
59	                      "(run /mfg/provision --set-psk to override)");
60	    }
61	
62	    uint8_t mac[6];
63	    esp_read_mac(mac, ESP_MAC_ETH);
64	    snprintf(s_psk_id, sizeof(s_psk_id),
65	             "flux-controller-%02x%02x%02x", mac[3], mac[4], mac[5]);
66	
67	    s_psk_ready = true;
68	    ESP_LOGI(TAG, "DTLS PSK identity: %s", s_psk_id);
69	    ESP_LOGI(TAG, "DTLS PSK key (hex): "
70	             "%02x%02x%02x%02x%02x%02x%02x%02x"
71	             "%02x%02x%02x%02x%02x%02x%02x%02x",
72	             s_psk[0],  s_psk[1],  s_psk[2],  s_psk[3],
73	             s_psk[4],  s_psk[5],  s_psk[6],  s_psk[7],
74	             s_psk[8],  s_psk[9],  s_psk[10], s_psk[11],
75	             s_psk[12], s_psk[13], s_psk[14], s_psk[15]);
76	}
77	
78	bool flux_coap_get_psk(uint8_t out[16])
79	{
80	    if (!s_psk_ready) return false;
81	    memcpy(out, s_psk, sizeof(s_psk));
82	    return true;
83	}
84	
85	/* ── libcoap log → ESP_LOG bridge ───────────────────────────────────────── */
86	
87	static void coap_log_handler(coap_log_t level, const char *message)
88	{
89	    uint32_t esp_level = (level <= COAP_LOG_WARN) ? ESP_LOG_WARN : ESP_LOG_DEBUG;
90	    char buf[256];
91	    snprintf(buf, sizeof(buf), "%s", message);
92	    size_t len = strlen(buf);
93	    while (len > 0 && (buf[len-1] == '\n' || buf[len-1] == '\r'))
94	        buf[--len] = '\0';
95	    if (len)
96	        ESP_LOG_LEVEL(esp_level, "libcoap", "%s", buf);
97	}
98	
99	/* ── CoAP server task ────────────────────────────────────────────────────── */
100	
101	static void coap_task(void *arg)
102	{
103	    coap_startup();
104	    coap_set_log_handler(coap_log_handler);
105	    coap_set_log_level(COAP_LOG_WARN);
106	
107	    while (1) {
108	        coap_context_t  *ctx  = NULL;
109	        coap_resource_t *r    = NULL;
110	        int              have_ep = 0;
111	
112	        ctx = coap_new_context(NULL);
113	        if (!ctx) {
114	            ESP_LOGE(TAG, "coap_new_context failed");
115	            goto restart;
116	        }
117	
118	        coap_context_set_block_mode(ctx,
119	            COAP_BLOCK_USE_LIBCOAP | COAP_BLOCK_SINGLE_BODY);
120	        coap_context_set_max_idle_sessions(ctx, 8);
121	        coap_context_set_keepalive(ctx, 30);
122	
123	        coap_context_set_psk(ctx, s_psk_id,
124	                             (const uint8_t *)s_psk, sizeof(s_psk));
125	
126	        {
127	            uint32_t scheme_bits = coap_get_available_scheme_hint_bits(
128	                1,  /* with_dtls */
129	                0,  /* with_ws */
130	                0   /* reserved  */);
131	#if LWIP_IPV6
132	            coap_addr_info_t *info_list =
133	                coap_resolve_address_info(coap_make_str_const("::"),
134	                    0, 5684, 0, 0, 0, scheme_bits,
135	                    COAP_RESOLVE_TYPE_LOCAL);
136	#else
137	            coap_addr_info_t *info_list =
138	                coap_resolve_address_info(coap_make_str_const("0.0.0.0"),
139	                    0, 5684, 0, 0, 0, scheme_bits,
140	                    COAP_RESOLVE_TYPE_LOCAL);
141	#endif
142	            if (!info_list) {
143	                ESP_LOGE(TAG, "coap_resolve_address_info failed");
144	                goto restart;
145	            }
146	            for (coap_addr_info_t *info = info_list; info; info = info->next) {
147	                coap_endpoint_t *ep = coap_new_endpoint(ctx, &info->addr,
148	                                                         info->proto);
149	                if (ep) have_ep = 1;
150	            }
151	            coap_free_address_info(info_list);
152	        }
153	        if (!have_ep) {
154	            ESP_LOGE(TAG, "no CoAP endpoints could be created");
155	            goto restart;
156	        }
157	
158	        /* ── Register all resource handlers ──────────────────────────── */
159	        r = coap_resource_init(coap_make_str_const("info"), 0);
160	        coap_register_handler(r, COAP_REQUEST_GET, hnd_info_get);
161	        coap_add_resource(ctx, r);
162	
163	        r = coap_resource_init(coap_make_str_const("thread/dataset"), 0);
164	        coap_register_handler(r, COAP_REQUEST_GET, hnd_thread_dataset_get);
165	        coap_register_handler(r, COAP_REQUEST_PUT, hnd_thread_dataset_put);
166	        coap_add_resource(ctx, r);
