171	        coap_register_handler(r, COAP_REQUEST_GET,    hnd_thread_epskc_get);
172	        coap_add_resource(ctx, r);
173	
174	        r = coap_resource_init(coap_make_str_const("thread/join"), 0);
175	        coap_register_handler(r, COAP_REQUEST_POST,   hnd_thread_join_post);
176	        coap_add_resource(ctx, r);
