/*
 * flux_meshcop_client — Thread 1.4 credential-sharing JOIN client.
 *
 * flux acts as a MeshCoP commissioner against a FOREIGN Border Router's
 * ephemeral-key (ePSKc) session: opens a DTLS 1.2 EC-JPAKE session (the 6-32
 * char ephemeral key IS the J-PAKE password — no KDF, matching the OT Border
 * Agent server side), petitions (MGMT_COMMISSIONER_PETITION, /c/cp), then reads
 * the Active Operational Dataset (MGMT_ACTIVE_GET, /c/ag). The response payload
 * is the raw dataset TLV blob, returned verbatim for flux to adopt/migrate.
 *
 * Blocking — must run on a worker task with a generous stack (see the
 * /thread/join handler), never on the coap_task. Does NOT touch the OpenThread
 * stack (plain lwIP UDP + mbedTLS to a LAN address), so no OT-lock concerns.
 */
#ifndef FLUX_MESHCOP_CLIENT_H
#define FLUX_MESHCOP_CLIENT_H

#include <stdint.h>
#include <stddef.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct {
    uint8_t tlv[254];        /* retrieved Active Operational Dataset TLV blob   */
    size_t  tlv_len;
    char    error[128];      /* human-readable failure reason (empty on success)*/
} flux_meshcop_result_t;

/* A foreign Border Agent advertising an active ephemeral-key session. */
typedef struct {
    char     addr[46];       /* LAN address to DTLS to                          */
    uint16_t port;           /* its _meshcop-e._udp port                        */
    char     name[64];       /* mDNS instance name (for logging/UX)             */
} flux_meshcop_candidate_t;

/* Browse the LAN for _meshcop-e._udp (Border Agents with a LIVE ephemeral-key
 * session — only advertised while the other ecosystem's share sheet is open).
 * Fills up to `max` candidates; returns the count (>=0) or <0 on mDNS error.
 * Blocking for ~timeout_ms. flux is the OTBR so it can browse directly. */
int flux_meshcop_discover_ephemeral(flux_meshcop_candidate_t *out, int max, uint32_t timeout_ms);

/* Connect to a foreign Border Agent's ephemeral-key session at [addr]:port
 * (addr = IPv4 or IPv6 literal), authenticate with `ephemeral_key`, and fetch
 * the Active Operational Dataset into `out`. Returns 0 on success, <0 on error
 * (out->error carries the reason). Blocking; bounded internally (~30 s worst
 * case). */
int flux_meshcop_fetch_dataset(const char *addr, uint16_t port,
                               const char *ephemeral_key,
                               flux_meshcop_result_t *out);

