void hnd_thread_dataset_get(coap_resource_t *resource,
                            coap_session_t  *session,
                            const coap_pdu_t *request,
                            const coap_string_t *query,
                            coap_pdu_t       *response)
{
    flux_ThreadDataset ds = flux_ThreadDataset_init_zero;
    bool tlv_from_ot = false;

#ifdef CONFIG_OPENTHREAD_BORDER_ROUTER
    /* Primary source: live OpenThread active dataset — this is the truth even
     * if the controller auto-generated a network on first boot and NVS was
     * never written.  Sync back to NVS so subsequent boots restore the same
     * network (avoids "creating new Thread network" on every cold start). */
    if (esp_openthread_lock_acquire(pdMS_TO_TICKS(200))) {
        otInstance *ot = esp_openthread_get_instance();
        if (ot) {
            otOperationalDatasetTlvs ot_tlvs;
            if (otDatasetGetActiveTlvs(ot, &ot_tlvs) == OT_ERROR_NONE &&
                ot_tlvs.mLength > 0) {
                memcpy(ds.tlv.bytes, ot_tlvs.mTlvs, ot_tlvs.mLength);
                ds.tlv.size = ot_tlvs.mLength;
                tlv_from_ot = true;

                /* Persist to NVS if not already there or different. */
                uint8_t stored[254]; size_t stored_len = 0;
                bool needs_sync =
                    (flux_state_get_thread_dataset(stored, &stored_len, sizeof(stored)) != ESP_OK) ||
                    (stored_len != ot_tlvs.mLength) ||
                    (memcmp(stored, ot_tlvs.mTlvs, ot_tlvs.mLength) != 0);
                if (needs_sync) {
                    flux_state_set_thread_dataset(ot_tlvs.mTlvs, ot_tlvs.mLength);
                    ESP_LOGI(TAG, "GET /thread/dataset — synced live OT dataset to NVS (%u bytes)",
                             (unsigned)ot_tlvs.mLength);
                }
            }

            otDeviceRole role = otThreadGetDeviceRole(ot);
            const char *role_str = "Unknown";
            switch (role) {
            case OT_DEVICE_ROLE_DISABLED:  role_str = "Disabled";  break;
            case OT_DEVICE_ROLE_DETACHED:  role_str = "Detached";  break;
            case OT_DEVICE_ROLE_CHILD:     role_str = "Child";     break;
            case OT_DEVICE_ROLE_ROUTER:    role_str = "Router";    break;
            case OT_DEVICE_ROLE_LEADER:    role_str = "Leader";    break;
            default: break;
            }
            snprintf(ds.role, sizeof(ds.role), "%s", role_str);
            ds.rloc16       = otThreadGetRloc16(ot);
            ds.partition_id = otThreadGetPartitionId(ot);

            otNeighborInfoIterator it = OT_NEIGHBOR_INFO_ITERATOR_INIT;
            otNeighborInfo info;
            uint32_t count = 0;
            while (otThreadGetNextNeighborInfo(ot, &it, &info) == OT_ERROR_NONE)
                count++;
            ds.neighbor_count = count;
        }
        esp_openthread_lock_release();
    }
#endif

    /* Fallback: NVS (used when OTBR is not enabled or OT lock timed out). */
    if (!tlv_from_ot) {
        uint8_t tlv[254]; size_t tlv_len = 0;
        esp_err_t err = flux_state_get_thread_dataset(tlv, &tlv_len, sizeof(tlv));
        if (err == ESP_ERR_NOT_FOUND) {
            coap_pdu_set_code(response, COAP_RESPONSE_CODE_NOT_FOUND);
            return;
        }

