 * device, since the attribute is reported for the accessing fabric) and the
 * Fabrics list (0x01), then issues RemoveFabric (cmd 0x04) for every fabric
 * index != CurrentFabricIndex. Fire-and-forget on the CHIP task; every step is
 * logged to the console.
 *
 * SAFETY: if CurrentFabricIndex could not be read (offline / read failed) we
 * remove NOTHING — never risk evicting flux itself and losing the device. The
 * fabric indices are collected up-front, so removing one never renumbers the
 * others (Matter fabric indices are stable).
 */
namespace {

struct FabricStripCtx {
    uint64_t          node_id;
    chip::FabricIndex current;       /* flux's index on the device               */
    bool              have_current;
    uint8_t           idx[16];       /* every fabric index on the device          */
    uint16_t          vendor[16];
    int               n;
    int               commissioned;  /* CommissionedFabrics (0x03) cross-check    */
    bool              finished;      /* single-terminal guard (CHIP-task only)    */
};

void strip_attr_cb(FabricStripCtx *sc,
                   const chip::app::ConcreteDataAttributePath &path,
                   chip::TLV::TLVReader *data)
{
    if (!data || path.mClusterId != 0x003E) return;

    if (path.mAttributeId == 0x0005) {            /* CurrentFabricIndex (U8)       */
        uint64_t v = 0;
        if (data->Get(v) == CHIP_NO_ERROR) {
            sc->current      = (chip::FabricIndex)v;
            sc->have_current = true;
        }
        return;
    }
    if (path.mAttributeId == 0x0003) {            /* CommissionedFabrics (U8 count)*/
        uint64_t v = 0;
        if (data->Get(v) == CHIP_NO_ERROR) sc->commissioned = (int)v;
        return;
    }
    if (path.mAttributeId != 0x0001) return;      /* Fabrics list                  */

    chip::TLV::TLVType outer;
    if (data->EnterContainer(outer) != CHIP_NO_ERROR) return;
    while (data->Next() == CHIP_NO_ERROR) {
        if (data->GetType() != chip::TLV::kTLVType_Structure) continue;
        chip::TLV::TLVType inner;
        if (data->EnterContainer(inner) != CHIP_NO_ERROR) continue;
