65	
66	/* libcoap holds the response body pointer across block2 requests (it does NOT
67	 * copy when no release_func is given) and paginates from it on each follow-up
68	 * block. Callers free their buffer right after this returns, which is fine for a
69	 * single-block reply but corrupts a multi-block one — libcoap then reads freed
70	 * memory, the body differs between blocks, and the client aborts with
71	 * ResourceChanged (hit by /energy/history and /modbus/rawdump). Hand libcoap its
72	 * OWN copy plus a release callback so the body stays stable for the whole
73	 * block-wise transfer; the caller's buffer lifetime no longer matters. */
74	static void proto_body_release(coap_session_t *session, void *app_ptr)
75	{
76	    (void)session;
77	    free(app_ptr);
78	}
79	
80	void coap_send_proto(coap_resource_t *resource,
81	                     coap_session_t  *session,
82	                     const coap_pdu_t *request,
83	                     coap_pdu_t       *response,
84	                     const uint8_t    *buf, size_t len)
85	{
86	    coap_pdu_set_code(response, COAP_RESPONSE_CODE_CONTENT);
87	
88	    /* Stable, content-derived ETag (FNV-1a). A block-wise (block2) transfer
89	     * re-runs the handler per block; with etag=0 libcoap auto-assigns a fresh
90	     * ETag each call, so the client sees the resource "change" mid-transfer and
91	     * aborts (ResourceChanged). Deriving the ETag from the body keeps it
92	     * identical across blocks of the same body (and differs when it changes). */
93	    uint64_t etag = 1469598103934665603ULL;
94	    for (size_t i = 0; i < len; i++) { etag ^= buf[i]; etag *= 1099511628211ULL; }
95	    if (etag == 0) etag = 1;
96	
97	    uint8_t *owned = len ? (uint8_t *)malloc(len) : NULL;
98	    if (owned) memcpy(owned, buf, len);
99	    coap_add_data_large_response(resource, session, request, response,
100	                                 NULL,
101	                                 COAP_MEDIATYPE_APPLICATION_OCTET_STREAM,
102	                                 -1, etag, len,
103	                                 owned ? owned : buf,
104	                                 owned ? proto_body_release : NULL,
105	                                 owned);
106	}
107	
108	void coap_send_proto_block2(coap_session_t *session, const coap_pdu_t *request,
109	                            coap_pdu_t *response, const uint8_t *body, size_t len)
110	{
111	    (void)session;
112	    /* Manual RFC7959 block2, with a fixed content-derived (FNV-1a) ETag on EVERY
113	     * block. coap_add_data_large_response adds the ETag only when it sets up the
114	     * transfer (block 0); on a mid-stream block served by a re-invoked handler
115	     * (the async separate-response path used by large deferred bodies) it drops
116	     * the ETag, so the client sees the resource "change" and aborts
117	     * (ResourceChanged). Setting options ourselves keeps the ETag identical
118	     * across all blocks. The caller must serve the SAME body for every block
119	     * (i.e. cache it), which the async endpoints do. */
120	    uint64_t etag = 1469598103934665603ULL;
121	    for (size_t i = 0; i < len; i++) { etag ^= body[i]; etag *= 1099511628211ULL; }
122	    if (etag == 0) etag = 1;
123	
124	    coap_block_t blk;
125	    uint32_t num = 0, szx = 6;                 /* default block size 1024 */
126	    if (coap_get_block(request, COAP_OPTION_BLOCK2, &blk)) { num = blk.num; szx = blk.szx; }
127	    if (szx > 6) szx = 6;
128	    size_t bsize = (size_t)1 << (szx + 4);
129	    size_t off   = (size_t)num * bsize;
130	    if (off > len) off = len;
131	    size_t chunk = (len - off > bsize) ? bsize : (len - off);
132	    unsigned more = (off + chunk < len) ? 1u : 0u;
133	
134	    coap_pdu_set_code(response, COAP_RESPONSE_CODE_CONTENT);
135	    /* Options must be added in ascending number order:
136	     * ETag(4) < Content-Format(12) < Block2(23) < Size2(28). */
137	    uint8_t b[8]; size_t n;
138	    n = coap_encode_var_safe8(b, sizeof b, etag);
139	    coap_add_option(response, COAP_OPTION_ETAG, n, b);
140	    n = coap_encode_var_safe(b, sizeof b, COAP_MEDIATYPE_APPLICATION_OCTET_STREAM);
141	    coap_add_option(response, COAP_OPTION_CONTENT_FORMAT, n, b);
142	    n = coap_encode_var_safe(b, sizeof b, (num << 4) | (more << 3) | szx);
143	    coap_add_option(response, COAP_OPTION_BLOCK2, n, b);
144	    if (num == 0) {                            /* advertise total size up front */
145	        n = coap_encode_var_safe(b, sizeof b, (unsigned)len);
146	        coap_add_option(response, COAP_OPTION_SIZE2, n, b);
147	    }
148	    coap_add_data(response, chunk, body + off);
149	}
