// ── Multi-admin / share ───────────────────────────────────────────────────

fun openCommissioningWindow(
    nodeId: Long,
    vendorId: Int,
    productId: Int,
    awaitReachable: Boolean,
    result: MethodChannel.Result,
) = core.requireChip(result) {
    val rng           = java.security.SecureRandom()
    val discriminator = rng.nextInt(0x1000)             // 12-bit: 0–4095
    val pin           = generateValidPin(rng)            // 27-bit valid passcode

    val devicePtr = ChipClient.getConnectedDevicePointer(core.context, nodeId)

    // Old CHIP SDK returns Boolean; new SDK returns String (manual pairing code).
    val sdkResult = ChipClient.getController().openPairingWindowWithPIN(
        devicePtr, 300, 1000L, discriminator, pin
    )
    Log.i(TAG, "openPairingWindowWithPIN: nodeId=$nodeId disc=$discriminator " +
               "pin=$pin sdkResult=$sdkResult (${sdkResult::class.java.simpleName})")
    if (!windowOpened(sdkResult)) {
        throw CommissioningException(
            -5,
            "Device rejected the commissioning window request " +
            "(sdkResult=$sdkResult). The device may be offline, " +
            "already have an open window, or not support multi-admin.",
        )
    }

    // If Flutter didn't supply VID/PID, read them from the device so the
    // QR code carries the real values — some commissioning apps filter by VID.
    val finalVendorId: Int
    val finalProductId: Int
    if (vendorId == 0) {
        val info = try { BasicInfoCluster.readBasicInfo(core.context, nodeId) } catch (_: Exception) { null }
        finalVendorId  = info?.vendorId ?.removePrefix("0x")?.removePrefix("0X")?.toIntOrNull(16) ?: 0
        finalProductId = info?.productId?.removePrefix("0x")?.removePrefix("0X")?.toIntOrNull(16) ?: 0
        Log.i(TAG, "VID/PID read from device: VID=0x%04X PID=0x%04X".format(finalVendorId, finalProductId))
    } else {
        finalVendorId  = vendorId
        finalProductId = productId
    }

    val payload = OnboardingPayload(
        /* version               */ 0,
        /* vendorId              */ finalVendorId,
        /* productId             */ finalProductId,
        /* commissioningFlow     */ CommissioningFlow.STANDARD.value,
        /* discoveryCapabilities */ mutableSetOf(DiscoveryCapability.ON_NETWORK),
        /* discriminator         */ discriminator,
        /* hasShortDiscriminator */ false,
        /* setupPinCode          */ pin,
    )
    val manualCode = ManualOnboardingPayloadGenerator(payload).payloadDecimalStringRepresentation()
    var qrCode = QRCodeOnboardingPayloadGenerator(payload).payloadBase38Representation()
    // payloadBase38Representation() already includes the "MT:" prefix in current
    // CHIP SDK versions.  Guard against older SDKs that may omit it.
    if (!qrCode.startsWith("MT:")) qrCode = "MT:$qrCode"

    Log.i(TAG, "ECM window open: nodeId=$nodeId disc=$discriminator " +
               "VID=0x%04X PID=0x%04X manual=$manualCode qr=$qrCode".format(finalVendorId, finalProductId))

    // Scan for the device's CM=2 mDNS advertisement to get its Thread IPv6 address.
    // OTBR proxies the _matterc._udp PTR to Ethernet but does NOT proxy the
    // discriminator subtype PTR (L{disc}._sub._matterc._udp).  This means CHIP's
    // built-in discriminator-based discovery (pairing_code) never finds the device.
    // The phone can find it via top-level _matterc._udp browse.  We return the IPv6
    // so the firmware can use PairDevice(IP) and skip CHIP DNS-SD discovery entirely.
    //
    // Skipped for the commission-then-handoff path (awaitReachable=false): the
    // controller rediscovers the device over Thread itself from the discriminator,
    // so the phone need not block on the (slow) mDNS scan.
    var ipv6Address = ""
    var ipv6Port    = 0
    if (awaitReachable) {
        val scanStart   = System.currentTimeMillis()
        val scanTimeout = 90_000L
        Log.i(TAG, "Scanning for CM=2 device disc=$discriminator (up to ${scanTimeout/1000}s)...")
        while (ipv6Address.isEmpty() && System.currentTimeMillis() - scanStart < scanTimeout) {
            val devices = MatterCommissionableScanner.scan(core.context)
            val match   = devices.find {
                it.discriminator.toInt() == discriminator &&
                it.commissioningMode == "EnhancedWindowOpen"
            }
            if (match != null) {
                ipv6Address = match.ipAddress
                ipv6Port    = match.port
                Log.i(TAG, "CM=2 found at $ipv6Address:$ipv6Port after ${System.currentTimeMillis()-scanStart}ms")
            } else {
                Log.d(TAG, "CM=2 not found yet, ${scanTimeout-(System.currentTimeMillis()-scanStart)}ms remaining")
            }
        }
        if (ipv6Address.isEmpty()) {
            Log.w(TAG, "CM=2 device not found within ${scanTimeout/1000}s — will fallback to mDNS on controller")
        }
    }

    core.main.post {
        result.success(mapOf(
            "manualPairingCode" to manualCode,
            "qrCodePayload"     to qrCode,
            "ipv6Address"       to ipv6Address,
            "port"              to ipv6Port,
            "passcode"          to pin,
            "discriminator"     to discriminator,
        ))
    }
}

