17	/// Flutter ↔ platform MethodChannel bridge.
18	///
19	/// Every public method maps 1-to-1 to a handler in MainActivity / MatterBridge.
20	/// All channel calls are funnelled through [_invoke] which handles the
21	/// [PlatformException] → fallback value pattern in one place.
22	///
23	/// Implements [MatterPort] so callers can depend on the narrower sub-interfaces
24	/// ([MatterSubscriptionPort], [MatterCommissionPort], [MatterClusterPort],
25	/// [MatterFabricPort]) and be tested with fakes.
26	class MatterChannel implements MatterPort {
27	  MatterChannel();
28	
29	  static const _method = MethodChannel('com.fluxhome.app/matter');
30	  static const _events = EventChannel('com.fluxhome.app/commission_events');
31	  static const _deviceEvents = EventChannel('com.fluxhome.app/device_state');
32	
33	  // ── Internal helper ────────────────────────────────────────────────────────
34	
35	  /// Invokes [method] with optional [args], returns [fallback] on any
36	  /// [PlatformException].  Supply [decode] to transform the raw result into [T].
37	  Future<T> _invoke<T>(String method, T fallback, {Map<String, dynamic>? args, T Function(dynamic raw)? decode}) async {
38	    try {
39	      final raw = await _method.invokeMethod<dynamic>(method, args);
40	      return decode != null ? decode(raw) : (raw as T? ?? fallback);
41	    } on PlatformException catch (e) {
42	      debugPrint('$method error: ${e.message}');
43	      return fallback;
44	    }
45	  }
46	
47	  // ── Streams ────────────────────────────────────────────────────────────────
48	
49	  /// Emits plain-text progress lines from the platform commissioning flow.
50	  @override
51	  Stream<String> get commissionEvents => _events.receiveBroadcastStream().map((e) => e as String);
52	
53	  /// Decodes the raw platform-channel map into a typed [DeviceStateEvent].
54	  ///
55	  /// This is the single place in Dart that knows about the map's key names.
56	  /// Every consumer above this layer works with the sealed class instead.
57	  @override
58	  Stream<DeviceStateEvent> get deviceStateUpdates =>
59	      _deviceEvents.receiveBroadcastStream().map((e) {
60	        final map = Map<String, dynamic>.from(e as Map<Object?, Object?>);
61	        final nodeId = (map['nodeId'] as num?)?.toInt() ?? 0;
62	        return switch (map['type'] as String?) {
63	          'established' => SubscriptionEstablishedEvent(nodeId),
64	          'resubscribing' => SubscriptionResubscribingEvent(
65	            nodeId,
66	            (map['nextMs'] as num?)?.toInt() ?? 0,
67	          ),
68	          'error' => SubscriptionErrorEvent(
69	            nodeId,
70	            map['message'] as String? ?? 'unknown',
71	          ),
72	          'otaProgress' => OtaProgressEvent(
73	            nodeId,
74	            phase:    map['phase']    as String? ?? '',
75	            progress: (map['progress'] as num?)?.toInt(),
76	            message:  map['message']  as String?,
77	          ),
78	          // Default branch covers 'update' and any future attr event types.
79	          _ => SubscriptionUpdateEvent(nodeId, _stripEnvelope(map)),
80	        };
81	      });
82	
83	  /// Removes the envelope keys so [SubscriptionUpdateEvent.attrs] contains
84	  /// only the attribute payload (the keys defined in SubscriptionManager.kt).
85	  static Map<String, dynamic> _stripEnvelope(Map<String, dynamic> m) {
86	    final attrs = Map<String, dynamic>.from(m);
87	    attrs.remove('nodeId');
88	    attrs.remove('type');
89	    return attrs;
90	  }
91	
92	  // ── Subscription control ───────────────────────────────────────────────────
93	
94	  @override
95	  Future<bool> startSubscription(int nodeId) => _invoke('startSubscription', false, args: {'nodeId': nodeId});
96	
97	  @override
98	  Future<void> stopSubscription(int nodeId) => _invoke('stopSubscription', null, args: {'nodeId': nodeId});
99	
100	  // ── Parse setup payload ────────────────────────────────────────────────────
101	
102	  /// Parses a QR code or manual pairing code (11 or 21 digits).
103	  /// Returns null if the payload is invalid or the SDK is unavailable.
104	  @override
105	  Future<ParsedPayload?> parsePayload(String payload) => _invoke<ParsedPayload?>(
106	    'parsePayload',
107	    null,
108	    args: {'payload': payload},
109	    decode: (raw) {
110	      if (raw == null) return null;
111	      final map = Map<String, dynamic>.from(raw as Map<Object?, Object?>);
112	      DiscoveryCapability cap(String s) => switch (s) {
113	        'BLE' => DiscoveryCapability.ble,
114	        'ON_NETWORK' => DiscoveryCapability.onNetwork,
115	        'SOFT_AP' => DiscoveryCapability.softAp,
116	        'WIFI_PAF' => DiscoveryCapability.wifiPaf,
117	        'NFC' => DiscoveryCapability.nfc,
118	        _ => DiscoveryCapability.unknown,
119	      };
120	      return ParsedPayload(
121	        vendorId: map['vendorId'] as int,
122	        productId: map['productId'] as int,
123	        discriminator: map['discriminator'] as int,
124	        hasShortDiscriminator: map['hasShortDiscriminator'] as bool? ?? false,
125	        setupPinCode: map['setupPinCode'] as int? ?? 0,
126	        discoveryCapabilities:
