import 'dart:typed_data';

import 'package:flutter/material.dart';
import 'package:matter_home/services/controller_settings.dart';
import 'package:matter_home/services/hub_connection.dart';
import 'package:matter_home/services/flux_coap_service.dart';
import 'package:provider/provider.dart';

/// Read-only identity/health for one controller, plus the destructive
/// "Remove controller" action at the bottom.
///
/// Deliberately no Matter or Thread detail — those have their own screens
/// (Settings -> Controller -> Matter / Thread) and duplicating them here meant
/// two places to keep in sync.
class DeviceInfoScreen extends StatefulWidget {
  const DeviceInfoScreen({super.key, this.controllerId});

  /// Optional hint for the PSK lookup; falls back to the live service identity.
  final String? controllerId;

  @override
  State<DeviceInfoScreen> createState() => _DeviceInfoScreenState();
}

class _DeviceInfoScreenState extends State<DeviceInfoScreen> {
  ControllerInfo? _info;
  Uint8List?      _storedPsk;
  bool            _loaded = false;

  @override
  void initState() {
    super.initState();
    _load();
  }

  String _idFor(HubConnection hub) =>
      hub.service?.endpoint.dtlsIdentity ?? widget.controllerId ?? '';

  Future<void> _load() async {
    final hub = context.read<HubConnection>();
    final svc = hub.service;
    final info = svc == null ? null : await svc.getInfo();
    final psk  = await ControllerSettings.loadPsk(_idFor(hub));
    if (!mounted) return;
    setState(() {
      _info          = info;
      _storedPsk     = psk;
      _loaded        = true;
    });
  }

  Future<void> _remove() async {
    final confirm = await showDialog<bool>(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('Remove controller?'),
        content: const Text(
            'The pairing key will be deleted. The app will no longer connect to '
            'this controller until you add it again.'),
        actions: [
          TextButton(onPressed: () => Navigator.pop(context, false), child: const Text('Cancel')),
          TextButton(onPressed: () => Navigator.pop(context, true),  child: const Text('Remove')),
        ],
      ),
    );
    if (confirm != true || !mounted) return;
    final hub = context.read<HubConnection>();
    final id = _idFor(hub);
    if (id.isNotEmpty) {
      await ControllerSettings.clearController(id);
    } else {
      // No live service and no id hint — the usual case when this screen is
      // opened while the controller is unreachable. Clearing a single key here
      // would miss the real ctrl_psk_<id> and leave the hub "configured", so
      // forget every controller instead (there is only one active hub today).
      await ControllerSettings.clearAllControllers();
    }
    // Tear the connection down; do NOT hub.connect() — that re-runs mDNS and
    // would re-find the controller we just removed.
    await hub.forget();
    if (!mounted) return;
    Navigator.of(context).pop();   // back to Settings
    ScaffoldMessenger.of(context)
        .showSnackBar(const SnackBar(content: Text('Controller removed')));
  }

  static String _formatUptime(int seconds) {
    final d = seconds ~/ 86400;
    final h = (seconds % 86400) ~/ 3600;
    final m = (seconds % 3600) ~/ 60;
    if (d > 0) return '${d}d ${h}h';
    if (h > 0) return '${h}h ${m}m';
    return '${m}m';
  }

  String _pskSummary(Uint8List psk) =>
      '${psk.take(4).map((b) => b.toRadixString(16).padLeft(2, '0')).join()}…';

  Widget _row(String label, String value) => Padding(
        padding: const EdgeInsets.symmetric(vertical: 6),
        child: Row(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            SizedBox(width: 120,
                child: Text(label, style: TextStyle(
                    fontSize: 13,
                    color: Theme.of(context).colorScheme.onSurfaceVariant))),
            Expanded(child: Text(value,
                style: const TextStyle(fontSize: 13, fontFamily: 'monospace'))),
          ],
        ),
      );

  @override
  Widget build(BuildContext context) {
    final cs      = Theme.of(context).colorScheme;
    final version = _info?.firmwareVersion ?? '';

    return Scaffold(
      appBar: AppBar(title: const Text('Device info')),
      body: !_loaded
          ? const SizedBox.shrink()
          : ListView(
              padding: const EdgeInsets.symmetric(vertical: 8),
              children: [
                Card(
                  margin: const EdgeInsets.symmetric(horizontal: 16),
                  child: Padding(
                    padding: const EdgeInsets.fromLTRB(16, 12, 16, 12),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        _row('Name', _info?.hostname.isNotEmpty ?? false
                            ? _info!.hostname : (widget.controllerId ?? 'Controller')),
                        if (_info?.ethernetIp.isNotEmpty ?? false)
                          _row('IP address', _info!.ethernetIp),
                        if (version.isNotEmpty) _row('Firmware', version),
                        if ((_info?.uptimeSeconds ?? 0) > 0)
                          _row('Uptime', _formatUptime(_info!.uptimeSeconds)),
                        if (_storedPsk != null)
                          _row('Pairing key', '${_pskSummary(_storedPsk!)} (stored)'),
                      ],
                    ),
                  ),
                ),
                const SizedBox(height: 24),
                Padding(
                  padding: const EdgeInsets.symmetric(horizontal: 16),
                  child: OutlinedButton.icon(
                    onPressed: _remove,
                    icon: const Icon(Icons.delete_outline),
                    label: const Text('Remove controller'),
                    style: OutlinedButton.styleFrom(
                      foregroundColor: cs.error,
                      side: BorderSide(color: cs.error.withValues(alpha: 0.5)),
                      minimumSize: const Size.fromHeight(48),
                    ),
                  ),
                ),
              ],
            ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:matter_home/services/hub_connection.dart';
import 'package:matter_home/ui/screens/settings/remote_access_screen.dart';
import 'package:provider/provider.dart';

// Connection-state accents (shared with the Settings panels).
const _onlineColor     = Color(0xFF9FD8A8); // green
const _remoteColor     = Color(0xFFA9C7F2); // blue
const _connectingColor = Color(0xFFBFC4CC); // grey
const _offlineColor    = Color(0xFFF2A9A0); // coral

/// Connection detail — how this phone is reaching the controller right now,
/// broken out into its two independent paths: the local network and the
/// remote (off-LAN) tunnel. Reached from the connection widget in Settings.
class ConnectionScreen extends StatefulWidget {
  const ConnectionScreen({super.key});

  @override
  State<ConnectionScreen> createState() => _ConnectionScreenState();
}

class _ConnectionScreenState extends State<ConnectionScreen> {
  bool?   _remoteEnabled;   // null → couldn't read the controller's config
  String? _rendezvous;
  String? _relay;

  @override
  void initState() {
    super.initState();
    _loadConfig();
  }

  Future<void> _loadConfig() async {
    final svc = context.read<HubConnection>().service;
    final cfg = svc == null ? null : await svc.getRemoteConfig();
    if (!mounted) return;
    setState(() {
      _remoteEnabled = cfg?.enabled;
      _rendezvous = (cfg?.rendezvousUrl.isNotEmpty ?? false)
          ? cfg!.rendezvousUrl
          : HubConnection.defaultRendezvousUrl;
      _relay = (cfg?.turn.isNotEmpty ?? false)
          ? '${cfg!.turn.first.host}:${cfg.turn.first.port}'
          : (HubConnection.defaultTurnHost.isNotEmpty
              ? HubConnection.defaultTurnHost
              : null);
    });
  }

  @override
  Widget build(BuildContext context) {
    final cs   = Theme.of(context).colorScheme;
    final hub  = context.watch<HubConnection>();
    final kind = hub.connectionKind;
    final ep   = hub.service?.endpoint;

    final (Color dot, String headline, String detail) = switch (hub.status) {
      ControllerStatus.online => kind == ConnectionKind.remote
          ? (_remoteColor, 'Connected', 'Remote · encrypted tunnel')
          : (_onlineColor, 'Connected', 'Local network'),
      ControllerStatus.connecting => (_connectingColor, 'Connecting…', ''),
      ControllerStatus.offline    => (_offlineColor, 'Offline', 'Controller unreachable'),
      ControllerStatus.noHub      => (_connectingColor, 'Not set up', ''),
    };

    // Per-path state.
    final localState = switch (hub.status) {
      ControllerStatus.online when kind == ConnectionKind.local => ('Active', _onlineColor),
      ControllerStatus.online     => ('Standby', _connectingColor),
      ControllerStatus.connecting => ('Connecting…', _connectingColor),
      _                           => ('Not connected', _offlineColor),
    };
    final (String remoteText, Color remoteDot) = _remoteEnabled == false
        ? ('Off', _connectingColor)
        : kind == ConnectionKind.remote
            ? ('Active tunnel', _remoteColor)
            : _remoteEnabled == true
                ? ('Standby', _connectingColor)
                : ('Unknown', _connectingColor);

    return Scaffold(
      appBar: AppBar(title: const Text('Connection')),
      body: ListView(
        children: [
          const SizedBox(height: 24),

          // ── Big current-state block ──────────────────────────────────────
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 24),
            child: Row(
              children: [
                Container(width: 14, height: 14,
                    decoration: BoxDecoration(shape: BoxShape.circle, color: dot)),
                const SizedBox(width: 14),
                Column(
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(headline, style: const TextStyle(fontSize: 22, fontWeight: FontWeight.w600)),
                    if (detail.isNotEmpty)
                      Text(detail, style: TextStyle(fontSize: 13, color: cs.onSurfaceVariant)),
                  ],
                ),
              ],
            ),
          ),

          const SizedBox(height: 32),

          // ── Local network ────────────────────────────────────────────────
          _label(cs, 'LOCAL NETWORK'),
          Card(
            margin: const EdgeInsets.symmetric(horizontal: 16),
            child: Column(children: [
              _stateRow(cs, 'State', localState.$1, localState.$2),
              _divider(cs),
              _valueRow(cs, 'Address',
                  kind == ConnectionKind.local && ep != null ? '${ep.host}:${ep.port}' : '—'),
            ]),
          ),

          const SizedBox(height: 24),

          // ── Remote access ────────────────────────────────────────────────
          _label(cs, 'REMOTE ACCESS'),
          Card(
            margin: const EdgeInsets.symmetric(horizontal: 16),
            clipBehavior: Clip.antiAlias,
            child: Column(children: [
              _stateRow(cs, 'State', remoteText, remoteDot),
              _divider(cs),
              _valueRow(cs, 'Rendezvous', _rendezvous ?? '…'),
              _divider(cs),
              _valueRow(cs, 'Relay', _relay ?? 'none'),
              _divider(cs),
              ListTile(
                title: const Text('Configure remote access'),
                trailing: const Icon(Icons.chevron_right),
                onTap: () => Navigator.push(context,
                    MaterialPageRoute<void>(builder: (_) => const RemoteAccessScreen())),
              ),
            ]),
          ),

          // ── Last connection metrics ──────────────────────────────────────
          const SizedBox(height: 20),
          _label(cs, 'LAST CONNECTION'),
          Card(
            margin: const EdgeInsets.symmetric(horizontal: 16),
            clipBehavior: Clip.antiAlias,
            child: Column(children: [
              _valueRow(cs, 'Attempt',
                  hub.lastConnectAt == null
                      ? 'none yet'
                      : '${hub.lastConnectOk == true ? "ok" : "failed"}'
                          ' · ${_ago(hub.lastConnectAt!)} ago'),
              _divider(cs),
              _valueRow(cs, 'Setup time', _ms(hub.lastConnectDuration)),
              _divider(cs),
              _valueRow(cs, 'Via',
                  hub.lastConnectKind == null || hub.lastConnectOk != true
                      ? '—'
                      : hub.lastConnectKind == ConnectionKind.remote
                          ? 'remote tunnel'
                          : 'local network'),
              _divider(cs),
              _valueRow(cs, 'Heartbeat',
                  hub.lastProbeAt == null
                      ? '—'
                      : hub.lastProbeRtt != null
                          ? '${_ms(hub.lastProbeRtt)} · ${_ago(hub.lastProbeAt!)} ago'
                          : 'failed · ${_ago(hub.lastProbeAt!)} ago'),
              _divider(cs),
              _valueRow(cs, 'Attempts',
                  '${hub.connectAttempts} total · ${hub.connectFailures} failed'),
              if (hub.probeFailStreak > 0) ...[
                _divider(cs),
                _valueRow(cs, 'Missed beats', '${hub.probeFailStreak}'),
              ],
              if (hub.lastConnectError != null) ...[
                _divider(cs),
                _valueRow(cs, 'Last error', hub.lastConnectError!),
              ],
            ]),
          ),

          const SizedBox(height: 40),
        ],
      ),
    );
  }

  Widget _label(ColorScheme cs, String text) => Padding(
        padding: const EdgeInsets.fromLTRB(20, 0, 20, 10),
        child: Text(text, style: TextStyle(
            fontFamily: 'monospace', fontSize: 12, fontWeight: FontWeight.w700,
            letterSpacing: 2.4, color: cs.onSurfaceVariant)),
      );

  Widget _stateRow(ColorScheme cs, String label, String value, Color dot) => ListTile(
        title: Text(label, style: TextStyle(fontSize: 14, color: cs.onSurfaceVariant)),
        trailing: Row(mainAxisSize: MainAxisSize.min, children: [
          Container(width: 8, height: 8,
              decoration: BoxDecoration(shape: BoxShape.circle, color: dot)),
          const SizedBox(width: 8),
          Text(value, style: const TextStyle(fontSize: 14, fontWeight: FontWeight.w600)),
        ]),
      );

  Widget _valueRow(ColorScheme cs, String label, String value) => ListTile(
        title: Text(label, style: TextStyle(fontSize: 14, color: cs.onSurfaceVariant)),
        trailing: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 220),
          child: Text(value, textAlign: TextAlign.right, overflow: TextOverflow.ellipsis,
              style: const TextStyle(fontFamily: 'monospace', fontSize: 12.5)),
        ),
      );

  Widget _divider(ColorScheme cs) =>
      Divider(height: 1, indent: 16, endIndent: 16, color: cs.outlineVariant);

  static String _ms(Duration? d) => d == null
      ? '—'
      : d.inMilliseconds < 1000
          ? '${d.inMilliseconds} ms'
          : '${(d.inMilliseconds / 1000).toStringAsFixed(1)} s';

  static String _ago(DateTime t) {
    final s = DateTime.now().difference(t).inSeconds;
    if (s < 60) return '${s}s';
    if (s < 3600) return '${s ~/ 60}m';
    return '${s ~/ 3600}h';
  }
}

import 'dart:async';
import 'dart:isolate';

import 'package:flutter/foundation.dart';

import 'package:matter_home/services/controller_transport/_transport_isolate.dart';
import 'package:matter_home/services/controller_transport/controller_transport.dart';
import 'package:matter_home/services/controller_transport/in_process_transport.dart';

/// [ControllerTransport] that runs the CoAP/DTLS client on a **background
/// isolate**, so the DTLS handshake/crypto can never block the UI thread.
///
/// If the isolate fails to start (or dies), it transparently degrades to an
/// in-process client — functionally identical to before, never worse.
class IsolateTransport implements ControllerTransport {
  IsolateTransport(this.endpoint) {
    unawaited(_spawn());
  }

  final FluxControllerEndpoint endpoint;

  final _ready = Completer<void>();
  Isolate?  _isolate;
  SendPort? _cmd;                       // set when the isolate is usable
  InProcessTransport? _fallback;        // set when we degrade to in-process
  bool _disposed = false;

  int _nextId = 0;
  int _nextObserveId = 0;
  final _pending      = <int, Completer<TransportResponse>>{};
  final _reconnects   = <int, Completer<void>>{};
  final _observeCtrls = <int, StreamController<TransportEvent>>{};

  // Retained so dispose() can close them — an open ReceivePort keeps the
  // isolate's message queue (and this object) alive.
  ReceivePort? _rx;
  ReceivePort? _errors;
  ReceivePort? _exits;

  Future<void> _spawn() async {
    final rx = ReceivePort();
    rx.listen(_onMessage);
    final errors = ReceivePort()..listen((_) => _degrade('isolate error'));
    final exits  = ReceivePort()..listen((_) => _degrade('isolate exit'));
    _rx = rx;
    _errors = errors;
    _exits = exits;
    try {
      _isolate = await Isolate.spawn(
        transportIsolateEntry,
        TransportInit(rx.sendPort, endpoint),
        onError: errors.sendPort,
        onExit:  exits.sendPort,
        debugName: 'flux-controller-transport',
      );
    } on Object catch (e) {
      _degrade('spawn failed: $e');
    }
  }

  void _onMessage(dynamic msg) {
    if (msg is TransportReady) {
      if (msg.ok) {
        _cmd = msg.commandPort;
        if (!_ready.isCompleted) _ready.complete();
      } else {
        _degrade('isolate reported client build failure');
      }
    } else if (msg is RespMsg) {
      _pending.remove(msg.id)?.complete(msg.response);
    } else if (msg is EventMsg) {
      final c = _observeCtrls[msg.observeId];
      if (c == null || c.isClosed) return;
      c.add(msg.event);
      if (msg.event.kind == TransportEventKind.done) {
        _observeCtrls.remove(msg.observeId);
        c.close();
      }
    } else if (msg is DoneMsg) {
      _reconnects.remove(msg.id)?.complete();
    }
  }

  /// Fall back to an in-process client and fail-forward everything in flight.
  void _degrade(String reason) {
    if (_disposed || _fallback != null) return;
    debugPrint('IsolateTransport: degrading to in-process ($reason)');
    _fallback = InProcessTransport(endpoint);
    _cmd = null;
    if (!_ready.isCompleted) _ready.complete();
    for (final c in _pending.values) {
      if (!c.isCompleted) c.complete(TransportResponse.unreachable);
    }
    _pending.clear();
    for (final c in _reconnects.values) {
      if (!c.isCompleted) c.complete();
    }
    _reconnects.clear();
    // Nudge live observers so callers re-subscribe (which will use the fallback).
    for (final ctrl in _observeCtrls.values) {
      if (!ctrl.isClosed) {
        ctrl.add(const TransportEvent(TransportEventKind.error,
            error: 'transport degraded'));
      }
    }
  }

  /// Grace added to the caller's own timeout before the main isolate gives up on
  /// its own. The request timeout is enforced *inside* the isolate, so if the
  /// isolate dies, is killed mid-request (dispose), or a reply is ever lost, the
  /// completer would otherwise never complete and `await` would hang forever.
  static const _deadlineSlack = Duration(seconds: 5);

  @override
  Future<TransportResponse> request(TransportRequest r) async {
    await _ready.future;
    if (_fallback != null) return _fallback!.request(r);
    // Never enqueue onto a dead isolate — the send would vanish silently.
    if (_disposed) return TransportResponse.unreachable;
    final id = _nextId++;
    final c = Completer<TransportResponse>();
    _pending[id] = c;
    _cmd!.send(ReqMsg(id, r));
    return c.future.timeout(
      Duration(milliseconds: r.timeoutMs) + _deadlineSlack,
      onTimeout: () {
        // Drop the orphan so the map cannot grow without bound.
        _pending.remove(id);
        debugPrint('IsolateTransport: no reply for ${r.path} within deadline');
        return TransportResponse.unreachable;
      },
    );
  }

  @override
  Stream<TransportEvent> observe(String path, {Map<String, String>? query}) {
    final id   = _nextObserveId++;
    final ctrl = StreamController<TransportEvent>();
    _observeCtrls[id] = ctrl;

    unawaited(_ready.future.then((_) {
      if (ctrl.isClosed) return;
      if (_fallback != null) {
        final sub = _fallback!
            .observe(path, query: query)
            .listen(ctrl.add, onError: ctrl.addError, onDone: ctrl.close);
        ctrl.onCancel = () {
          _observeCtrls.remove(id);
          return sub.cancel();
        };
      } else {
        ctrl.onCancel = () {
          _observeCtrls.remove(id);
          _cmd?.send(CancelObserveMsg(id));
        };
        _cmd!.send(ObserveMsg(id, path, query));
      }
    }));

    return ctrl.stream;
  }

  @override
  Future<void> reconnect() async {
    await _ready.future;
    if (_fallback != null) return _fallback!.reconnect();
    final id = _nextId++;
    final c = Completer<void>();
    _reconnects[id] = c;
    _cmd!.send(ReconnectMsg(id));
    return c.future;
  }

  @override
  Future<void> dispose() async {
    _disposed = true;
    _cmd?.send(const DisposeMsg());
    await _fallback?.dispose();

    // Fail everything still in flight. The isolate is about to be killed and
    // will never reply, so leaving these pending strands the caller forever —
    // e.g. a service swap mid-request used to permanently wedge
    // DeviceProvider.syncWithController (its `finally` never ran).
    for (final c in _pending.values) {
      if (!c.isCompleted) c.complete(TransportResponse.unreachable);
    }
    _pending.clear();
    for (final c in _reconnects.values) {
      if (!c.isCompleted) c.complete();
    }
    _reconnects.clear();

    for (final ctrl in _observeCtrls.values) {
      if (!ctrl.isClosed) await ctrl.close();
    }
    _observeCtrls.clear();
    // Give the isolate a moment to dispose its client, then kill it and release
    // the ports (they keep the isolate's message queue alive otherwise).
    Future.delayed(const Duration(seconds: 1), () {
      _isolate?.kill();
      _isolate = null;
      _rx?.close();
      _errors?.close();
      _exits?.close();
    });
  }
}

