206	// ── Painter ────────────────────────────────────────────────────────────────
207	class _PriceChartPainter extends CustomPainter {
208	  _PriceChartPainter({
209	    required this.prices,
210	    required this.history,
211	    required this.now,
212	    required this.axisColor,
213	    required this.labelColor,
214	  });
215	
216	  final EnergyPrices prices;
217	  final EnergyHistoryData? history;
218	  final DateTime now;
219	  final Color axisColor;
220	  final Color labelColor;
221	
222	  static const _padBottom = 18.0;
223	  static const _padTop = 8.0;
224	  static const _padLeft = 28.0; // room for the ct/kWh axis labels
225	
226	  @override
227	  void paint(Canvas canvas, Size size) {
228	    final pts = prices.points;
229	    if (pts.isEmpty) return;
230	
231	    final plotH = size.height - _padBottom - _padTop;
232	    final plotW = size.width - _padLeft;
233	
234	    final resMs = prices.resolution.inMilliseconds;
235	    final coverStart = pts.first.time.millisecondsSinceEpoch;
236	    final coverEnd = pts.last.time.millisecondsSinceEpoch + resMs;
237	
238	    // Window to ~now ±12h so past consumption and upcoming prices share the view.
239	    const half = 12 * 3600 * 1000;
240	    final nowMs = now.millisecondsSinceEpoch;
241	    var startMs = nowMs - half < coverStart ? coverStart : nowMs - half;
242	    var endMs = nowMs + half > coverEnd ? coverEnd : nowMs + half;
243	    if (endMs <= startMs) { startMs = coverStart; endMs = coverEnd; }
244	    final span = (endMs - startMs).toDouble();
245	    double x(int ms) => _padLeft + plotW * (ms - startMs) / span;
246	
247	    // Price Y scale — include 0, round the top (and bottom, if negative) to a
248	    // nice value so the gridline labels are tidy.
249	    final rawHi = prices.maxCt > 0 ? prices.maxCt : 1.0;
250	    final rawLo = prices.minCt < 0 ? prices.minCt : 0.0;
251	    final step = _niceStep((rawHi - rawLo) / 4);
252	    final hi = (rawHi / step).ceil() * step;
253	    final lo = (rawLo / step).floor() * step;
254	    final range = (hi - lo) <= 0 ? 1.0 : (hi - lo);
255	    double yPrice(double ct) => _padTop + plotH * (1 - (ct - lo) / range);
256	
257	    // Horizontal gridlines + ct/kWh labels.
258	    final tp = TextPainter(textDirection: TextDirection.ltr);
259	    final gridPaint = Paint()..color = axisColor..strokeWidth = 1;
260	    for (var v = lo; v <= hi + 0.001; v += step) {
261	      final gy = yPrice(v);
262	      canvas.drawLine(Offset(_padLeft, gy), Offset(size.width, gy),
263	          gridPaint..color = axisColor.withValues(alpha: v == 0 ? 0.5 : 0.22));
264	      tp
265	        ..text = TextSpan(
266	            text: step >= 1 ? v.toStringAsFixed(0) : v.toStringAsFixed(1),
267	            style: TextStyle(color: labelColor, fontSize: 9))
268	        ..layout();
269	      tp.paint(canvas, Offset(_padLeft - tp.width - 4, gy - tp.height / 2));
270	    }
271	
272	    // Clip data traces to the plot rect so lines/steps never spill past the
273	    // axes into the padding or neighbouring widgets.
274	    canvas.save();
275	    canvas.clipRect(Rect.fromLTRB(_padLeft, _padTop, size.width, _padTop + plotH));
276	
277	    // Price as a stepped line — each interval held flat at its price, with
278	    // risers at the interval boundaries (no fill).
279	    final priceLine = Path();
280	    var startedPrice = false;
281	    for (final p in pts) {
282	      final x0 = x(p.time.millisecondsSinceEpoch);
283	      final x1 = x(p.time.millisecondsSinceEpoch + resMs);
284	      final yv = yPrice(p.ctPerKwh);
285	      if (!startedPrice) {
286	        priceLine.moveTo(x0, yv);
287	        startedPrice = true;
288	      } else {
289	        priceLine.lineTo(x0, yv); // riser to this interval's level
290	      }
291	      priceLine.lineTo(x1, yv);    // hold flat across the interval
292	    }
293	    canvas.drawPath(
294	        priceLine,
295	        Paint()
296	          ..color = _priceColor
297	          ..style = PaintingStyle.stroke
298	          ..strokeWidth = 2.5
299	          ..strokeJoin = StrokeJoin.round
300	          ..isAntiAlias = true);
301	
302	    // Grid import + export overlays (shared scale), only over covered time.
303	    final h = history;
304	    if (h != null && h.points.isNotEmpty) {
305	      var flowMax = 0.0;
306	      for (final hp in h.points) {
307	        if (hp.gridImportW > flowMax) flowMax = hp.gridImportW;
308	        if (hp.gridExportW > flowMax) flowMax = hp.gridExportW;
309	      }
310	      if (flowMax > 0) {
311	        void trace(double Function(EnergyHistoryPoint) sel, Color c) {
312	          final line = Path();
313	          var started = false;
314	          for (final hp in h.points) {
315	            final ms = hp.time.millisecondsSinceEpoch;
316	            if (ms < startMs || ms > endMs) continue;
317	            final px = x(ms);
318	            final py = _padTop + plotH * (1 - 0.85 * (sel(hp) / flowMax));
319	            if (!started) { line.moveTo(px, py); started = true; }
320	            else { line.lineTo(px, py); }
321	          }
322	          canvas.drawPath(
323	              line,
324	              Paint()
325	                ..color = c
326	                ..style = PaintingStyle.stroke
327	                ..strokeWidth = 2
328	                ..strokeJoin = StrokeJoin.round
329	                ..isAntiAlias = true);
330	        }
331	        trace((hp) => hp.gridExportW, _exportColor);
332	        trace((hp) => hp.gridImportW, _importColor);
333	      }
334	    }
335	
336	    // "Now" marker + current price label.
337	    if (nowMs >= startMs && nowMs <= endMs) {
338	      final nx = x(nowMs);
339	      canvas.drawLine(Offset(nx, _padTop), Offset(nx, _padTop + plotH),
340	          Paint()..color = labelColor.withValues(alpha: 0.7)..strokeWidth = 1);
341	    }
342	
343	    canvas.restore(); // end plot clip
344	
345	    // Vertical time gridlines + labels every 3 hours across the window, so the
346	    // time scale is readable (midnight is emphasised).
347	    for (final p in pts) {
348	      final t = p.time;
349	      final ms = t.millisecondsSinceEpoch;
350	      if (ms < startMs || ms > endMs) continue;
351	      if (t.minute != 0 || t.hour % 3 != 0) continue;
352	      final lx = x(ms);
353	      final midnight = t.hour == 0;
354	      canvas.drawLine(Offset(lx, _padTop), Offset(lx, _padTop + plotH),
355	          Paint()
356	            ..color = axisColor.withValues(alpha: midnight ? 0.45 : 0.20)
357	            ..strokeWidth = 1);
358	      tp
359	        ..text = TextSpan(
360	            text: '${t.hour.toString().padLeft(2, '0')}:00',
361	            style: TextStyle(
362	                color: labelColor,
363	                fontSize: 8.5,
364	                fontWeight: midnight ? FontWeight.w700 : FontWeight.w400))
365	        ..layout();
366	      tp.paint(canvas, Offset(lx - tp.width / 2, size.height - tp.height));
367	    }
368	  }
369	
370	  /// Round [v] up to a tidy 1/2/5 × 10^k step for the price axis.
371	  double _niceStep(double v) {
372	    if (v <= 0) return 1;
373	    var mag = 1.0;
374	    while (mag * 10 <= v) {
375	      mag *= 10;
376	    }
377	    for (final m in [1.0, 2.0, 5.0, 10.0]) {
378	      if (mag * m >= v) return mag * m;
379	    }
380	    return mag * 10;
381	  }
382	
383	  @override
384	  bool shouldRepaint(_PriceChartPainter old) =>
385	      old.prices != prices || old.history != history || old.now != now;
386	}
