/* ── Fetch ───────────────────────────────────────────────────────────────── */

static esp_err_t do_fetch(const flux_PricingConfig *cfg, int64_t now)
{
    const flux_price_provider_t *p = flux_prices_provider_find(cfg->provider);
    if (!p) {
        ESP_LOGW(TAG, "unknown provider '%s'", cfg->provider);
        return ESP_ERR_INVALID_ARG;
    }
    flux_PriceCurve tmp;   /* ~0.8 KB — fits the task stack */
    esp_err_t err = p->fetch(cfg, now, now + FETCH_LOOKAHEAD_S, &tmp);
    if (err != ESP_OK) return err;
    if (tmp.prices_count == 0 || tmp.resolution_seconds == 0) return ESP_ERR_INVALID_RESPONSE;

    tmp.fetched_at = now;
    tmp.stale      = false;

    lock();
    s_curve      = tmp;
    s_have_curve = true;
    unlock();

    nvs_save_blob(NVS_KEY_CURVE, flux_PriceCurve_fields, &tmp, flux_PriceCurve_size);

    int64_t end = tmp.start_epoch + (int64_t)tmp.prices_count * tmp.resolution_seconds;
    ESP_LOGI(TAG, "curve updated: %u intervals @%us, covers %lld..%lld (%.1fh ahead)",
             (unsigned)tmp.prices_count, (unsigned)tmp.resolution_seconds,
             (long long)tmp.start_epoch, (long long)end, (double)(end - now) / 3600.0);

