/*
 * flux_prices_awattar — aWATTar day-ahead provider (DE/AT).
 *
 * Free, no API key. GET https://api.awattar.de|at/v1/marketdata returns raw EPEX
 * spot in hourly intervals as JSON:
 *   {"object":"list","data":[
 *     {"start_timestamp":<ms>,"end_timestamp":<ms>,"marketprice":68.9,"unit":"Eur/MWh"}, ...]}
 * marketprice is EUR/MWh (may be negative) → stored as µEUR/kWh (×1000).
 */
#include "flux_prices_provider.h"
#include "flux_prices_http.h"

#include <math.h>
#include <string.h>
#include <stdio.h>
#include <strings.h>

#include "cJSON.h"
#include "esp_log.h"

static const char *TAG = "flux_awattar";

#define AWATTAR_MAX_BODY  (64 * 1024)

static esp_err_t awattar_fetch(const flux_PricingConfig *cfg,
                               int64_t want_from, int64_t want_to,
                               flux_PriceCurve *out)
{
    (void)want_to;
    const char *host = "api.awattar.de";
    if (cfg->zone[0] && strcasecmp(cfg->zone, "AT") == 0) host = "api.awattar.at";

    /* start filters to entries at/after `want_from` (ms). Floor to the top of the
     * hour so the CURRENT interval is included (aWATTar drops intervals whose
     * start precedes `start`) — otherwise flux_prices_at(now) has no coverage
     * until the next hour. end omitted → provider returns today + tomorrow. */
    int64_t from = want_from > 0 ? want_from - (want_from % 3600) : 0;
    char url[128];
    snprintf(url, sizeof(url), "https://%s/v1/marketdata?start=%lld000",
             host, (long long)from);

    char  *body = NULL;
    size_t len  = 0;
    esp_err_t err = flux_prices_http_get(url, &body, &len, AWATTAR_MAX_BODY);
    if (err != ESP_OK) return err;

    cJSON *root = cJSON_Parse(body);
    free(body);
    if (!root) return ESP_ERR_INVALID_RESPONSE;

    cJSON *data = cJSON_GetObjectItem(root, "data");
    if (!cJSON_IsArray(data)) { cJSON_Delete(root); return ESP_ERR_INVALID_RESPONSE; }

    const int cap = (int)(sizeof(out->prices) / sizeof(out->prices[0]));
    memset(out, 0, sizeof(*out));
    out->unit = flux_PriceUnit_PRICE_UNIT_UEUR_PER_KWH;
    strlcpy(out->currency, "EUR", sizeof(out->currency));

    int     count = 0;
    int64_t first_start = 0, res = 3600;
    int     n = cJSON_GetArraySize(data);
    for (int i = 0; i < n && count < cap; i++) {
        cJSON *it = cJSON_GetArrayItem(data, i);
        cJSON *st = cJSON_GetObjectItem(it, "start_timestamp");
        cJSON *en = cJSON_GetObjectItem(it, "end_timestamp");
        cJSON *mp = cJSON_GetObjectItem(it, "marketprice");
        if (!cJSON_IsNumber(st) || !cJSON_IsNumber(mp)) continue;

        int64_t s = (int64_t)(st->valuedouble) / 1000;   /* ms → s */
        if (count == 0) {
            first_start = s;
            if (cJSON_IsNumber(en)) {
                int64_t e = (int64_t)(en->valuedouble) / 1000;
                if (e > s) res = e - s;
            }
        }
        /* EUR/MWh → µEUR/kWh (×1000), round to nearest, clamped to int32 so a
         * malformed/out-of-range marketprice can't wrap into a garbage price. */
        double up = mp->valuedouble * 1000.0;
        if (up >  2147483647.0) up =  2147483647.0;
        if (up < -2147483648.0) up = -2147483648.0;
        out->prices[count++] = (int32_t)llround(up);
    }
    cJSON_Delete(root);

    if (count == 0) return ESP_ERR_NOT_FOUND;
    out->start_epoch        = first_start;
    out->resolution_seconds = (uint32_t)res;
    out->prices_count       = (pb_size_t)count;
    ESP_LOGI(TAG, "%s: %d intervals @%llds from %lld", host, count,
             (long long)res, (long long)first_start);
    return ESP_OK;
}

const flux_price_provider_t flux_prices_provider_awattar = {
    .name  = "awattar",
    .fetch = awattar_fetch,
};

