extern "C" void flux_device_fetch_metadata(uint64_t node_id)
{
    if (flux_is_modbus_node(node_id)) return;  /* not a Matter node — no CASE read */
    auto *nid_p = new (std::nothrow) uint64_t(node_id);
    if (!nid_p) return;
    CHIP_ERROR cerr = chip::DeviceLayer::PlatformMgr().ScheduleWork(
        [](intptr_t ctx) {
            uint64_t nid = *reinterpret_cast<uint64_t *>(ctx);
            delete reinterpret_cast<uint64_t *>(ctx);

            chip::Platform::ScopedMemoryBufferWithSize<chip::app::AttributePathParams> paths;
            chip::Platform::ScopedMemoryBufferWithSize<chip::app::EventPathParams>     evts;
            paths.Alloc(3);
            if (!paths.Get()) return;
            paths[0] = chip::app::AttributePathParams(0, 0x0028, 0x0002); /* VendorID       */
            paths[1] = chip::app::AttributePathParams(0, 0x0028, 0x0004); /* ProductID      */
            paths[2] = chip::app::AttributePathParams(0, 0x001D, 0x0000); /* DeviceTypeList */

            using namespace esp_matter::controller;
            auto *cmd = chip::Platform::New<read_command>(
                nid,
                std::move(paths),
                std::move(evts),
                attribute_report_cb_t(attr_report_cb),
                nullptr,
                nullptr);
            if (cmd) {
                cmd->send_command();
                ESP_LOGI(TAG, "metadata read queued for %016llx",
                         (unsigned long long)nid);
            } else {
                ESP_LOGE(TAG, "metadata read: alloc failed for %016llx",
                         (unsigned long long)nid);
            }
        },
        reinterpret_cast<intptr_t>(nid_p));
    if (cerr != CHIP_NO_ERROR) {
        ESP_LOGE(TAG, "ScheduleWork(metadata) failed: %s", cerr.AsString());
        delete nid_p;
