/* Discovery + PASE + commissioning delegate. Reused across calls (CHIP
 * delegates are registered/unregistered per attempt, not per-instance). */
class FluxCommissionDelegate : public chip::Controller::DevicePairingDelegate,
                                public chip::Controller::DeviceDiscoveryDelegate {
public:
    void OnDiscoveredDevice(const chip::Dnssd::CommissionNodeData &nodeData) override
    {
        if (!s_ctx || s_ctx->pase_started) return;
        ESP_LOGI(TAG, "OnDiscoveredDevice: disc=%u cm=%u",
                 (unsigned)nodeData.longDiscriminator, (unsigned)nodeData.commissioningMode);
        /* We browse all commissionable nodes (kNone) and match the requested
         * discriminator client-side. This browse only sees LAN advertisements
         * (Wi-Fi/Ethernet devices, or Thread devices proxied by another
         * ecosystem's border router) — devices on OUR mesh are matched from
         * the SRP server table instead, because our own OTBR's SRP->mDNS proxy
         * (1) omits the L<disc> subtype PTR and (2) strips the D=/CM TXT, so
         * their mDNS echo resolves as disc=0 cm=0. For the same reason we do
         * NOT gate on commissioningMode — a discriminator match is the signal. */
        if (!disc_matches(nodeData.longDiscriminator)) return;

        char addr_buf[chip::Inet::IPAddress::kMaxStringLength];
        nodeData.ipAddress[0].ToString(addr_buf);
        ESP_LOGI(TAG, "discovered device via mDNS: %s:%u", addr_buf, nodeData.port);

        chip::Inet::InterfaceId ifc =
            nodeData.ipAddress[0].IsIPv6LinkLocal() ? nodeData.interfaceId : chip::Inet::InterfaceId::Null();
        start_pase(chip::Transport::PeerAddress::UDP(nodeData.ipAddress[0], nodeData.port, ifc));
    }

    void OnPairingComplete(CHIP_ERROR error) override
    {
        if (error != CHIP_NO_ERROR) {
            char buf[128];
            snprintf(buf, sizeof(buf), "PASE failed: %s", error.AsString());
            ESP_LOGE(TAG, "%s", buf);
            finish(false, buf);
        }
        /* On success, commissioning continues automatically (AutoCommissioner)
         * through AddNOC (flux_creds_issuer) to OnCommissioningSuccess/Failure. */
    }

    /* Fires after every AutoCommissioner stage — streamed to the app via the
     * observable GET /commission/events so the progress track advances while
     * the controller commissions. Stage names (StageToString) are the same
     * ones the phone SDK reports, so the app maps them with its existing
     * stage table. Advisory only; failures are finalized by the delegates. */
    void OnCommissioningStatusUpdate(chip::PeerId peerId,
                                     chip::Controller::CommissioningStage stageCompleted,
                                     CHIP_ERROR error) override
    {
        const char *stage = chip::Controller::StageToString(stageCompleted);
        if (error != CHIP_NO_ERROR) {
            flux_events_emit_commission(stage, true, error.AsString());
        } else {
            flux_events_emit_commission(stage, false, nullptr);
        }
    }

