/* Only one commission at a time: s_ctx is still set while a prior attempt is
 * in flight (or abandoned-but-not-yet-cleaned after a timeout). Reject rather
 * than clobber s_ctx, which would orphan the in-flight context. */
if (s_ctx != nullptr) {
    xSemaphoreGive(s_claim_mux);
    flux_async_deinit(&ctx->async); delete ctx;
    snprintf(error_buf, error_buf_len, "commission already in progress");
    return ESP_ERR_INVALID_STATE;
}

s_ctx = ctx;
xSemaphoreGive(s_claim_mux);

auto *w = new (std::nothrow) CommissionWorkCtx{};
if (w) {
    w->passcode      = passcode;
    w->discriminator = discriminator;
    w->short_disc    = short_discriminator;
    w->node_id       = node_id;
}
if (!w) {
    xSemaphoreTake(s_claim_mux, portMAX_DELAY);
    s_ctx = nullptr;
    xSemaphoreGive(s_claim_mux);
    flux_async_deinit(&ctx->async); delete ctx;
    snprintf(error_buf, error_buf_len, "oom");
    return ESP_ERR_NO_MEM;
}

CHIP_ERROR cerr = chip::DeviceLayer::PlatformMgr().ScheduleWork(
    commission_work, reinterpret_cast<intptr_t>(w));
if (cerr != CHIP_NO_ERROR) {
    delete w;
    xSemaphoreTake(s_claim_mux, portMAX_DELAY);
    s_ctx = nullptr;
    xSemaphoreGive(s_claim_mux);
    flux_async_deinit(&ctx->async); delete ctx;
    snprintf(error_buf, error_buf_len, "ScheduleWork: %s", cerr.AsString());
    return ESP_FAIL;
}

/* Discovery + PASE + full commissioning (incl. AddNOC + the final operational
 * CASE for CommissioningComplete) can take well over a minute on a Thread mesh:
 * the device often promotes to a Thread router right after AddNOC, and the
 * operational DNS-SD resolve can time out (~45s) and retry while it settles.
 * CHIP re-arms the device fail-safe to 120s for that, so we wait to match
 * rather than abandoning a commission that is still progressing. */
if (!flux_async_wait(&ctx->async, 120000)) {
    /* Timed out — ownership was handed to finish(), which frees ctx when the
     * still-pending commission eventually completes. */
    snprintf(error_buf, error_buf_len, "commission timed out");

    chip::DeviceLayer::PlatformMgr().ScheduleWork(
        [](intptr_t arg) {
            auto nid = static_cast<chip::NodeId>(arg);
            auto &ci = matter_controller_client::get_instance();
            CHIP_ERROR e = ci.get_commissioner()->StopPairing(nid);
            ci.get_commissioner()->RegisterPairingDelegate(nullptr);
            ci.get_commissioner()->RegisterDeviceDiscoveryDelegate(nullptr);
            chip::DeviceLayer::SystemLayer().CancelTimer(srp_poll_cb, nullptr);
            ESP_LOGW(TAG, "post-timeout cleanup for %016" PRIX64 ": StopPairing=%s",
                     nid, e.AsString());
        },
        static_cast<intptr_t>(node_id));
    return ESP_ERR_TIMEOUT;
}

bool ok = ctx->ok;
if (!ok) snprintf(error_buf, error_buf_len, "%s", ctx->error);

