static void clear_readings(pv_value_t *r)
{
    for (int i = 0; i < PV_COUNT; i++) { r[i].value = 0.0; r[i].valid = false; }
}
static void set_reading(pv_value_t *r, pv_index_t idx, double v)
{
    r[idx].value = v; r[idx].valid = true;
}

/* ── Discovery ────────────────────────────────────────────────────────────── */

esp_err_t flux_sunspec_discover(flux_modbus_handle_t h, flux_sunspec_ctx_t *ctx)
{
    uint16_t regs[2];

    for (size_t b = 0; b < sizeof(SUNS_BASES) / sizeof(SUNS_BASES[0]); b++) {
        uint16_t base = SUNS_BASES[b];
        esp_err_t rerr = flux_modbus_read_holding(h, base, 2, regs);
        if (rerr != ESP_OK) continue;
        if (regs[0] != SUNS_HI || regs[1] != SUNS_LO) continue;

        ESP_LOGI(TAG, "SunSpec marker found at base %u", base);

        /* Walk the model chain. First model header is at base + 2. */
        uint16_t p = base + 2;
        for (int guard = 0; guard < 64; guard++) {
            uint16_t hdr[2];
            if (flux_modbus_read_holding(h, p, 2, hdr) != ESP_OK) break;
            uint16_t model_id  = hdr[0];
            uint16_t model_len = hdr[1];

            if (model_id == MODEL_END) {
                ESP_LOGW(TAG, "reached end-of-map without an inverter model");
                break;
            }

            /* Capture the serial from the Common model (best effort). */
            if (model_id == MODEL_COMMON && model_len >= OFF_COMMON_SN + COMMON_SN_REGS
                && ctx->serial[0] == '\0') {
                uint16_t sn[COMMON_SN_REGS];
                if (flux_modbus_read_holding(h, p + 2 + OFF_COMMON_SN,
                                             COMMON_SN_REGS, sn) == ESP_OK) {
                    regs_to_str(sn, COMMON_SN_REGS, ctx->serial, sizeof(ctx->serial));
                    ESP_LOGI(TAG, "SunSpec serial: %s", ctx->serial);
                }
            }

            bool is_int   = is_inverter_model_int(model_id);
            bool is_float = is_inverter_model_float(model_id);
            if (is_int || is_float) {
                ctx->found      = true;
                ctx->is_float   = is_float;
                ctx->model_id   = model_id;
                ctx->data_start = p + 2;
                ctx->data_len   = model_len;
                ESP_LOGI(TAG, "inverter model %u (%s) at reg %u (len %u)",
                         model_id, is_float ? "float" : "int+SF",
                         ctx->data_start, model_len);
                return ESP_OK;
            }
            p += 2 + model_len;  /* advance to next model header */
        }
    }

    ESP_LOGW(TAG, "no SunSpec inverter model located");
    return ESP_ERR_NOT_FOUND;
}

/* ── Decoders ─────────────────────────────────────────────────────────────── */

static void decode_int_model(const uint16_t *buf, pv_value_t *r)
{
    const int16_t w_sf   = (int16_t)buf[OFF_W_SF];
    const int16_t hz_sf  = (int16_t)buf[OFF_HZ_SF];
    const int16_t v_sf   = (int16_t)buf[OFF_V_SF];
    const int16_t a_sf   = (int16_t)buf[OFF_A_SF];
    const int16_t wh_sf  = (int16_t)buf[OFF_WH_SF];
    const int16_t dcw_sf = (int16_t)buf[OFF_DCW_SF];
    const int16_t t_sf   = (int16_t)buf[OFF_TMP_SF];

