static void push_scaled(const pv_value_t *r, pv_index_t idx, const char *key,
                        flux_modbus_reading_t *out, size_t cap, size_t *n)
{
    if (!r[idx].valid || *n >= cap) return;
    flux_modbus_reading_t *e = &out[(*n)++];
    e->key   = key;
    e->which = 3;  /* int64 → long_val, matching kAttrMap for EPM/EEM */
    e->bv    = false;
    e->iv    = 0;
    e->lv    = (int64_t)llround(r[idx].value * 1000.0);
}

static esp_err_t sunspec_poll_map(flux_modbus_profile_ctx_t *ctx,
                                  flux_modbus_handle_t h,
                                  flux_modbus_reading_t *out, size_t *n_out)
{
    pv_value_t r[PV_COUNT];
    esp_err_t err = flux_sunspec_poll(h, &ctx->sunspec, r);
    if (err != ESP_OK) return err;

    size_t cap = *n_out, n = 0;
    /* Keys must match kAttrMap in flux_controller.cpp exactly. Frequency, DC
     * power, temperature and operating-state have no app attr key yet and are
     * intentionally dropped (see modbus_devices_plan.md). */
    push_scaled(r, PV_AC_POWER,   "activePower",                 out, cap, &n);
    push_scaled(r, PV_AC_VOLTAGE, "voltage",                     out, cap, &n);
    push_scaled(r, PV_AC_CURRENT, "activeCurrent",               out, cap, &n);
    push_scaled(r, PV_AC_ENERGY,  "cumulativeEnergyExportedMwh", out, cap, &n);
    *n_out = n;
    return ESP_OK;
}

