/* flux_sunspec.c — SunSpec Modbus decoder. See flux_sunspec.h.
 *
 * Ported from flux-pv/sunspec.c and generalised: all discovery state moved from
 * file-scope globals into a per-device flux_sunspec_ctx_t (the controller polls
 * multiple inverters), register access goes through a flux_modbus handle, and
 * the decode fills a caller-owned readings array instead of pushing to Matter.
 */

#include <math.h>
#include <string.h>

#include "esp_log.h"
#include "esp_timer.h"
#include "flux_sunspec.h"

static const char *TAG = "flux_sunspec";

/* "SunS" marker (0x53756E53) split across two 16-bit registers. */
#define SUNS_HI  0x5375  /* 'S','u' */
#define SUNS_LO  0x6E53  /* 'n','S' */

/* Well-known base register addresses to probe for the marker (0-based Modbus). */
static const uint16_t SUNS_BASES[] = { 40000, 50000, 0 };

#define MODEL_END       0xFFFF
#define MODEL_COMMON    1        /* SunSpec Common model (holds the serial) */

static inline bool is_inverter_model_int(uint16_t id)
{
    return id == 101 || id == 102 || id == 103;  /* 1ph / split / 3ph */
}
static inline bool is_inverter_model_float(uint16_t id)
{
    return id == 111 || id == 112 || id == 113;
}

/* Field offsets within the "int+SF" inverter model data block (0-based, from the
 * first register after the [ID][L] header). Layout identical across 101/2/3. */
enum {
    OFF_A      = 0,    OFF_A_SF   = 4,
    OFF_PHV_A  = 8,    OFF_V_SF   = 11,
    OFF_W      = 12,   OFF_W_SF   = 13,
    OFF_HZ     = 14,   OFF_HZ_SF  = 15,
    OFF_WH_HI  = 22,   OFF_WH_LO  = 23,   OFF_WH_SF = 24,
    OFF_DCW    = 29,   OFF_DCW_SF = 30,
    OFF_TMP    = 31,   OFF_TMP_SF = 35,
    OFF_ST     = 36,
    INV_INT_MIN_LEN = 38,
};

/* Field offsets within the "float" inverter model data block (0-based). Each
 * numeric is a float32 (2 registers); same field order, no scale factors. */
enum {
    OFF_F_A     = 0,   OFF_F_PHV_A = 14,
    OFF_F_W     = 20,  OFF_F_HZ    = 22,
    OFF_F_WH    = 30,  OFF_F_DCW   = 36,
    OFF_F_TMP   = 38,  OFF_F_ST    = 46,
    INV_FLOAT_MIN_LEN = 47,
};

/* Common-model field offsets (0-based, after [ID][L]): serial number is 16
 * registers at offset 48. */
#define OFF_COMMON_SN     48
#define COMMON_SN_REGS    16

/* SunSpec "not implemented" sentinels. */
#define NA_U16   0xFFFF
#define NA_I16   ((int16_t)0x8000)
#define NA_ACC32 0xFFFFFFFFu
#define NA_SF    ((int16_t)0x8000)
/* float32 "not implemented" is NaN — detected with isnan(). */

#define MODEL_BUF_REGS  70   /* int model 50 / float model 60 regs; headroom */

/* ── Helpers ──────────────────────────────────────────────────────────────── */

static double apply_sf(double raw, int16_t sf)
{
    if (sf == NA_SF) return raw;
    return raw * pow(10.0, (double)sf);
}

static float reg_to_f32(const uint16_t *p)   /* MSW-first big-endian float32 */
{
    uint32_t bits = ((uint32_t)p[0] << 16) | p[1];
    float f;
    memcpy(&f, &bits, sizeof(f));
    return f;
}

/* Decode a register run (2 ASCII chars per reg, big-endian) into a C string,
 * trimming trailing spaces/NULs. */
static void regs_to_str(const uint16_t *regs, int nregs, char *out, size_t out_sz)
{
    size_t j = 0;
    for (int i = 0; i < nregs && j + 2 < out_sz; i++) {
        char hi = (char)(regs[i] >> 8);
        char lo = (char)(regs[i] & 0xFF);
        if (hi) out[j++] = hi;
        if (lo) out[j++] = lo;
    }
    out[j] = '\0';
    while (j > 0 && (out[j - 1] == ' ' || out[j - 1] == '\0')) out[--j] = '\0';
}

static void clear_readings(pv_value_t *r)
{
    for (int i = 0; i < PV_COUNT; i++) { r[i].value = 0.0; r[i].valid = false; }
}
static void set_reading(pv_value_t *r, pv_index_t idx, double v)
{
    r[idx].value = v; r[idx].valid = true;
}

/* ── Discovery ────────────────────────────────────────────────────────────── */

esp_err_t flux_sunspec_discover(flux_modbus_handle_t h, flux_sunspec_ctx_t *ctx)
{
    uint16_t regs[2];

    for (size_t b = 0; b < sizeof(SUNS_BASES) / sizeof(SUNS_BASES[0]); b++) {
        uint16_t base = SUNS_BASES[b];
        esp_err_t rerr = flux_modbus_read_holding(h, base, 2, regs);
        if (rerr != ESP_OK) continue;
        if (regs[0] != SUNS_HI || regs[1] != SUNS_LO) continue;

        ESP_LOGI(TAG, "SunSpec marker found at base %u", base);

        /* Walk the model chain. First model header is at base + 2. */
        uint16_t p = base + 2;
        for (int guard = 0; guard < 64; guard++) {
            uint16_t hdr[2];
            if (flux_modbus_read_holding(h, p, 2, hdr) != ESP_OK) break;
            uint16_t model_id  = hdr[0];
            uint16_t model_len = hdr[1];

            if (model_id == MODEL_END) {
                ESP_LOGW(TAG, "reached end-of-map without an inverter model");
                break;
            }

            /* Capture the serial from the Common model (best effort). */
            if (model_id == MODEL_COMMON && model_len >= OFF_COMMON_SN + COMMON_SN_REGS
                && ctx->serial[0] == '\0') {
                uint16_t sn[COMMON_SN_REGS];
                if (flux_modbus_read_holding(h, p + 2 + OFF_COMMON_SN,
                                             COMMON_SN_REGS, sn) == ESP_OK) {
                    regs_to_str(sn, COMMON_SN_REGS, ctx->serial, sizeof(ctx->serial));
                    ESP_LOGI(TAG, "SunSpec serial: %s", ctx->serial);
                }
            }

            bool is_int   = is_inverter_model_int(model_id);
            bool is_float = is_inverter_model_float(model_id);
            if (is_int || is_float) {
                ctx->found      = true;
                ctx->is_float   = is_float;
                ctx->model_id   = model_id;
                ctx->data_start = p + 2;
                ctx->data_len   = model_len;
                ESP_LOGI(TAG, "inverter model %u (%s) at reg %u (len %u)",
                         model_id, is_float ? "float" : "int+SF",
                         ctx->data_start, model_len);
                return ESP_OK;
            }
            p += 2 + model_len;  /* advance to next model header */
        }
    }

    ESP_LOGW(TAG, "no SunSpec inverter model located");
    return ESP_ERR_NOT_FOUND;
}

/* ── Decoders ─────────────────────────────────────────────────────────────── */

static void decode_int_model(const uint16_t *buf, pv_value_t *r)
{
    const int16_t w_sf   = (int16_t)buf[OFF_W_SF];
    const int16_t hz_sf  = (int16_t)buf[OFF_HZ_SF];
    const int16_t v_sf   = (int16_t)buf[OFF_V_SF];
    const int16_t a_sf   = (int16_t)buf[OFF_A_SF];
    const int16_t wh_sf  = (int16_t)buf[OFF_WH_SF];
    const int16_t dcw_sf = (int16_t)buf[OFF_DCW_SF];
    const int16_t t_sf   = (int16_t)buf[OFF_TMP_SF];

    if ((int16_t)buf[OFF_W] != NA_I16)
        set_reading(r, PV_AC_POWER, apply_sf((double)(int16_t)buf[OFF_W], w_sf));

    uint32_t wh = ((uint32_t)buf[OFF_WH_HI] << 16) | buf[OFF_WH_LO];
    if (wh != NA_ACC32)
        set_reading(r, PV_AC_ENERGY, apply_sf((double)wh, wh_sf));

    if (buf[OFF_HZ] != NA_U16)
        set_reading(r, PV_AC_FREQUENCY, apply_sf((double)buf[OFF_HZ], hz_sf));

    if (buf[OFF_PHV_A] != NA_U16)
        set_reading(r, PV_AC_VOLTAGE, apply_sf((double)buf[OFF_PHV_A], v_sf));

    if (buf[OFF_A] != NA_U16)
        set_reading(r, PV_AC_CURRENT, apply_sf((double)buf[OFF_A], a_sf));

    if ((int16_t)buf[OFF_DCW] != NA_I16)
        set_reading(r, PV_DC_POWER, apply_sf((double)(int16_t)buf[OFF_DCW], dcw_sf));

    if ((int16_t)buf[OFF_TMP] != NA_I16)
        set_reading(r, PV_TEMP, apply_sf((double)(int16_t)buf[OFF_TMP], t_sf));

    if (buf[OFF_ST] != NA_U16)
        set_reading(r, PV_STATE, (double)buf[OFF_ST]);
}

static void decode_float_model(const uint16_t *buf, pv_value_t *r)
{
    float w  = reg_to_f32(&buf[OFF_F_W]);
    float wh = reg_to_f32(&buf[OFF_F_WH]);
    float hz = reg_to_f32(&buf[OFF_F_HZ]);
    float v  = reg_to_f32(&buf[OFF_F_PHV_A]);
    float a  = reg_to_f32(&buf[OFF_F_A]);
    float dc = reg_to_f32(&buf[OFF_F_DCW]);
    float t  = reg_to_f32(&buf[OFF_F_TMP]);

    if (!isnan(w))  set_reading(r, PV_AC_POWER,     (double)w);
    if (!isnan(wh)) set_reading(r, PV_AC_ENERGY,    (double)wh);
    if (!isnan(hz)) set_reading(r, PV_AC_FREQUENCY, (double)hz);
    if (!isnan(v))  set_reading(r, PV_AC_VOLTAGE,   (double)v);
    if (!isnan(a))  set_reading(r, PV_AC_CURRENT,   (double)a);
    if (!isnan(dc)) set_reading(r, PV_DC_POWER,     (double)dc);
    if (!isnan(t))  set_reading(r, PV_TEMP,         (double)t);

    if (buf[OFF_F_ST] != NA_U16)   /* St is enum16 (single register) */
        set_reading(r, PV_STATE, (double)buf[OFF_F_ST]);
}

/* ── Poll ─────────────────────────────────────────────────────────────────── */

esp_err_t flux_sunspec_poll(flux_modbus_handle_t h, flux_sunspec_ctx_t *ctx,
                            pv_value_t *r)
{
    if (!ctx->found) {
        esp_err_t d = flux_sunspec_discover(h, ctx);
        if (d != ESP_OK) return d;
    }

    uint16_t min_len = ctx->is_float ? INV_FLOAT_MIN_LEN : INV_INT_MIN_LEN;
    uint16_t n = ctx->data_len < MODEL_BUF_REGS ? ctx->data_len : MODEL_BUF_REGS;
    if (n < min_len) n = min_len;

    uint16_t buf[MODEL_BUF_REGS];
    esp_err_t err = flux_modbus_read_holding(h, ctx->data_start, n, buf);
    if (err != ESP_OK) {
        ESP_LOGW(TAG, "inverter model read failed: %s", esp_err_to_name(err));
        return err;
    }

    clear_readings(r);
    if (ctx->is_float) decode_float_model(buf, r);
    else               decode_int_model(buf, r);

    ESP_LOGI(TAG, "PV[%u]: %.0f W  %.3f kWh  %.2f Hz  %.1f V  %.2f A  (St=%d)",
             ctx->model_id, r[PV_AC_POWER].value, r[PV_AC_ENERGY].value / 1000.0,
             r[PV_AC_FREQUENCY].value, r[PV_AC_VOLTAGE].value,
             r[PV_AC_CURRENT].value, (int)r[PV_STATE].value);
    return ESP_OK;
}

/* flux_modbus_task.c — Modbus poll task. See flux_modbus_task.h. */

#include <string.h>
#include <stdio.h>

#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_timer.h"

#include "flux_modbus_task.h"
#include "flux_modbus.h"
#include "flux_modbus_profile.h"
#include "flux_state.h"
#include "flux_hangwatch.h"   /* task-liveness heartbeat (FW-ADR-0013) */
#include "flux_events.h"  /* flux_events_emit_attr / flux_events_emit_device */
#include "flux.pb.h"      /* flux_DeviceEventType_* */

static const char *TAG = "flux_mb_task";

#define DEFAULT_POLL_S        5
#define TASK_TICK_MS          500
#define MAX_BACKOFF_US        (120LL * 1000000) /* cap dead-device retry at 120 s —
                                                 * fewer failed reads = less leak */
#define FAIL_BEFORE_RETRYING  3   /* consecutive fails before flagging RETRYING  */
#define FAIL_BEFORE_RECONNECT 5   /* consecutive fails before tearing the socket */
#define POLL_RETRIES          2   /* immediate in-poll retries before backing off */
#define POLL_RETRY_DELAY_MS   120 /* let a flaky dongle settle between retries     */

/* One entry per active (opened) device. */
typedef struct {
    uint64_t                   node_id;
    flux_modbus_handle_t       mb;
    flux_modbus_profile_ctx_t *profile;
    char                       host[FLUX_MODBUS_HOST_MAX];  /* for reconnect */
    uint16_t                   port;
    uint8_t                    unit_id;
    bool                       udp;
    int64_t                    poll_us;       /* configured interval */
    int64_t                    next_poll_us;  /* esp_timer clock */
    int                        fail_count;
    bool                       established;    /* connectivity latch */
} mb_active_t;

static mb_active_t   s_active[FLUX_MODBUS_MAX];
static size_t        s_n_active = 0;
static volatile bool s_reload   = true;   /* true → (re)load on next tick */
static TaskHandle_t  s_task     = NULL;

/* ── Active-set (re)build from the persisted registry ─────────────────────── */

static void teardown_active(void)
{
    for (size_t i = 0; i < s_n_active; i++) {
        if (s_active[i].mb)      flux_modbus_close(s_active[i].mb);
        if (s_active[i].profile) flux_modbus_profile_destroy(s_active[i].profile);
    }
    s_n_active = 0;
}

/* Full rebuild: cheap (a handful of devices) and only runs on add/remove, so we
 * favour simplicity/correctness over preserving unaffected devices' sessions. */
static void rebuild_active(void)
{
    teardown_active();

    size_t n = flux_modbus_count();
    for (size_t i = 0; i < n && s_n_active < FLUX_MODBUS_MAX; i++) {
        flux_ModbusRecord rec;
        if (flux_modbus_get(i, &rec) != ESP_OK) continue;

        mb_active_t *a = &s_active[s_n_active];
        memset(a, 0, sizeof(*a));
        a->node_id      = rec.node_id;
        snprintf(a->host, sizeof(a->host), "%s", rec.host);
        a->port         = rec.port;
        a->unit_id      = rec.unit_id;
        a->udp          = (rec.transport == 1);  /* flux_ModbusTransport UDP */
        a->poll_us      = (int64_t)(rec.poll_seconds ? rec.poll_seconds
                                                      : DEFAULT_POLL_S) * 1000000;
        a->next_poll_us = 0;   /* poll asap */

        a->profile = flux_modbus_profile_create((flux_modbus_profile_id_t)rec.profile);
        if (!a->profile) {
            ESP_LOGE(TAG, "profile %u create failed for %016llx",
                     rec.profile, (unsigned long long)rec.node_id);
            continue;
        }
        /* open() tolerates an offline device (connects in the background), so a
         * hard failure here is unusual (OOM / bad config) — skip this entry. */
        if (flux_modbus_open(rec.host, rec.port, rec.unit_id, a->udp, 0, &a->mb) != ESP_OK) {
            flux_modbus_profile_destroy(a->profile);
            continue;
        }
        s_n_active++;
        ESP_LOGI(TAG, "polling %016llx (%s:%u) every %llds",
                 (unsigned long long)rec.node_id, rec.host, rec.port,
                 (long long)(a->poll_us / 1000000));
    }
}

/* ── Per-device poll ──────────────────────────────────────────────────────── */

static void poll_device(mb_active_t *a)
{
    flux_modbus_reading_t rd[FLUX_MODBUS_MAX_READINGS];
    size_t cnt = FLUX_MODBUS_MAX_READINGS;
    esp_err_t err = flux_modbus_profile_poll(a->profile, a->mb, rd, &cnt);

    /* Absorb a transient glitch (a slow/garbled frame, a briefly dropped TCP
     * socket) with a couple of immediate retries before declaring the poll
     * failed. Without this, a single hiccup freezes the last-good reading for a
     * whole backoff window — which is how a PV inverter can appear stuck at one
     * value all day. The failed read already dropped the socket, so the retry
     * reconnects; a persistent outage still falls through to the backoff below. */
    /* A device that has already failed several times running is almost certainly
     * offline; skip the immediate in-poll retries for it. Each retry re-runs the
     * whole profile poll (several Modbus reads, e.g. SunSpec model-chain walk),
     * which only adds failed-read churn — and every failed read leaks an
     * esp-modbus transaction buffer (the internal-RAM leak behind the hangs). */
    int retries = (a->fail_count >= FAIL_BEFORE_RECONNECT) ? 0 : POLL_RETRIES;
    for (int t = 0; err != ESP_OK && t < retries; t++) {
        vTaskDelay(pdMS_TO_TICKS(POLL_RETRY_DELAY_MS));
        cnt = FLUX_MODBUS_MAX_READINGS;
        err = flux_modbus_profile_poll(a->profile, a->mb, rd, &cnt);
    }

    int64_t now = esp_timer_get_time();

    if (err == ESP_OK) {
        for (size_t i = 0; i < cnt; i++)
            flux_events_emit_attr(a->node_id, rd[i].key, rd[i].which,
                                  rd[i].bv, rd[i].iv, rd[i].lv);
        if (!a->established) {
            a->established = true;
            flux_events_emit_device(
                a->node_id, flux_DeviceEventType_DEVICE_EVENT_ESTABLISHED, NULL);
        }
        a->fail_count   = 0;
        a->next_poll_us = now + a->poll_us;
        return;
    }

    if (a->fail_count < 1000) a->fail_count++;

    /* Connectivity hysteresis: only report RETRYING after several *consecutive*
     * failures, so a single slow or garbled read from a flaky inverter dongle
     * doesn't flap the device between SUBSCRIBED and RETRYING in the app. */
    if (a->established && a->fail_count >= FAIL_BEFORE_RETRYING) {
        a->established = false;
        flux_events_emit_device(
            a->node_id, flux_DeviceEventType_DEVICE_EVENT_RESUBSCRIBING,
            esp_err_to_name(err));
    }

    int shift = a->fail_count > 5 ? 5 : a->fail_count;
    int64_t backoff = a->poll_us << shift;
    if (backoff > MAX_BACKOFF_US) backoff = MAX_BACKOFF_US;
    a->next_poll_us = now + backoff;

    /* Reconnect only after repeated failures — a genuinely wedged handle. The
     * raw TCP client already drops and lazily re-opens its socket on each failed
     * read, so a full close/open here is belt-and-suspenders (also resets the UDP
     * socket); doing it every failure would needlessly churn the lwip pool. */
    if (a->fail_count % FAIL_BEFORE_RECONNECT == 0) {
        if (a->mb) flux_modbus_close(a->mb);
        a->mb = NULL;
        if (flux_modbus_open(a->host, a->port, a->unit_id, a->udp, 0, &a->mb) != ESP_OK)
            ESP_LOGW(TAG, "reconnect to %s:%u failed — will retry", a->host, a->port);
    }
}

/* ── Task loop ────────────────────────────────────────────────────────────── */

static void modbus_task(void *arg)
{
    (void)arg;
    /* 30 s budget: the loop ticks every TASK_TICK_MS regardless of per-device
     * backoff, so a healthy task kicks frequently; only a wedged poll (stuck
     * socket) goes silent, and that is exactly what we want to catch. */
    int hb = flux_hangwatch_register("flux_modbus", 30LL * 1000000);
    for (;;) {
        if (s_reload) {
            s_reload = false;
            rebuild_active();
        }
        int64_t now = esp_timer_get_time();
        for (size_t i = 0; i < s_n_active; i++) {
            if (now >= s_active[i].next_poll_us)
                poll_device(&s_active[i]);
        }
        flux_hangwatch_kick(hb);
        vTaskDelay(pdMS_TO_TICKS(TASK_TICK_MS));
    }
}

void flux_modbus_task_start(void)
{
    if (s_task) return;
    if (xTaskCreate(modbus_task, "flux_modbus", 6144, NULL, 4, &s_task) != pdPASS) {
        s_task = NULL;
        ESP_LOGE(TAG, "failed to create modbus poll task — polling disabled");
    }
}

void flux_modbus_task_reload(void)
{
    s_reload = true;
}

