static void on_state(flux_ice_state_t st, void *user)
{
    session_t *s = (session_t *)user;
    s->state = st;
    /* Consent loss / failure -> mark for reclaim (ADR-0010). Actual free is
     * deferred out of the callback thread (see reap_dead). */
    if (st == FLUX_ICE_STATE_FAILED || st == FLUX_ICE_STATE_CLOSED)
        s->active = false;
}
