/* A session is only ever released when libjuice reports FAILED/CLOSED. A tunnel
 * that simply stops being used — app killed, phone back on the LAN, Wi-Fi
 * dropped without a consent-freshness failure ever being delivered — stays
 * active forever and its slot is never reclaimed. Three of those and every
 * subsequent offer is refused until reboot; observed in the field with 12
 * refusals, 0 reclaims and 73 h of uptime.
 *
 * Two independent defences, because they cover different failure shapes:
 *   - IDLE reaper: no inbound datagram for this long ⇒ the peer is gone. Handles
 *     the quiet case where no new offer ever arrives.
 *   - LRU eviction (see alloc_session): a fresh, MAC-authenticated offer when
 *     the cap is full is strong evidence the oldest session is dead — usually
 *     the very same phone reconnecting. Guarantees a valid offer is never
 *     refused because of a corpse. */
#define SESSION_IDLE_TIMEOUT_US (10LL * 60 * 1000000)  /* 10 min without traffic */
#define REAPER_TICK_MS          30000

typedef struct {
    flux_ice_t         *ice;
    flux_ice_bridge_t  *bridge;
    volatile flux_ice_state_t state;
    volatile bool       gathered;
    bool                active;
    /* esp_timer_get_time() of the last inbound datagram (or session start).
     * Inbound traffic is what proves the remote peer is still there. */
    volatile int64_t    last_rx_us;
} session_t;

