static SemaphoreHandle_t s_lock;
static StaticSemaphore_t s_lock_buf;
static char             s_eth_ip[16];   /* bind address (ADR-0004) */

/* ── config helpers ──────────────────────────────────────────────────────── */

static void resolve_eth_ip(void)
{
    s_eth_ip[0] = 0;
    esp_netif_t *eth = esp_netif_get_handle_from_ifkey(FLUX_BACKBONE_IFKEY);
    esp_netif_ip_info_t ip;
    /* Leave s_eth_ip empty until a real lease exists — before DHCP, get_ip_info
     * succeeds with 0.0.0.0, and stringifying that would defeat the lazy
     * re-resolve guard in flux_ice_task_signal (and bind ICE to 0.0.0.0, which
     * yields no host candidate). */
    if (eth && esp_netif_get_ip_info(eth, &ip) == ESP_OK && ip.ip.addr != 0)
        esp_ip4addr_ntoa(&ip.ip, s_eth_ip, sizeof(s_eth_ip));
}

/* First STUN server from stored RemoteConfig, else Google default (ADR-0007). */
static void resolve_stun(char *host, size_t host_max, uint16_t *port)
{
    snprintf(host, host_max, "stun.relay.metered.ca");   /* metered.ca (ADR-0007) */
    *port = 80;

    uint8_t buf[flux_RemoteConfig_size];
    size_t len = 0;
    if (flux_remote_get_config(buf, &len, sizeof buf) != ESP_OK) return;
    flux_RemoteConfig cfg = flux_RemoteConfig_init_zero;
    pb_istream_t is = pb_istream_from_buffer(buf, len);
    if (pb_decode(&is, flux_RemoteConfig_fields, &cfg) && cfg.stun_count > 0 &&
        cfg.stun[0].host[0]) {
        snprintf(host, host_max, "%s", cfg.stun[0].host);
        *port = cfg.stun[0].port ? (uint16_t)cfg.stun[0].port : 3478;
    }
}

/* ── libjuice callbacks (per session, user = session_t*) ─────────────────── */

static void on_state(flux_ice_state_t st, void *user)
{
