     * deferred out of the callback thread (see reap_dead). */
    if (st == FLUX_ICE_STATE_FAILED || st == FLUX_ICE_STATE_CLOSED)
        s->active = false;
}
static void on_gathering_done(void *user) { ((session_t *)user)->gathered = true; }
static void on_recv(const uint8_t *d, size_t n, void *user)
{
    session_t *s = (session_t *)user;
    if (s->bridge) flux_ice_bridge_deliver(s->bridge, d, n);
}

/* Free sessions marked inactive but not yet torn down. Caller holds s_lock.
 *
 * The teardown dependency is CIRCULAR — the bridge reader task calls
 * flux_ice_send(s->ice), and the agent's on_recv (libjuice poll thread, takes
 * no s_lock) calls flux_ice_bridge_deliver(s->bridge) — so neither side may be
 * freed while the other can still run. Three phases, in order:
 *   1. detach the bridge  — reader quiesced (definitive wait): nothing touches
 *      s->ice anymore; the bridge struct/socket stay valid for deliver().
 *   2. close the agent    — juice_destroy joins its threads: no more on_recv
 *      can touch s->bridge.
 *   3. free the bridge.
 * The old order (stop+free bridge, then close agent) let a straggler datagram
 * deliver into the freed bridge — a use-after-free. */
static void reap_dead(void)
{
    for (int i = 0; i < MAX_SESSIONS; i++) {
        session_t *s = &s_sessions[i];
        if (!s->active && s->ice) {
            flux_ice_bridge_detach(s->bridge);       /* 1: reader quiesced      */
            flux_ice_close(s->ice); s->ice = NULL;   /* 2: callbacks quiesced   */
            if (s->bridge) { flux_ice_bridge_stop(s->bridge); s->bridge = NULL; } /* 3 */
            ESP_LOGI(TAG, "session %d reclaimed", i);
        }
    }
}

static session_t *alloc_session(void)
{
    for (int i = 0; i < MAX_SESSIONS; i++)
        if (!s_sessions[i].active && !s_sessions[i].ice) return &s_sessions[i];
    return NULL;
}

