             s_eth_ip[0] ? s_eth_ip : "(any)", stun_host, stun_port);

    /* libjuice (POLL) spawns its conn-poll thread and a STUN resolver thread
     * with NULL pthread attrs, inheriting CONFIG_PTHREAD_TASK_STACK_SIZE_DEFAULT
     * (3 KiB). They are created synchronously from THIS (coap_server) task during
     * flux_ice_open/gather, so raise the per-thread default here.
     *
     * 32 KiB: libjuice uses char buffer[4096] on-stack pervasively (conn_poll.c,
     * agent.c x8) and the recv->STUN-response chain nests several of them, so
     * the real peak is ~20 KiB — 3 KiB/8 KiB both fault. (The separate 4 KiB
     * log-format buffer is avoided by disabling libjuice logging on ESP.) */
    esp_pthread_cfg_t pcfg = esp_pthread_get_default_config();
    pcfg.stack_size       = 32768;
    pcfg.thread_name      = "flux_ice";
    pcfg.inherit_cfg      = true;
    /* Allocate these big stacks from PSRAM, not scarce internal RAM: with the
     * rendezvous task + esp_http_client + Matter/OpenThread all resident,
     * internal RAM can't satisfy 32 KiB × (conn-poll + resolver) and
     * pthread_create fails ("Failed to create task!") — libjuice then never
     * gathers (no candidate in the answer). The P4 has 32 MiB PSRAM. */
    pcfg.stack_alloc_caps = MALLOC_CAP_SPIRAM | MALLOC_CAP_8BIT;
    esp_pthread_set_cfg(&pcfg);

    flux_ice_cfg_t cfg = {0};
    cfg.role               = FLUX_ICE_CONTROLLED;
    cfg.bind_address       = s_eth_ip[0] ? s_eth_ip : NULL;   /* ADR-0004 */
    cfg.stun_host          = stun_host;
    cfg.stun_port          = stun_port;
    cfg.on_state           = on_state;
    cfg.on_gathering_done  = on_gathering_done;
    cfg.on_recv            = on_recv;
    cfg.user               = s;

    s->gathered = false;
    s->state    = FLUX_ICE_STATE_NEW;
    s->ice = flux_ice_open(&cfg);
    if (!s->ice) { xSemaphoreGive(s_lock); return -1; }

    flux_addr_t lo = { .family = FLUX_AF_INET, .port = LOOPBACK_COAP_PORT };
    lo.addr[0] = 127; lo.addr[1] = 0; lo.addr[2] = 0; lo.addr[3] = 1;
    s->bridge = flux_ice_bridge_start(lo);
    flux_ice_bridge_attach_ice(s->bridge, s->ice);
    s->active = true;

    flux_ice_set_remote_description(s->ice, sdp);
    flux_ice_gather(s->ice);
    xSemaphoreGive(s_lock);

    /* Single-exchange (ADR-0005): wait (bounded) for gathering, then the local
     * description is the answer. NOTE first-cut: this blocks the caller for the
     * gather window — production moves the exchange off the coap_task. */
    for (int i = 0; i < GATHER_TIMEOUT_MS / 50 && !s->gathered; i++)
        vTaskDelay(pdMS_TO_TICKS(50));

    /* Off-stack: sole caller is the coap_server handler (serial dispatch), and
     * this frame already nests libjuice — keep the 2 KiB answer buffer off the
     * task stack. */
    static char local[2048];
    if (flux_ice_local_description(s->ice, local, sizeof local) != 0) {
        xSemaphoreTake(s_lock, portMAX_DELAY); s->active = false; reap_dead();
        xSemaphoreGive(s_lock);
        return -1;
    }
    size_t n = strlen(local);
    if (n >= answer_max) return -1;
    memcpy(answer_sdp, local, n);
    *answer_len = n;
    ESP_LOGI(TAG, "answered remote offer (answer %u bytes)", (unsigned)n);
    return 0;
}

