    print(f"rendezvous base={BASE}  mailbox={MAILBOX[:16]}…")
    for f in (OFFER, ANSWER):
        try: os.remove(f)
        except FileNotFoundError: pass
    proc = subprocess.Popen([CLIENT, OFFER, ANSWER], stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True)
    try:
        offer = None
        end = time.time() + 15
        while time.time() < end:
            line = proc.stdout.readline()
            if not line:
                if proc.poll() is not None: print("client exited"); return
                continue
            print("  [client]", line.rstrip())
