            if ans: break
        if not ans: print("no answer via rendezvous"); return
        sdp = decode_sdp(ans).decode('utf-8', 'replace')
        print(f"controller answer via rendezvous:\n{sdp}")
        open(ANSWER, 'wb').write(decode_sdp(ans))

        port = None
