        while time.time() < end:
            line = proc.stdout.readline()
            if not line:
                if proc.poll() is not None: print("client exited before tunnel"); return
                continue
            print("  [client]", line.rstrip())
            if "TUNNEL_READY" in line:
                port = int(line.split("port=")[1].strip()); break
        if not port: print("tunnel not ready"); return

        print(f"\n=== TUNNEL UP on 127.0.0.1:{port} via RENDEZVOUS — flux-ctl through it ===")

