"""E2E of the rendezvous signaling path (flux-interface ADR-0006).

Signaling goes through the reference rendezvous mailbox instead of a direct
/remote/signal CoAP POST — exercising the controller's rendezvous client:

  remote_client (host ICE agent) --offer--> rzv /{mailbox}/offer
     controller polls offer, answers --> rzv /{mailbox}/answer --> us
  set_answer -> ICE connects -> CoAP GET /info through the loopback tunnel

usage: uv run python rzv_e2e.py <rendezvous_base_url>
"""
import asyncio, base64, hashlib, hmac, os, subprocess, sys, time, urllib.request
from flux_ctl._config import load

cfg = load(None, None, None, None)
psk = bytes.fromhex(cfg.psk_hex)
BASE = sys.argv[1].rstrip('/') if len(sys.argv) > 1 else 'http://127.0.0.1:8099'
SP = "/tmp/claude-1001/-home-tado-workspace-flux-flux-controller/1500536b-d115-4633-9ad4-bf1aa7701bde/scratchpad"
CLIENT = "/home/tado/workspace/flux/flux-controller/proto/flux-ice/build/tests/remote_client"
OFFER, ANSWER = f"{SP}/rzv_offer.sdp", f"{SP}/rzv_answer.sdp"

MAILBOX = base64.b32encode(
    hmac.new(psk, b"flux-rendezvous-mailbox", hashlib.sha256).digest()
).decode().lower().rstrip('=')


def hkdf_expand(prk, info, L=32):
    t = b''; okm = b''; c = 1
    while len(okm) < L:
        t = hmac.new(prk, t + info + bytes([c]), hashlib.sha256).digest(); okm += t; c += 1
    return okm[:L]

def sig_mac(kind, sdp):
    return hmac.new(hkdf_expand(psk, b"flux-remote-signal"), bytes([kind]) + sdp, hashlib.sha256).digest()

def vlq(n):
    o = b''
    while True:
        b = n & 0x7f; n >>= 7; o += bytes([b | (0x80 if n else 0)])
        if not n: return o

def field(t, w, d):
    return bytes([(t << 3) | w]) + (vlq(len(d)) + d if w == 2 else vlq(d))

def decode_sdp(ans):
    i = 0; sdp = b""
    while i < len(ans):
        k = ans[i]; t = k >> 3; w = k & 7; i += 1
        if w == 0:
            while ans[i] & 0x80: i += 1
            i += 1
        elif w == 2:
            ln = 0; s = 0
            while True:
                b = ans[i]; i += 1; ln |= (b & 0x7f) << s; s += 7
                if not b & 0x80: break
            v = ans[i:i+ln]; i += ln
            if t == 2: sdp = v
    return sdp

def http_post(url, body):
    urllib.request.urlopen(urllib.request.Request(url, data=body, method='POST'), timeout=15).read()

def http_get(url):
    try:
        r = urllib.request.urlopen(url, timeout=30)
        return r.read() if r.status == 200 else b""
    except Exception:
        return b""


def main():
    print(f"rendezvous base={BASE}  mailbox={MAILBOX[:16]}…")
    for f in (OFFER, ANSWER):
        try: os.remove(f)
        except FileNotFoundError: pass
    proc = subprocess.Popen([CLIENT, OFFER, ANSWER], stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True)
    try:
        offer = None
        end = time.time() + 15
        while time.time() < end:
            line = proc.stdout.readline()
            if not line:
                if proc.poll() is not None: print("client exited"); return
                continue
            print("  [client]", line.rstrip())
            if "OFFER_READY" in line:
                offer = open(OFFER, 'rb').read(); break
        if not offer: print("no offer"); return

        # POST offer to the rendezvous mailbox; controller polls + answers there.
        msg = field(2, 2, offer) + field(3, 2, sig_mac(0, offer)) + field(4, 0, 1)
        http_post(f"{BASE}/{MAILBOX}/offer", msg)
        print(f"offer posted to rendezvous ({len(msg)} B); polling for answer…")

        ans = b""
        for _ in range(6):
            ans = http_get(f"{BASE}/{MAILBOX}/answer")
            if ans: break
        if not ans: print("no answer via rendezvous"); return
        sdp = decode_sdp(ans).decode('utf-8', 'replace')
        print(f"controller answer via rendezvous:\n{sdp}")
        open(ANSWER, 'wb').write(decode_sdp(ans))

        port = None
        end = time.time() + 25
        while time.time() < end:
            line = proc.stdout.readline()
            if not line:
                if proc.poll() is not None: print("client exited before tunnel"); return
                continue
            print("  [client]", line.rstrip())
            if "TUNNEL_READY" in line:
                port = int(line.split("port=")[1].strip()); break
        if not port: print("tunnel not ready"); return

        print(f"\n=== TUNNEL UP on 127.0.0.1:{port} via RENDEZVOUS — flux-ctl through it ===")

        async def tget(path):
            from flux_ctl._coap import CoapClient
            async with CoapClient("127.0.0.1", port, cfg.psk_hex, cfg.identity) as c:
                return await c.get(path, timeout=15)
        for p in ("info", "devices"):
            try:
                r = asyncio.run(tget(p))
                print(f"  TUNNELED GET {p} -> {len(r)} B OK")
            except Exception as e:
                print(f"  TUNNELED GET {p} -> FAILED: {e!r}")
    finally:
        proc.terminate()
        try: proc.wait(timeout=3)
        except Exception: proc.kill()


main()

