static void reaper_task(void *arg)
{
    (void)arg;
    for (;;) {
        vTaskDelay(pdMS_TO_TICKS(REAPER_TICK_MS));
        xSemaphoreTake(s_lock, portMAX_DELAY);
        const int retired = retire_idle_locked();
        reap_dead();          /* also collects sessions libjuice already failed */
        xSemaphoreGive(s_lock);
        /* Report headroom after a real reap — the expensive path. An undersized
         * stack here shows up as a panic, not a log line, so make the margin
         * observable instead of waiting for the next crash to reveal it. */
        if (retired) {
            ESP_LOGI(TAG, "reaper: %d retired, stack headroom %u B",
                     retired, (unsigned)uxTaskGetStackHighWaterMark(NULL));
        }
    }
}

