    b->peer       = loopback_peer;
    b->peer_known = (loopback_peer.port != 0);
    b->learn      = (loopback_peer.port == 0);

    b->sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (b->sock < 0) { free(b); return NULL; }

