    uint8_t buf[2048];
    struct timeval tv = { .tv_sec = 0, .tv_usec = 200000 }; /* 200ms so we can exit */
    setsockopt(b->sock, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof tv);

    while (b->running) {
        struct sockaddr_in src; socklen_t sl = sizeof(src);
        int n = recvfrom(b->sock, buf, sizeof buf, 0, (struct sockaddr *)&src, &sl);
        if (n <= 0) continue;                       /* timeout / transient */
        /* Learn mode: follow the latest loopback sender (reconnect robustness). */
        if (b->learn) {
            portENTER_CRITICAL(&b->lock);
            sockaddr_to_addr(&src, &b->peer);
            b->peer_known = 1;
            portEXIT_CRITICAL(&b->lock);
        }
        if (b->ice) flux_ice_send(b->ice, buf, (size_t)n);

        /* Report the worst-case stack headroom seen on the send path. Two
         * overflows here (4 KiB pre-TURN, 12 KiB with TURN) were both found only
         * by the panic they caused; a number in the log turns the next one into
         * a warning instead of a reboot. */
        UBaseType_t head = uxTaskGetStackHighWaterMark(NULL);
        if (head < b->min_headroom) {
