    if (!b) return NULL;
    b->lock       = (portMUX_TYPE)portMUX_INITIALIZER_UNLOCKED;
    b->peer       = loopback_peer;
    b->peer_known = (loopback_peer.port != 0);
    b->learn      = (loopback_peer.port == 0);

    b->sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (b->sock < 0) { free(b); return NULL; }

    struct sockaddr_in la;
    memset(&la, 0, sizeof(la));
    la.sin_family      = AF_INET;
    la.sin_addr.s_addr = lwip_htonl(INADDR_LOOPBACK);
    la.sin_port        = 0;                          /* ephemeral */
