     * pthread_join. The old bounded wait (500 ms) could expire while the reader
     * was still inside recvfrom/flux_ice_send; the caller then freed `b` and
     * the reader used freed memory. The reader exits within one 200 ms recv
     * timeout plus one flux_ice_send, so a longer wait only happens if the
     * network stack is wedged — in which case blocking here (and letting the
     * hang watchdog see it) beats heap corruption. */
    for (int i = 0; !b->stopped; i++) {
        vTaskDelay(pdMS_TO_TICKS(20));
        if (i == 100)   /* 2 s: abnormal — say so, keep waiting */
            printf("flux_ice_bridge: reader slow to stop (still waiting)\n");
    }
    b->task = NULL;
}

void flux_ice_bridge_stop(flux_ice_bridge_t *b)
{
    if (!b) return;
    flux_ice_bridge_detach(b);
    if (b->sock >= 0) close(b->sock);
    free(b);
}

