/* Worst stack headroom seen on the libjuice worker thread ("flux_ice"), which is
 * where on_recv runs. Three separate stacks overflowed while bringing TURN up
 * (this one, the bridge reader, and the session reaper) and every one was found
 * only by the panic it caused — so measure it. Single-threaded in POLL mode
 * (sessions share one worker), so a plain static needs no locking. */
static UBaseType_t s_ice_min_headroom = (UBaseType_t)-1;

static void on_recv(const uint8_t *d, size_t n, void *user)
{
    session_t *s = (session_t *)user;
    s->last_rx_us = esp_timer_get_time();   /* liveness for the idle reaper */
    if (s->bridge) flux_ice_bridge_deliver(s->bridge, d, n);

    UBaseType_t head = uxTaskGetStackHighWaterMark(NULL);
    if (head < s_ice_min_headroom) {
        s_ice_min_headroom = head;
        if (head < 8192)
            ESP_LOGW(TAG, "libjuice thread stack headroom down to %u B — raise "
                          "pcfg.stack_size", (unsigned)head);
    }
}

