/* ── Device registry ────────────────────────────────────────────────────── */

#define FLUX_DEVICE_NAME_MAX  64
#define FLUX_DEVICES_MAX      32

typedef struct {
    uint64_t node_id;
    uint32_t vendor_id;
    uint32_t product_id;
    uint32_t device_type;   /* primary Matter device type from Descriptor */
    char     name[FLUX_DEVICE_NAME_MAX];
} flux_DeviceRecord;

/** Return total number of persisted devices (0..FLUX_DEVICES_MAX). */
size_t    flux_device_count(void);

/** Get device at index i (0-based).  Returns ESP_ERR_NOT_FOUND if i >= count. */
esp_err_t flux_device_get(size_t i, flux_DeviceRecord *out);

/** Get device by node_id.  Returns ESP_ERR_NOT_FOUND if not present. */
esp_err_t flux_device_get_by_node(uint64_t node_id, flux_DeviceRecord *out);

/** Add or overwrite a device record.  Persists to NVS immediately. */
esp_err_t flux_device_upsert(const flux_DeviceRecord *rec);

/** Update only the name field for an existing node.  Returns ESP_ERR_NOT_FOUND
 *  if node_id is not in the registry. */
esp_err_t flux_device_set_name(uint64_t node_id, const char *name);

/** Update vendor_id / product_id / device_type for an existing node.
 *  Silently ignores if node_id is not present (race-safe async metadata fill). */
esp_err_t flux_device_set_metadata(uint64_t node_id, uint32_t vendor_id,
                                    uint32_t product_id, uint32_t device_type);

/** Remove a device from the registry.  Returns ESP_ERR_NOT_FOUND if absent. */
