/* ── Modbus device registry ──────────────────────────────────────────────── */

#define FLUX_MODBUS_MAX        8
#define FLUX_MODBUS_HOST_MAX   46   /* INET6_ADDRSTRLEN */

/* Synthetic node IDs for Modbus devices. The base is chosen to be:
 *  - far above any operational node ID this controller assigns (those come from
 *    a small incrementing counter starting at 0x0003), so no collision; and
 *  - POSITIVE when interpreted as a signed 64-bit integer (< 0x8000000000000000).
 *    The phone app decodes node_id into a signed Dart int and formats it as hex
 *    for the per-device ?id= query; a value with bit 63 set would go negative and
 *    produce a malformed id the controller can't match (no readings). Keeping the
 *    top bit clear makes the synthetic IDs round-trip correctly through the app. */
#define FLUX_MODBUS_NODE_BASE  0x0100000000000000ULL
#define flux_is_modbus_node(nid)  ((uint64_t)(nid) >= FLUX_MODBUS_NODE_BASE)

/* Persisted config for one Modbus TCP device.  Separate registry from the
 * Matter device table above, but each entry is *also* mirrored into that table
 * (as a flux_DeviceRecord under the same synthetic node_id) so /devices lists it
 * transparently. */
