#pragma once
/*
 * flux_device_kind — what kind of thing a device is, and therefore what its
 * node_id means.
 *
 * A device is identified by the PAIR (kind, node_id): two selection criteria,
 * neither sufficient on its own. node_id is scoped to its kind's namespace, so
 * MATTER node 5 and MODBUS node 5 are different devices and neither has to
 * dodge the other's numbering.
 *
 * This replaces deriving the kind from the magnitude of node_id. Modbus devices
 * used to be handed Matter node IDs above a reserved base
 * (FLUX_MODBUS_NODE_BASE = 0x0100000000000000) and roughly ten call sites each
 * re-derived "is this really a Matter node?" from that constant. The constant
 * was duplicated across three repos, already stale and wrong in one of them,
 * and it forced a cross-repo rule that bit 63 stay clear because the phone app
 * decodes node_id into a signed integer. Carrying the kind explicitly retires
 * the reserved range, the predicate, and the bit-63 rule together.
 *
 * Lives in devices/ rather than matter/ deliberately: the taxonomy spans Matter,
 * Modbus and (later) cloud-API devices, so matter/ must not own it — the same
 * dependency-direction argument as flux_events (ADR-0008).
 *
 * Values are wire-compatible with flux_DeviceKind in the shared proto. Keep them
 * in sync; UNKNOWN is deliberately NOT a synonym for MATTER, so a field nobody
 * set reads as a decode error instead of silently meaning "Matter".
 */
#include <stdint.h>

typedef enum {
    FLUX_DEV_KIND_UNKNOWN = 0,
    FLUX_DEV_KIND_MATTER  = 1,
    FLUX_DEV_KIND_MODBUS  = 2,
    FLUX_DEV_KIND_CLOUD   = 3,
} flux_dev_kind_t;

/** Short lowercase name for logs and the energy CSV's source column. */
static inline const char *flux_dev_kind_str(uint8_t kind)
{
    switch (kind) {
        case FLUX_DEV_KIND_MATTER: return "matter";
        case FLUX_DEV_KIND_MODBUS: return "modbus";
        case FLUX_DEV_KIND_CLOUD:  return "cloud";
        default:                   return "unknown";
    }
}

