/** Short lowercase name for logs and the energy CSV's source column. */
static inline const char *flux_dev_kind_str(uint8_t kind)
{
    switch (kind) {
        case FLUX_DEV_KIND_MATTER: return "matter";
        case FLUX_DEV_KIND_MODBUS: return "modbus";
        case FLUX_DEV_KIND_CLOUD:  return "cloud";
        default:                   return "unknown";
    }
}

