esp_err_t flux_device_remove(uint64_t node_id);

/* ── Energy-role overrides ───────────────────────────────────────────────────
 * The app pushes the user's energy-role assignments (which node is PV / battery
 * / grid) so the energy log can classify correctly, overriding the Modbus-
 * profile heuristic. Stored as one NVS blob + a RAM cache. `cls` values match
 * flux_EnergyClass (0=unknown/none, 1=grid, 2=pv, 3=load, 4=battery). */
#define FLUX_ENERGY_ROLES_MAX 40

typedef struct {
    uint64_t node_id;
    uint8_t  cls;
} flux_EnergyRoleRec;

/** Replace the whole role-override table (persists + updates the RAM cache).
 *  Entries with cls==0 are dropped (treated as "clear"). */
esp_err_t flux_energy_roles_set(const flux_EnergyRoleRec *recs, size_t n);

/** The override class for [node_id], or 0 (unknown) if none. Cheap: RAM lookup
 *  (lazily loaded from NVS on first use). */
uint8_t flux_energy_role_of(uint64_t node_id);

