esp_err_t flux_state_init_factory_partition(void)
{
    /* Initialise the device-registry mutex once, before any task can touch the
     * device table (app_main.cpp calls this at boot). */
    dev_mutex_init();
    mb_mutex_init();
    roles_mutex_init();

    esp_err_t err = nvs_flash_init_partition(FLUX_FACTORY_PART);
    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {
        ESP_LOGW(TAG, "flux_factory NVS erasing and reinitialising (err=%d)", err);
        ESP_ERROR_CHECK(nvs_flash_erase_partition(FLUX_FACTORY_PART));
        err = nvs_flash_init_partition(FLUX_FACTORY_PART);
    }
    if (err != ESP_OK)
        ESP_LOGE(TAG, "flux_factory NVS init failed: %d", err);
    return err;
}

/* ── Fabric ID ────────────────────────────────────────────────────────────── */
