1	/*
2	 * Flux Controller — persistent shared state (NVS)
3	 *
4	 * Pure C module; keeps the CoAP layer free of any C++ / CHIP SDK headers.
5	 *
6	 * Thread-safety: the device registry is read-modify-written from the CoAP
7	 * task (register/rename/remove), the CHIP task (metadata updates,
8	 * reachability checks) and the boot-time sub_restore task, so all registry
9	 * functions serialize on an internal mutex.  See docs/threading.md for the
10	 * full state-ownership map.
11	 */
12	
13	#include "flux_state.h"
14	
15	#include <nvs_flash.h>
16	#include <nvs.h>
17	#include <esp_log.h>
18	#include <esp_random.h>
19	#include <freertos/FreeRTOS.h>
20	#include <freertos/semphr.h>
21	#include <stdatomic.h>
22	#include <string.h>
23	#include <stdio.h>
24	
25	static const char *TAG = "flux_state";
26	
27	/* Forward declaration: the registry mutex initialisers, called once at boot
28	 * from flux_state_init_factory_partition() before any task spins up. */
29	static void dev_mutex_init(void);
30	static void mb_mutex_init(void);
31	static void roles_mutex_init(void);
32	
33	#define NVS_NAMESPACE   "flux"
34	#define NVS_KEY_DATASET "thread_tlv"
35	
36	/* All Flux manufacturing identity (PSK, serial, RCAC private key + cert) lives
37	 * in the flux-exclusive "flux_factory" NVS partition, kept separate from the
38	 * operational "nvs" partition so it survives churn in the operational store.
39	 *
40	 * NB: the RCAC was briefly routed to "matter_factory" (CHIP's chip-factory
41	 * partition) to share the "matter" factory store, but that proved broken: when
42	 * CHIP co-mounts and manages that partition, flux_state's foreign "flux"
43	 * namespace there becomes unreadable after a reboot (the key/cert persist to
44	 * flash but nvs_open can no longer resolve the namespace).  A flux-exclusive
45	 * partition has no such interference, so everything lives in flux_factory.
46	 *
47	 * Mounted by flux_state_init_factory_partition() at boot before any get/set. */
48	#define FLUX_FACTORY_PART   "flux_factory"
49	
50	static void state_migrate_kind_v1(void);
