52	esp_err_t flux_state_init_factory_partition(void)
53	{
54	    /* Initialise the device-registry mutex once, before any task can touch the
55	     * device table (app_main.cpp calls this at boot). */
56	    dev_mutex_init();
57	    mb_mutex_init();
58	    roles_mutex_init();
59	
60	    /* Stamp `kind` onto records written before the field existed. Must run before
61	     * any reader: adding the field changed sizeof(flux_DeviceRecord), and every
62	     * load demands an exact size match, so without this every pre-existing
63	     * device and energy-role override silently disappears. */
64	    state_migrate_kind_v1();
65	
66	    esp_err_t err = nvs_flash_init_partition(FLUX_FACTORY_PART);
67	    if (err == ESP_ERR_NVS_NO_FREE_PAGES || err == ESP_ERR_NVS_NEW_VERSION_FOUND) {
68	        ESP_LOGW(TAG, "flux_factory NVS erasing and reinitialising (err=%d)", err);
69	        ESP_ERROR_CHECK(nvs_flash_erase_partition(FLUX_FACTORY_PART));
70	        err = nvs_flash_init_partition(FLUX_FACTORY_PART);
71	    }
72	    if (err != ESP_OK)
73	        ESP_LOGE(TAG, "flux_factory NVS init failed: %d", err);
74	    return err;
75	}
76	
77	/* ── Fabric ID ────────────────────────────────────────────────────────────── */
78	
79	static atomic_uint_fast64_t s_fabric_id = 0;
80	
81	void flux_state_set_fabric_id(uint64_t id)
82	{
83	    atomic_store(&s_fabric_id, (atomic_uint_fast64_t)id);
84	    ESP_LOGI(TAG, "fabric_id set: %016llx", (unsigned long long)id);
85	}
86	
87	/* ── Raw fabric ID (persisted, generated once at first boot) ─────────────── */
88	
89	#define NVS_KEY_RAW_FABRIC_ID "raw_fab_id"
90	
91	uint64_t flux_state_get_raw_fabric_id(void)
92	{
93	    nvs_handle_t h;
94	    if (nvs_open(NVS_NAMESPACE, NVS_READONLY, &h) != ESP_OK) return 0;
95	    uint64_t id = 0;
96	    nvs_get_u64(h, NVS_KEY_RAW_FABRIC_ID, &id);
97	    nvs_close(h);
98	    return id;
99	}
100	
101	esp_err_t flux_state_ensure_raw_fabric_id(void)
102	{
103	    if (flux_state_get_raw_fabric_id() != 0)
104	        return ESP_OK;
105	
106	    uint64_t id = ((uint64_t)esp_random() << 32) | esp_random();
107	    nvs_handle_t h;
