/*
 * flux_events — device/attribute event bus (producer ↔ transport decoupling).
 *
 * Event *producers* — the Matter controller (subscription reports, lifecycle
 * events) and the Modbus poller (readings) — call flux_events_emit_*(). They do
 * NOT include flux_coap.h. The CoAP transport registers a sink at boot whose
 * callbacks push the event onto the CoAP /events notify queue.
 *
 * This inverts what used to be a matter→coap dependency (the core reaching up
 * into its transport to publish): now both the producers and the transport
 * depend only downward on this neutral module, so the dependency graph is
 * acyclic. See ADR / the architectural review.
 */
#pragma once

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

/* Publish one changed attribute. which: 1 = bool_val, 2 = int_val (int32),
 * 3 = long_val (int64). Safe to call from any task; a no-op until a sink is
 * registered (and the sink itself drops events until its queue exists). */
void flux_events_emit_attr(uint64_t node_id, const char *key,
                           uint8_t which, bool bv, int32_t iv, int64_t lv);

/* Publish a device lifecycle event. event_type is a flux_DeviceEventType cast
 * to uint8_t; error may be NULL for non-error events. */
void flux_events_emit_device(uint64_t node_id, uint8_t event_type, const char *error);

/* Publish a commissioning-progress stage (drives the observable
 * GET /commission/events).  stage is a CHIP CommissioningStage name
 * (StageToString) or a discovery pseudo-stage ("SrpLookup", "Discovering",
 * "Found"); detail may be NULL. Advisory/UI-only — the POST /commission reply
 * stays the source of truth. */
void flux_events_emit_commission(const char *stage, bool failed, const char *detail);

/* Transport sink — implemented and registered once at boot by the CoAP layer
 * (flux_coap_notify_register_sink). Signatures match the emit_* functions. */
typedef struct {
    void (*emit_attr)(uint64_t node_id, const char *key,
                      uint8_t which, bool bv, int32_t iv, int64_t lv);
    void (*emit_device)(uint64_t node_id, uint8_t event_type, const char *error);
