/* flux_modbus_task.c — Modbus poll task. See flux_modbus_task.h. */

#include <string.h>
#include <stdio.h>

#include "freertos/FreeRTOS.h"
#include "freertos/task.h"
#include "esp_log.h"
#include "esp_timer.h"

#include "flux_modbus_task.h"
#include "flux_modbus.h"
#include "flux_modbus_profile.h"
#include "flux_state.h"
#include "flux_hangwatch.h"   /* task-liveness heartbeat (FW-ADR-0013) */
#include "flux_events.h"  /* flux_events_emit_attr / flux_events_emit_device */
#include "flux.pb.h"      /* flux_DeviceEventType_* */

static const char *TAG = "flux_mb_task";

#define DEFAULT_POLL_S        5
#define TASK_TICK_MS          500
#define MAX_BACKOFF_US        (120LL * 1000000) /* cap dead-device retry at 120 s —
                                                 * fewer failed reads = less leak */
#define FAIL_BEFORE_RETRYING  3   /* consecutive fails before flagging RETRYING  */
#define FAIL_BEFORE_RECONNECT 5   /* consecutive fails before tearing the socket */
#define POLL_RETRIES          2   /* immediate in-poll retries before backing off */
#define POLL_RETRY_DELAY_MS   120 /* let a flaky dongle settle between retries     */
/* Hard ceiling on one poll_device() call, retries included. Each attempt can
 * cost several 5 s Modbus response timeouts, so unbounded retries can outlast
 * the task's 30 s hang-watchdog budget and reboot the controller. Keep the whole
 * call comfortably inside that budget. */
#define POLL_BUDGET_US        (12LL * 1000000)

/* One entry per active (opened) device. */
typedef struct {
    uint64_t                   node_id;
    flux_modbus_handle_t       mb;
    flux_modbus_profile_ctx_t *profile;
    char                       host[FLUX_MODBUS_HOST_MAX];  /* for reconnect */
    uint16_t                   port;
    uint8_t                    unit_id;
    bool                       udp;
    int64_t                    poll_us;       /* configured interval */
    int64_t                    next_poll_us;  /* esp_timer clock */
    int                        fail_count;
    bool                       established;    /* connectivity latch */
} mb_active_t;

static mb_active_t   s_active[FLUX_MODBUS_MAX];
static size_t        s_n_active = 0;
static volatile bool s_reload   = true;   /* true → (re)load on next tick */
static TaskHandle_t  s_task     = NULL;

/* ── Active-set (re)build from the persisted registry ─────────────────────── */

static void teardown_active(void)
{
    for (size_t i = 0; i < s_n_active; i++) {
        if (s_active[i].mb)      flux_modbus_close(s_active[i].mb);
        if (s_active[i].profile) flux_modbus_profile_destroy(s_active[i].profile);
    }
    s_n_active = 0;
}

/* Full rebuild: cheap (a handful of devices) and only runs on add/remove, so we
 * favour simplicity/correctness over preserving unaffected devices' sessions. */
static void rebuild_active(void)
{
    teardown_active();

    size_t n = flux_modbus_count();
    for (size_t i = 0; i < n && s_n_active < FLUX_MODBUS_MAX; i++) {
        flux_ModbusRecord rec;
        if (flux_modbus_get(i, &rec) != ESP_OK) continue;

        mb_active_t *a = &s_active[s_n_active];
        memset(a, 0, sizeof(*a));
        a->node_id      = rec.node_id;
        snprintf(a->host, sizeof(a->host), "%s", rec.host);
        a->port         = rec.port;
        a->unit_id      = rec.unit_id;
        a->udp          = (rec.transport == 1);  /* flux_ModbusTransport UDP */
        a->poll_us      = (int64_t)(rec.poll_seconds ? rec.poll_seconds
                                                      : DEFAULT_POLL_S) * 1000000;
        a->next_poll_us = 0;   /* poll asap */

        a->profile = flux_modbus_profile_create((flux_modbus_profile_id_t)rec.profile);
        if (!a->profile) {
            ESP_LOGE(TAG, "profile %u create failed for %016llx",
                     rec.profile, (unsigned long long)rec.node_id);
            continue;
        }
        /* open() tolerates an offline device (connects in the background), so a
         * hard failure here is unusual (OOM / bad config) — skip this entry. */
        if (flux_modbus_open(rec.host, rec.port, rec.unit_id, a->udp, 0, &a->mb) != ESP_OK) {
            flux_modbus_profile_destroy(a->profile);
            continue;
        }
        s_n_active++;
        ESP_LOGI(TAG, "polling %016llx (%s:%u) every %llds",
                 (unsigned long long)rec.node_id, rec.host, rec.port,
                 (long long)(a->poll_us / 1000000));
    }
}

/* ── Per-device poll ──────────────────────────────────────────────────────── */

static void poll_device(mb_active_t *a)
{
    flux_modbus_reading_t rd[FLUX_MODBUS_MAX_READINGS];
    size_t cnt = FLUX_MODBUS_MAX_READINGS;
    esp_err_t err = flux_modbus_profile_poll(a->profile, a->mb, rd, &cnt);

    /* Absorb a transient glitch (a slow/garbled frame, a briefly dropped TCP
     * socket) with a couple of immediate retries before declaring the poll
     * failed. Without this, a single hiccup freezes the last-good reading for a
     * whole backoff window — which is how a PV inverter can appear stuck at one
     * value all day. The failed read already dropped the socket, so the retry
     * reconnects; a persistent outage still falls through to the backoff below. */
    /* A device that has already failed several times running is almost certainly
     * offline; skip the immediate in-poll retries for it. Each retry re-runs the
     * whole profile poll (several Modbus reads, e.g. SunSpec model-chain walk),
     * which only adds failed-read churn — and every failed read leaks an
     * esp-modbus transaction buffer (the internal-RAM leak behind the hangs). */
    /* ESP_ERR_NOT_FOUND means the device answered but is not serving a usable
     * register map (SunSpec discovery found no inverter model, or ran out of its
     * discovery budget) — an inverter in night standby, typically. An immediate
     * retry will get the same answer and costs another full discovery budget, so
     * don't spend it; let the backoff below do the waiting instead. */
    int retries = (a->fail_count >= FAIL_BEFORE_RECONNECT ||
                   err == ESP_ERR_NOT_FOUND) ? 0 : POLL_RETRIES;
    const int64_t poll_deadline = esp_timer_get_time() + POLL_BUDGET_US;
    for (int t = 0; err != ESP_OK && t < retries; t++) {
        /* Never start another attempt we don't have time for: the hang-watchdog
         * aborts the whole controller if this task goes quiet for 30 s. */
        if (esp_timer_get_time() >= poll_deadline) {
            ESP_LOGW(TAG, "%s:%u poll budget exhausted after %d retr%s",
                     a->host, a->port, t, t == 1 ? "y" : "ies");
            break;
        }
        vTaskDelay(pdMS_TO_TICKS(POLL_RETRY_DELAY_MS));
        cnt = FLUX_MODBUS_MAX_READINGS;
        err = flux_modbus_profile_poll(a->profile, a->mb, rd, &cnt);
    }

    int64_t now = esp_timer_get_time();

    if (err == ESP_OK) {
        for (size_t i = 0; i < cnt; i++)
            flux_events_emit_attr(FLUX_DEV_KIND_MODBUS, a->node_id, rd[i].key,
                                  rd[i].which, rd[i].bv, rd[i].iv, rd[i].lv);
        if (!a->established) {
            a->established = true;
            flux_events_emit_device(FLUX_DEV_KIND_MODBUS, a->node_id,
                                    flux_DeviceEventType_DEVICE_EVENT_ESTABLISHED, NULL);
        }
        a->fail_count   = 0;
        a->next_poll_us = now + a->poll_us;
        return;
    }

    if (a->fail_count < 1000) a->fail_count++;

    /* Connectivity hysteresis: only report RETRYING after several *consecutive*
     * failures, so a single slow or garbled read from a flaky inverter dongle
     * doesn't flap the device between SUBSCRIBED and RETRYING in the app. */
    if (a->established && a->fail_count >= FAIL_BEFORE_RETRYING) {
        a->established = false;
        flux_events_emit_device(FLUX_DEV_KIND_MODBUS, a->node_id,
                                flux_DeviceEventType_DEVICE_EVENT_RESUBSCRIBING,
                                esp_err_to_name(err));
    }

    int shift = a->fail_count > 5 ? 5 : a->fail_count;
    int64_t backoff = a->poll_us << shift;
    if (backoff > MAX_BACKOFF_US) backoff = MAX_BACKOFF_US;
    a->next_poll_us = now + backoff;

    /* Reconnect only after repeated failures — a genuinely wedged handle. The
     * raw TCP client already drops and lazily re-opens its socket on each failed
     * read, so a full close/open here is belt-and-suspenders (also resets the UDP
     * socket); doing it every failure would needlessly churn the lwip pool. */
    if (a->fail_count % FAIL_BEFORE_RECONNECT == 0) {
        if (a->mb) flux_modbus_close(a->mb);
        a->mb = NULL;
        if (flux_modbus_open(a->host, a->port, a->unit_id, a->udp, 0, &a->mb) != ESP_OK)
            ESP_LOGW(TAG, "reconnect to %s:%u failed — will retry", a->host, a->port);
    }
}

/* ── Task loop ────────────────────────────────────────────────────────────── */

static void modbus_task(void *arg)
{
    (void)arg;
    /* 30 s budget: the loop ticks every TASK_TICK_MS regardless of per-device
     * backoff, so a healthy task kicks frequently; only a wedged poll (stuck
     * socket) goes silent, and that is exactly what we want to catch. */
    int hb = flux_hangwatch_register("flux_modbus", 30LL * 1000000);
    for (;;) {
        if (s_reload) {
            s_reload = false;
            rebuild_active();
        }
        int64_t now = esp_timer_get_time();
        for (size_t i = 0; i < s_n_active; i++) {
            if (now >= s_active[i].next_poll_us) {
                /* Kick before each device so a sweep over several devices can't
                 * accumulate against a single heartbeat. This can't mask a wedge
                 * *inside* a poll — the kick happens before the blocking work,
                 * so a stuck socket still goes silent and still gets caught. */
                flux_hangwatch_kick(hb);
                poll_device(&s_active[i]);
            }
        }
        flux_hangwatch_kick(hb);
        vTaskDelay(pdMS_TO_TICKS(TASK_TICK_MS));
    }
}

void flux_modbus_task_start(void)
{
    if (s_task) return;
    if (xTaskCreate(modbus_task, "flux_modbus", 6144, NULL, 4, &s_task) != pdPASS) {
        s_task = NULL;
        ESP_LOGE(TAG, "failed to create modbus poll task — polling disabled");
    }
}

void flux_modbus_task_reload(void)
{
    s_reload = true;
}

