void hnd_command_post(coap_resource_t *resource,
                      coap_session_t  *session,
                      const coap_pdu_t *request,
                      const coap_string_t *query,
                      coap_pdu_t       *response)
{
    uint8_t *body; size_t body_len;
    if (!read_body(request, &body, &body_len)) {
        send_status(resource, session, request, response, 1, "no body");
        return;
    }
    flux_DeviceCommand cmd = flux_DeviceCommand_init_zero;
    pb_istream_t is = pb_istream_from_buffer(body, body_len);
    if (!pb_decode(&is, flux_DeviceCommand_fields, &cmd)) {
        free(body);
        send_status(resource, session, request, response, 1, "decode failed");
        return;
    }
    free(body);

    esp_err_t err = flux_send_device_command_args(
        cmd.node_id, cmd.endpoint_id,
        cmd.cluster_id, cmd.command_id,
        cmd.args, cmd.args_count);

    flux_BoolResult br = flux_BoolResult_init_zero;
    br.success = (err == ESP_OK);
    if (err != ESP_OK)
        snprintf(br.error, sizeof(br.error), "err=%d", err);

    uint8_t buf[flux_BoolResult_size];
    pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
    if (!pb_encode(&os, flux_BoolResult_fields, &br)) {
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR);
        return;
    }
    coap_send_proto(resource, session, request, response, buf, os.bytes_written);
}

