#define NVS_KEY_ENERGY_ROLES "energy_roles"

static flux_EnergyRoleRec s_roles[FLUX_ENERGY_ROLES_MAX];
static size_t             s_roles_n;
static bool               s_roles_loaded;
static SemaphoreHandle_t  s_roles_mutex;
static StaticSemaphore_t  s_roles_mutex_buf;

/* Created once at boot by flux_state_init_factory_partition(), like the device
 * and modbus mutexes — never lazily in roles_lock(): the energy-log task
 * (flux_energy_role_of) and the CoAP task (flux_energy_roles_set) both reach it,
 * so a lazy first-use init races and can leave the roles table unguarded. */
static void roles_mutex_init(void)
{
    s_roles_mutex = xSemaphoreCreateMutexStatic(&s_roles_mutex_buf);
}

static void roles_lock(void)
{
    xSemaphoreTake(s_roles_mutex, portMAX_DELAY);
}
static void roles_unlock(void) { xSemaphoreGive(s_roles_mutex); }

static void roles_load_locked(void)
{
    if (s_roles_loaded) return;
    s_roles_loaded = true;
    s_roles_n = 0;
    nvs_handle_t h;
    if (nvs_open(NVS_NAMESPACE, NVS_READONLY, &h) != ESP_OK) return;
    size_t sz = sizeof(s_roles);
    if (nvs_get_blob(h, NVS_KEY_ENERGY_ROLES, s_roles, &sz) == ESP_OK)
        s_roles_n = sz / sizeof(s_roles[0]);
    nvs_close(h);
}

esp_err_t flux_energy_roles_set(const flux_EnergyRoleRec *recs, size_t n)
{
    roles_lock();
    size_t m = 0;
    for (size_t i = 0; i < n && m < FLUX_ENERGY_ROLES_MAX; i++) {
        if (recs[i].cls == 0) continue;   /* 0 = clear/none */
        s_roles[m++] = recs[i];
    }
    s_roles_n      = m;
    s_roles_loaded = true;

    nvs_handle_t h;
    esp_err_t err = nvs_open(NVS_NAMESPACE, NVS_READWRITE, &h);
    if (err == ESP_OK) {
        if (m == 0) {
            err = nvs_erase_key(h, NVS_KEY_ENERGY_ROLES);
            if (err == ESP_ERR_NVS_NOT_FOUND) err = ESP_OK;
        } else {
            err = nvs_set_blob(h, NVS_KEY_ENERGY_ROLES, s_roles, m * sizeof(s_roles[0]));
        }
        if (err == ESP_OK) err = nvs_commit(h);
        nvs_close(h);
    }
    roles_unlock();
    return err;
}

uint8_t flux_energy_role_of(uint8_t kind, uint64_t node_id)
{
    roles_lock();
    roles_load_locked();
    uint8_t cls = 0;
    for (size_t i = 0; i < s_roles_n; i++) {
        if (s_roles[i].node_id == node_id && s_roles[i].kind == kind) {
            cls = s_roles[i].cls;
            break;
        }
    }
    roles_unlock();
    return cls;
}

