    size_t n = sz / sizeof(role_record_v0_t);
    if (n > ROLES_MAX_MIGRATE) n = ROLES_MAX_MIGRATE;
    role_record_v0_t v0[ROLES_MAX_MIGRATE];
    size_t rd = sz;
    if (nvs_get_blob(h, NVS_KEY_ENERGY_ROLES, v0, &rd) != ESP_OK) {
        nvs_close(h);
        return;
    }

