    role_record_v1_t roles[ROLES_MAX_MIGRATE];
    size_t n_roles = 0;
    nvs_handle_t rh;
    if (nvs_open(NVS_NAMESPACE, NVS_READWRITE, &rh) == ESP_OK) {
        size_t sz = sizeof(roles);
        if (nvs_get_blob(rh, NVS_KEY_ENERGY_ROLES, roles, &sz) == ESP_OK)
            n_roles = sz / sizeof(roles[0]);
        nvs_close(rh);
    }

    nvs_handle_t h;
    if (nvs_open(DEV_NS, NVS_READWRITE, &h) != ESP_OK) return;

    uint8_t cnt = 0;
    nvs_get_u8(h, DEV_CNT, &cnt);
    int converted = 0, with_role = 0;
    for (size_t i = 0; i < cnt; i++) {
        char key[16];
        if (dev_key(key, sizeof(key), i) != ESP_OK) continue;
        dev_record_v1_t v1;
        size_t sz = sizeof(v1);
        if (nvs_get_blob(h, key, &v1, &sz) != ESP_OK || sz != sizeof(v1)) continue;

        flux_DeviceRecord v2 = {
            .node_id     = v1.node_id,
            .kind        = v1.kind,
            .vendor_id   = v1.vendor_id,
            .product_id  = v1.product_id,
            .device_type = v1.device_type,
            .room_id     = FLUX_ROOM_NONE,  /* rooms were phone-side; the app
                                             * uploads its layout once */
            .energy_cls  = 0,
        };
        snprintf(v2.name, sizeof(v2.name), "%s", v1.name);
        for (size_t r = 0; r < n_roles; r++) {
            if (roles[r].node_id == v1.node_id && roles[r].kind == v1.kind) {
                v2.energy_cls = roles[r].cls;
                with_role++;
                break;
            }
        }
        if (nvs_set_blob(h, key, &v2, sizeof(v2)) == ESP_OK) converted++;
    }
    nvs_commit(h);
    nvs_close(h);

    /* Only now drop the blob — if we die before this, the migration re-runs from
     * a still-intact source rather than from a half-erased one. */
    if (nvs_open(NVS_NAMESPACE, NVS_READWRITE, &rh) == ESP_OK) {
        if (nvs_erase_key(rh, NVS_KEY_ENERGY_ROLES) == ESP_OK) nvs_commit(rh);
        nvs_close(rh);
    }
    ESP_LOGI(TAG, "v2: %d/%u record(s) gained room+energy class, %d role(s) folded in",
             converted, (unsigned)cnt, with_role);
}

static void state_migrate(void)
{
    nvs_handle_t h;
    uint8_t ver = 0;
    if (nvs_open(DEV_NS, NVS_READONLY, &h) == ESP_OK) {
        nvs_get_u8(h, DEV_VER_KEY, &ver);
        nvs_close(h);
    }
    if (ver >= STATE_META_V2) return;

    if (ver < STATE_KIND_V1) {
        migrate_roles_v1();     /* roles first: keyed off the same legacy base */
        migrate_devices_v1();
    }
    migrate_devices_v2();

    /* One version stamp for the whole chain, written last: a power cut mid-way
     * leaves the version behind, so the surviving steps simply re-run. Each is
     * a straight rewrite of every record, so re-running is harmless. */
    if (nvs_open(DEV_NS, NVS_READWRITE, &h) == ESP_OK) {
        nvs_set_u8(h, DEV_VER_KEY, STATE_META_V2);
        nvs_commit(h);
        nvs_close(h);
    }
}

