new = r'''/* ── Handler: GET /rooms ─────────────────────────────────────────────────── */

void hnd_rooms_get(coap_resource_t *resource,
                   coap_session_t  *session,
                   const coap_pdu_t *request,
                   const coap_string_t *query,
                   coap_pdu_t       *response)
{
    (void)query;
    flux_RoomList list = flux_RoomList_init_zero;
    flux_RoomRec recs[FLUX_ROOMS_MAX];
    size_t n = flux_rooms_get_all(recs, FLUX_ROOMS_MAX);
    for (size_t i = 0; i < n; i++) {
        list.rooms[i].id = recs[i].id;
        snprintf(list.rooms[i].name, sizeof(list.rooms[i].name), "%s", recs[i].name);
    }
    list.rooms_count = (pb_size_t)n;

    uint8_t buf[flux_RoomList_size];
    pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
    if (!pb_encode(&os, flux_RoomList_fields, &list)) {
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR);
        return;
    }
    coap_send_proto(resource, session, request, response, buf, os.bytes_written);
}

/* ── Handler: PUT /rooms ─────────────────────────────────────────────────── */

/* Full replace, and it answers with the resulting list rather than a status:
 * ids for newly created rooms are assigned here, so the caller has no other way
 * to learn them. */
void hnd_rooms_put(coap_resource_t *resource,
                   coap_session_t  *session,
                   const coap_pdu_t *request,
                   const coap_string_t *query,
                   coap_pdu_t       *response)
{
    (void)query;
    uint8_t *body; size_t body_len;
    if (!read_body(request, &body, &body_len)) {
        send_status(resource, session, request, response, 1, "no body");
        return;
    }
    flux_RoomList list = flux_RoomList_init_zero;
    pb_istream_t is = pb_istream_from_buffer(body, body_len);
    bool ok = pb_decode(&is, flux_RoomList_fields, &list);
    free(body);
    if (!ok) {
        send_status(resource, session, request, response, 1, "decode failed");
        return;
    }

    flux_RoomRec recs[FLUX_ROOMS_MAX];
    size_t n = list.rooms_count > FLUX_ROOMS_MAX ? FLUX_ROOMS_MAX : list.rooms_count;
    for (size_t i = 0; i < n; i++) {
        recs[i].id = (uint16_t)list.rooms[i].id;
        snprintf(recs[i].name, sizeof(recs[i].name), "%s", list.rooms[i].name);
    }
    esp_err_t err = flux_rooms_set_all(recs, n);
    if (err != ESP_OK) {
        send_status_ex(resource, session, request, response,
                       COAP_RESPONSE_CODE_INTERNAL_ERROR, 1, "nvs error");
        return;
    }

    /* Echo back with the assigned ids filled in. */
    for (size_t i = 0; i < n; i++) list.rooms[i].id = recs[i].id;
    list.rooms_count = (pb_size_t)n;

    uint8_t buf[flux_RoomList_size];
    pb_ostream_t os = pb_ostream_from_buffer(buf, sizeof(buf));
    if (!pb_encode(&os, flux_RoomList_fields, &list)) {
        coap_pdu_set_code(response, COAP_RESPONSE_CODE_INTERNAL_ERROR);
        return;
    }
    ESP_LOGI(TAG, "PUT /rooms: %u room(s)", (unsigned)n);
    coap_send_proto(resource, session, request, response, buf, os.bytes_written);
}

/* ── Handler: POST /devices/meta ─────────────────────────────────────────── */

/* Partial update of the metadata the controller owns for a device. Only the
 * fields actually present are written — 0 is a meaningful value for both
 * room_id (No Room) and energy_class (no override), so "absent" and "zero" must
 * stay distinguishable, which is why DeviceMeta marks them `optional`. */
void hnd_device_meta_post(coap_resource_t *resource,
                          coap_session_t  *session,
                          const coap_pdu_t *request,
                          const coap_string_t *query,
                          coap_pdu_t       *response)
{
    (void)query;
    uint8_t *body; size_t body_len;
    if (!read_body(request, &body, &body_len)) {
        send_status(resource, session, request, response, 1, "no body");
        return;
    }
    flux_DeviceMeta meta = flux_DeviceMeta_init_zero;
    pb_istream_t is = pb_istream_from_buffer(body, body_len);
    bool ok = pb_decode(&is, flux_DeviceMeta_fields, &meta);
    free(body);
    if (!ok) {
        send_status(resource, session, request, response, 1, "decode failed");
        return;
    }

    /* kind may be omitted by a caller that only knows the node id; resolve it
     * from the registry rather than assuming MATTER. */
    uint8_t kind = meta.kind ? (uint8_t)meta.kind
                             : flux_device_kind_of_node(meta.node_id);
    if (flux_device_get_by(kind, meta.node_id, NULL) == ESP_ERR_NOT_FOUND) {
        send_status_ex(resource, session, request, response,
                       COAP_RESPONSE_CODE_NOT_FOUND, 1, "unknown device");
        return;
    }

    esp_err_t err = ESP_OK;
    if (err == ESP_OK && meta.has_name)
        err = flux_device_set_name(kind, meta.node_id, meta.name);
    if (err == ESP_OK && meta.has_room_id)
        err = flux_device_set_room(kind, meta.node_id, (uint16_t)meta.room_id);
    if (err == ESP_OK && meta.has_energy_class)
        err = flux_device_set_energy_class(kind, meta.node_id,
                                           (uint8_t)meta.energy_class);
    if (err != ESP_OK) {
        send_status_ex(resource, session, request, response,
                       COAP_RESPONSE_CODE_INTERNAL_ERROR, 1, "nvs error");
        return;
    }

    ESP_LOGI(TAG, "POST /devices/meta: %016llx kind=%u%s%s%s",
             (unsigned long long)meta.node_id, (unsigned)kind,
             meta.has_name ? " name" : "", meta.has_room_id ? " room" : "",
             meta.has_energy_class ? " energy" : "");
    send_status(resource, session, request, response, 0, "ok");
}
